async function init() {
  applyAtmosphere(currentAtmospherePref);
  // Auto-check time of day every 60s if mode is 'auto'
  setInterval(() => {
    if (currentAtmospherePref === 'auto') {
      applyAtmosphere('auto');
    }
  }, 60000);

  // Start fetching feed posts in parallel with auth verification for instant login & boot
  const postsPromise = loadPosts();
  await initAuth();

  const gateEmail = sessionStorage.getItem('slant_gate_active_email');
  if (gateEmail) {
    openPrivatePreviewGateModal(gateEmail);
  }
  const deepPostId = typeof getDeepLinkedPostId === 'function' ? getDeepLinkedPostId() : null;
  const hasPublicDeepLink = typeof hasPublicDeepLinkInUrl === 'function' ? hasPublicDeepLinkInUrl() : Boolean(deepPostId);
  if (!currentUser && !hasPublicDeepLink) {
    dismissInitialFeedLoader(true);
    renderLoginPostsPreview();
  }
  await postsPromise;
  setupEventListeners();
  setupPullToRefresh();
  await checkDeepLink();
  setupRealtimeSubscription();
  checkIncomingShareTarget();
  if (currentUser && currentUser.email) {
    loadFamilyCastProfile(true);
  }
}

