async function submitUserCreditRequest() {
  if (!currentUser || !currentUser.email) {
    openAuthModal('Please sign in first to request more visual credits.');
    return;
  }
  const btn = document.getElementById('userCreditRequestSubmitBtn') || document.getElementById('userRequestCreditsSubmitBtn');
  const noteInput = document.getElementById('userCreditRequestReasonInput') || document.getElementById('userCreditRequestNoteInput');
  const statusMsg = document.getElementById('userCreditRequestStatusMsg');
  const reason = (noteInput?.value || '').trim();
  const origHtml = btn ? btn.innerHTML : 'Request +Credits';

  if (btn) {
    btn.disabled = true;
    btn.innerHTML = 'Sending...';
  }

  try {
    const resp = await fetch('/api/whitelist', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'request_credits',
        email: currentUser.email,
        name: getUserDisplayName(),
        avatar: getUserAvatarUrl(),
        reason: reason || 'Requesting additional visual art generation credits'
      })
    });
    if (resp.ok) {
      if (noteInput) noteInput.value = '';
      if (statusMsg) {
        statusMsg.style.display = 'block';
        statusMsg.style.color = '#10B981';
        statusMsg.textContent = '✓ Request sent to Admin! Your bonus visual credits will appear here as soon as approved.';
      }
      showTemporaryToast('⚡ Credit request sent to curator admin!');
    } else {
      throw new Error('Could not submit request');
    }
  } catch (e) {
    if (statusMsg) {
      statusMsg.style.display = 'block';
      statusMsg.style.color = '#EF4444';
      statusMsg.textContent = '⚠️ Network error sending request. Please try again.';
    }
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = origHtml;
    }
  }
}

async function shareSlantCommunityInvite() {
  const shareUrl = 'https://www.slant.today';
  const shareTitle = 'Slant — Every Thought Deserves a Frame';
  const shareText = `Hey! Came across Slant (https://www.slant.today) — it’s a quiet space that turns reading notes and everyday thoughts into illustrated, print-style editorial cards. Thought you'd appreciate it, check it out.`;

  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(shareText).catch(() => {});
    }
  } catch (_) {}

  if (!_cachedInviteGifFile) {
    await preloadAnimatedInviteLogoFiles();
  }

  if (navigator.share) {
    const candidateFiles = [_cachedInviteGifFile].filter(Boolean);
    for (const logoFile of candidateFiles) {
      try {
        const payloadWithText = {
          files: [logoFile],
          title: shareTitle,
          text: shareText
        };
        if (!navigator.canShare || navigator.canShare(payloadWithText)) {
          await navigator.share(payloadWithText);
          return;
        }
        if (navigator.canShare && navigator.canShare({ files: [logoFile] })) {
          await navigator.share({
            files: [logoFile],
            title: shareTitle,
            text: shareText
          });
          return;
        }
      } catch (err) {
        if (err && err.name === 'AbortError') return;
      }
    }

    try {
      await navigator.share({
        title: shareTitle,
        text: shareText,
        url: shareUrl
      });
      return;
    } catch (err) {
      if (err && err.name === 'AbortError') return;
    }
  }
  copyPersonalInviteMessage();
}

