function syncBookmarkButtonsForPost(postId) {
  const sId = String(postId || '');
  if (!sId) return;
  const isNowSaved = savedPostIds.has(sId);
  document.querySelectorAll(`#bookmark-btn-${CSS.escape(sId)}, .bookmark-btn[data-bookmark-post="${CSS.escape(sId)}"]`).forEach(btn => {
    btn.classList.toggle('is-saved', isNowSaved);
    btn.setAttribute('title', isNowSaved ? 'Saved — Manage Buckets' : 'Save to Bucket');
    const svg = btn.querySelector('svg');
    if (svg) {
      svg.setAttribute('fill', isNowSaved ? '#F59E0B' : 'none');
      svg.setAttribute('stroke', isNowSaved ? '#F59E0B' : 'currentColor');
    }
  });
}

function closeAllSaveBucketPopovers() {
  document.querySelectorAll('.save-bucket-popover.show').forEach(pop => {
    pop.classList.remove('show');
  });
}
window.closeAllSaveBucketPopovers = closeAllSaveBucketPopovers;

function buildSaveBucketPopoverInnerHtml(postId) {
  const sId = String(postId || '');
  if (!Array.isArray(saveBuckets) || saveBuckets.length === 0) {
    saveBuckets = loadSaveBucketsFromStorage();
  }
  const isSavedAnywhere = savedPostIds.has(sId);

  const itemsHtml = saveBuckets.map(bucket => {
    const bIds = Array.isArray(bucket.postIds) ? bucket.postIds : [];
    const isChecked = bIds.includes(sId);
    const count = bIds.length;
    return `
      <button type="button"
              class="save-bucket-item ${isChecked ? 'is-checked' : ''}"
              onclick="togglePostInSaveBucket(event, '${escapeHtml(sId)}', '${escapeHtml(bucket.id)}')">
        <span class="save-bucket-check" aria-hidden="true">${isChecked ? '✓' : ''}</span>
        <span class="save-bucket-icon">${escapeHtml(bucket.icon || '📁')}</span>
        <span class="save-bucket-name">${escapeHtml(bucket.name)}</span>
        <span class="save-bucket-count">${count}</span>
      </button>
    `;
  }).join('');

  return `
    <div class="save-bucket-popover-header" onclick="event.stopPropagation()">
      <span class="save-bucket-popover-title">🔖 Save to Bucket</span>
      <div class="save-bucket-popover-actions">
        ${isSavedAnywhere ? `
          <button type="button" class="save-bucket-unsave-all-btn" onclick="removePostFromAllSaveBuckets(event, '${escapeHtml(sId)}')" title="Remove from all buckets">Remove</button>
        ` : ''}
        <button type="button" class="save-bucket-close-btn" onclick="event.stopPropagation(); closeAllSaveBucketPopovers()" title="Close">✕</button>
      </div>
    </div>
    <div class="save-bucket-list" onclick="event.stopPropagation()">
      ${itemsHtml}
    </div>
    <form class="save-bucket-create-form" onsubmit="createSaveBucketAndAddPost(event, '${escapeHtml(sId)}')" onclick="event.stopPropagation()">
      <input type="text"
             class="save-bucket-create-input"
             id="save-bucket-input-${escapeHtml(sId)}"
             placeholder="+ Create bucket & save..."
             maxlength="34"
             autocomplete="off"
             onclick="event.stopPropagation()">
      <button type="submit" class="save-bucket-create-btn">Save</button>
    </form>
  `;
}

function refreshOpenSaveBucketPopover(postId) {
  const sId = String(postId || '');
  const pop = document.getElementById(`save-bucket-popover-${sId}`);
  if (pop && pop.classList.contains('show')) {
    pop.innerHTML = buildSaveBucketPopoverInnerHtml(sId);
  }
}

function togglePostInSaveBucket(event, postId, bucketId) {
  if (event) {
    event.stopPropagation();
    event.preventDefault();
  }
  const sId = String(postId || '');
  const bId = String(bucketId || '');
  const bucket = Array.isArray(saveBuckets) ? saveBuckets.find(b => String(b.id) === bId) : null;
  if (!bucket || !sId) return;

  if (!Array.isArray(bucket.postIds)) bucket.postIds = [];
  const idx = bucket.postIds.indexOf(sId);
  let added = false;
  if (idx !== -1) {
    bucket.postIds.splice(idx, 1);
  } else {
    bucket.postIds.push(sId);
    added = true;
  }

  persistSaveBuckets(true);
  syncBookmarkButtonsForPost(sId);
  refreshOpenSaveBucketPopover(sId);
  updateAuthUI();

  if (added) {
    showTemporaryToast(`${bucket.icon || '🔖'} Saved to "${bucket.name}"`);
  } else {
    showTemporaryToast(`Removed from "${bucket.name}"`);
  }

  if (currentFilter === 'saved') {
    renderFeed();
  }
}
window.togglePostInSaveBucket = togglePostInSaveBucket;

function createSaveBucketAndAddPost(event, postId) {
  if (event) {
    event.stopPropagation();
    event.preventDefault();
  }
  const sId = String(postId || '');
  const inp = document.getElementById(`save-bucket-input-${sId}`);
  const rawName = inp ? inp.value.trim() : '';

  if (!rawName) {
    // If input is empty, save directly to default Reading List bucket
    const defaultBucket = saveBuckets[0];
    if (defaultBucket) {
      if (!defaultBucket.postIds.includes(sId)) {
        defaultBucket.postIds.push(sId);
        persistSaveBuckets(true);
        syncBookmarkButtonsForPost(sId);
        refreshOpenSaveBucketPopover(sId);
        updateAuthUI();
      }
      showTemporaryToast(`${defaultBucket.icon || '🔖'} Saved to "${defaultBucket.name}"`);
      closeAllSaveBucketPopovers();
    }
    return;
  }

  let bucket = saveBuckets.find(b => b && b.name.toLowerCase() === rawName.toLowerCase());
  const isNewBucket = !bucket;
  if (!bucket) {
    const slug = rawName.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '') || ('b_' + Date.now());
    bucket = {
      id: `bucket_${slug}_${Date.now().toString(36).slice(-3)}`,
      name: rawName,
      icon: '📁',
      postIds: []
    };
    saveBuckets.push(bucket);
  }

  if (!bucket.postIds.includes(sId)) {
    bucket.postIds.push(sId);
  }

  persistSaveBuckets(true);
  syncBookmarkButtonsForPost(sId);
  refreshOpenSaveBucketPopover(sId);
  updateAuthUI();

  showTemporaryToast(isNewBucket ? `✨ Created "${bucket.name}" & saved story!` : `📁 Saved to "${bucket.name}"`);

  if (currentFilter === 'saved') {
    renderFeed();
  }
}
window.createSaveBucketAndAddPost = createSaveBucketAndAddPost;

function removePostFromAllSaveBuckets(event, postId) {
  if (event) {
    event.stopPropagation();
    event.preventDefault();
  }
  const sId = String(postId || '');
  if (Array.isArray(saveBuckets)) {
    saveBuckets.forEach(b => {
      if (b && Array.isArray(b.postIds)) {
        b.postIds = b.postIds.filter(id => id !== sId);
      }
    });
  }
  persistSaveBuckets(true);
  syncBookmarkButtonsForPost(sId);
  closeAllSaveBucketPopovers();
  updateAuthUI();
  showTemporaryToast('Removed from Saved Stories');

  if (currentFilter === 'saved') {
    renderFeed();
  }
}
window.removePostFromAllSaveBuckets = removePostFromAllSaveBuckets;

function toggleBookmark(event, postId) {
  if (event) {
    event.stopPropagation();
    event.preventDefault();
  }

  if (!currentUser) {
    openAuthModal('Sign in to save stories to your bucket lists on Slant.');
    return;
  }

  const sId = String(postId || '');
  if (!sId) return;

  const btn = (event && event.currentTarget) ? event.currentTarget : document.getElementById(`bookmark-btn-${sId}`);
  if (!btn) return;

  let wrap = btn.closest('.bookmark-action-wrap');
  if (!wrap) {
    wrap = btn.parentElement;
  }
  if (!wrap) return;

  let pop = document.getElementById(`save-bucket-popover-${sId}`);
  if (!pop) {
    pop = document.createElement('div');
    pop.className = 'save-bucket-popover';
    pop.id = `save-bucket-popover-${sId}`;
    wrap.appendChild(pop);
  }

  const isAlreadyShowing = pop.classList.contains('show');
  if (typeof closeAllPostMenus === 'function') closeAllPostMenus();
  closeAllSaveBucketPopovers();

  if (isAlreadyShowing) {
    return;
  }

  // If this post has never been saved to any bucket yet, pre-save it into "Reading List" OR let user pick/create?
  // Wait: user asked "When save option is clicked on posts lower right corner, pop up a list of existing save bucket lists.. with small prompt right in that to create one and save to it..."
  pop.innerHTML = buildSaveBucketPopoverInnerHtml(sId);
  pop.classList.add('show');
}

function showTemporaryToast(message, duration = 2800, isHtml = false, onClickHandler = null) {
  let toast = document.getElementById('slantToast') || document.getElementById('editourToast');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'slantToast';
    toast.style.cssText = `
      position: fixed;
      bottom: 24px;
      left: 50%;
      transform: translateX(-50%) translateY(20px);
      background: var(--bg-surface, #1E293B);
      color: var(--text-primary, #F8FAFC);
      border: 1px solid var(--border-subtle, rgba(255,255,255,0.12));
      box-shadow: 0 10px 30px rgba(0,0,0,0.4);
      padding: 10px 18px;
      border-radius: 999px;
      font-size: 13px;
      font-weight: 600;
      z-index: 9999;
      opacity: 0;
      transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
      display: flex;
      align-items: center;
      gap: 8px;
      white-space: nowrap;
      max-width: 90vw;
      box-sizing: border-box;
    `;
    document.body.appendChild(toast);
  }

  if (isHtml) {
    toast.innerHTML = message;
  } else {
    toast.textContent = message;
  }

  if (typeof onClickHandler === 'function') {
    toast.style.pointerEvents = 'auto';
    toast.style.cursor = 'pointer';
    toast.onclick = () => {
      onClickHandler();
      toast.style.opacity = '0';
      toast.style.transform = 'translateX(-50%) translateY(20px)';
    };
  } else {
    toast.style.pointerEvents = 'none';
    toast.style.cursor = 'default';
    toast.onclick = null;
  }

  toast.style.opacity = '1';
  toast.style.transform = 'translateX(-50%) translateY(0)';
  
  clearTimeout(toast._timeout);
  toast._timeout = setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateX(-50%) translateY(20px)';
    toast.onclick = null;
  }, duration);
}

// ============================================================
// CLIENT-SIDE AES-256-GCM DIARY ENCRYPTION ENGINE
// ============================================================
const _chronicleAesKeyCache = new Map();
const _upgradedChronicleIds = new Set();

function resolveChronicleKeySeed() {
  const curEmail = (currentUser?.email || '').trim().toLowerCase();
  if (!curEmail) return null;
  if (curEmail === 'shridharoct16@gmail.com') {
    return 'slant_curator_shridhar_vault';
  }
  return curEmail;
}

async function getChronicleCryptoKey(seedStr) {
  if (!seedStr) return null;
  const normalizedSeed = String(seedStr).trim().toLowerCase();
  if (_chronicleAesKeyCache.has(normalizedSeed)) {
    return _chronicleAesKeyCache.get(normalizedSeed);
  }
  const encoder = new TextEncoder();
  const keyMaterial = await window.crypto.subtle.importKey(
    'raw',
    encoder.encode(`slant_diary_aes256_v1::${normalizedSeed}`),
    { name: 'PBKDF2' },
    false,
    ['deriveKey']
  );
  const derivedKey = await window.crypto.subtle.deriveKey(
    {
      name: 'PBKDF2',
      salt: encoder.encode(`slant_chronicle_salt_2026::${normalizedSeed}`),
      iterations: 50000,
      hash: 'SHA-256'
    },
    keyMaterial,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt']
  );
  _chronicleAesKeyCache.set(normalizedSeed, derivedKey);
  return derivedKey;
}

function uint8ToBase64(bytes) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return window.btoa(binary);
}

function base64ToUint8(b64) {
  const binary = window.atob(b64);
  const len = binary.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

async function encryptChroniclePostForCloud(postObj) {
  if (!postObj || !isPostChronicleDiary(postObj) || !window.crypto?.subtle) {
    return postObj;
  }
  const copy = { ...postObj };
  if (currentUser?.email) {
    copy.userEmail = currentUser.email.trim().toLowerCase();
  }
  // If already encrypted and not decrypted in memory, return as-is
  if (typeof copy.encryptedDiaryPayload === 'string' && copy.encryptedDiaryPayload.startsWith('ENC:v1:') && !copy._diaryDecrypted) {
    copy.illustrationUrl = '';
    copy.aiIllustrationUrl = '';
    return copy;
  }
  try {
    const seed = resolveChronicleKeySeed();
    if (!seed) return postObj;
    const key = await getChronicleCryptoKey(seed);
    if (!key) return postObj;
    const secretBundle = {
      adaptedHeadline: copy.adaptedHeadline || '',
      originalHeadline: copy.originalHeadline || '',
      summary: copy.summary || '',
      broadsheetObservation: copy.broadsheetObservation || '',
      curatorTake: copy.curatorTake || '',
      polishedCuratorTake: copy.polishedCuratorTake || '',
      creatorOpinion: copy.creatorOpinion || '',
      userSlantTake: copy.userSlantTake || '',
      whyItMatters: copy.whyItMatters || '',
      illustrationUrl: copy.illustrationUrl || '',
      aiIllustrationUrl: copy.aiIllustrationUrl || '',
      contextBullets: Array.isArray(copy.contextBullets) ? copy.contextBullets : [],
      keyTakeaways: Array.isArray(copy.keyTakeaways) ? copy.keyTakeaways : [],
      articleExcerpts: Array.isArray(copy.articleExcerpts) ? copy.articleExcerpts : [],
      resolvedArticleExcerpts: Array.isArray(copy.resolvedArticleExcerpts) ? copy.resolvedArticleExcerpts : [],
      chronicleMoments: Array.isArray(copy.chronicleMoments) ? copy.chronicleMoments : (copy.generationInputs?.chronicleMoments || []),
      chronicleReflections: Array.isArray(copy.chronicleReflections) ? copy.chronicleReflections : (copy.generationInputs?.chronicleReflections || []),
      reflectionFeedback: copy.reflectionFeedback || null,
      contextProvided: copy.contextProvided || '',
      sourceContext: copy.sourceContext || '',
      illustrationPrompt: copy.illustrationPrompt || '',
      headlineOptions: Array.isArray(copy.headlineOptions) ? copy.headlineOptions : [],
      generationInputs: copy.generationInputs ? { ...copy.generationInputs } : { chronicleMode: true, innerVoiceSubMode: 'chronicle' }
    };

    const iv = window.crypto.getRandomValues(new Uint8Array(12));
    const encodedPlaintext = new TextEncoder().encode(JSON.stringify(secretBundle));
    const cipherBuffer = await window.crypto.subtle.encrypt(
      { name: 'AES-GCM', iv },
      key,
      encodedPlaintext
    );
    const ivB64 = uint8ToBase64(iv);
    const cipherB64 = uint8ToBase64(new Uint8Array(cipherBuffer));

    copy.encryptedDiaryPayload = `ENC:v1:${ivB64}:${cipherB64}`;
    copy.isEncryptedDiary = true;
    copy.isDiaryDraftOnly = Boolean(postObj.isDiaryDraftOnly);
    copy.isDiary = !copy.isDiaryDraftOnly;
    copy.chronicleMode = true;
    copy.innerVoiceSubMode = 'chronicle';
    delete copy._diaryDecrypted;

    // Redact all plaintext personal diary text & poster URLs from the cloud/database row
    copy.adaptedHeadline = '🔒 Encrypted Daily Chronicle';
    copy.originalHeadline = copy.originalHeadline && /^\d{1,2}\s+[A-Za-z]+/.test(copy.originalHeadline) ? copy.originalHeadline : 'Personal Diary';
    copy.summary = '🔒 AES-256 End-to-End Encrypted Personal Diary Entry';
    copy.illustrationUrl = '';
    copy.aiIllustrationUrl = '';
    copy.broadsheetObservation = '';
    copy.curatorTake = '';
    copy.polishedCuratorTake = '';
    copy.creatorOpinion = '';
    copy.userSlantTake = '';
    copy.whyItMatters = '';
    copy.contextBullets = [];
    copy.keyTakeaways = [];
    copy.articleExcerpts = [];
    copy.resolvedArticleExcerpts = [];
    copy.chronicleMoments = [];
    copy.chronicleReflections = [];
    copy.reflectionFeedback = null;
    copy.contextProvided = '';
    copy.sourceContext = '';
    copy.illustrationPrompt = '';
    copy.headlineOptions = [];
    copy.generationInputs = {
      chronicleMode: true,
      innerVoiceSubMode: 'chronicle',
      isEncryptedDiary: true
    };
    return copy;
  } catch (err) {
    console.warn('Chronicle encryption notice:', err);
    return postObj;
  }
}

async function decryptChroniclePostInPlace(post) {
  if (!post || typeof post.encryptedDiaryPayload !== 'string' || !post.encryptedDiaryPayload.startsWith('ENC:v1:')) {
    return false;
  }
  if (post._diaryDecrypted) return true;
  if (!currentUser || !isPostOwnedByCurrentUser(post)) return false;
  if (!window.crypto?.subtle) return false;

  try {
    const parts = post.encryptedDiaryPayload.split(':');
    if (parts.length < 4) return false;
    const iv = base64ToUint8(parts[2]);
    const cipherBytes = base64ToUint8(parts.slice(3).join(':'));
    const seed = resolveChronicleKeySeed();
    if (!seed) return false;
    const key = await getChronicleCryptoKey(seed);
    if (!key) return false;
    const plainBuffer = await window.crypto.subtle.decrypt(
      { name: 'AES-GCM', iv },
      key,
      cipherBytes
    );
    const decodedJson = new TextDecoder().decode(plainBuffer);
    const bundle = JSON.parse(decodedJson);
    if (bundle && typeof bundle === 'object') {
      const preservedDraftFlag = Boolean(post.isDiaryDraftOnly);
      const preservedDiaryFlag = post.isDiary;
      Object.assign(post, bundle);
      if (!post.illustrationUrl && !post.isTextOnly && post.id) {
        post.illustrationUrl = `${SUPABASE_URL}/storage/v1/object/public/posters/${post.id}.webp`;
        post.aiIllustrationUrl = post.illustrationUrl;
      }
      post.isDiaryDraftOnly = preservedDraftFlag;
      post.isDiary = preservedDraftFlag ? false : (preservedDiaryFlag !== undefined ? preservedDiaryFlag : true);
      post.isEncryptedDiary = true;
      post._diaryDecrypted = true;
      return true;
    }
  } catch (err) {
    console.warn('Chronicle decryption notice for post', post.id, err);
  }
  return false;
}

async function decryptChroniclePostsInPlace(postsArray) {
  if (!Array.isArray(postsArray) || postsArray.length === 0) return false;
  let anyDecrypted = false;
  for (const raw of postsArray) {
    const p = raw?.data || raw;
    if (p && typeof p.encryptedDiaryPayload === 'string' && p.encryptedDiaryPayload.startsWith('ENC:v1:') && !p._diaryDecrypted) {
      const ok = await decryptChroniclePostInPlace(p);
      if (ok) anyDecrypted = true;
    }
  }
  return anyDecrypted;
}

async function decryptAllOwnedChroniclePosts() {
  if (!Array.isArray(allPosts) || allPosts.length === 0) return;
  const anyDecrypted = await decryptChroniclePostsInPlace(allPosts);
  if (anyDecrypted) {
    if (currentFilter === 'diary' || currentFilter === 'daily_chronicles') {
      renderFeed();
    }
    const diaryModal = document.getElementById('diaryCalendarModal');
    if (diaryModal && diaryModal.style.display !== 'none' && typeof renderDiaryCalendarModal === 'function') {
      renderDiaryCalendarModal();
    }
  }
  upgradeUnencryptedOwnedChronicles();
}

async function upgradeUnencryptedOwnedChronicles() {
  if (!currentUser || !Array.isArray(allPosts) || allPosts.length === 0) return;
  const unencryptedChronicles = allPosts.filter(p =>
    p &&
    p.id &&
    isPostChronicleDiary(p) &&
    isPostOwnedByCurrentUser(p) &&
    !p.encryptedDiaryPayload &&
    !_upgradedChronicleIds.has(p.id) &&
    p.adaptedHeadline &&
    p.adaptedHeadline !== '🔒 Encrypted Daily Chronicle'
  );
  if (unencryptedChronicles.length === 0) return;

  for (const p of unencryptedChronicles) {
    _upgradedChronicleIds.add(p.id);
    try {
      const encryptedCopy = await encryptChroniclePostForCloud(p);
      if (encryptedCopy && encryptedCopy.encryptedDiaryPayload) {
        p.encryptedDiaryPayload = encryptedCopy.encryptedDiaryPayload;
        p.isEncryptedDiary = true;
        p._diaryDecrypted = true;
        await fetch('/api/posts', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(encryptedCopy)
        });
      }
    } catch (_) {}
  }
}

function mergeAndSortPosts(newPosts) {
  if (!Array.isArray(newPosts) || newPosts.length === 0) return false;

  const existingMap = new Map();
  // 1. Keep track of all current posts (excluding deleted tombstones, login-only showcase posts, & foreign diary entries)
  for (const post of allPosts) {
    if (post && post.id && !deletedPostIds.has(post.id) && !post.deleted && !post.isDeleted && !isLoginShowcaseOnlyPost(post)) {
      if (isPostChronicleDiary(post) && !isPostOwnedByCurrentUser(post)) {
        continue;
      }
      existingMap.set(post.id, post);
    }
  }

  let addedCount = 0;
  let hasPendingEncryptedChronicles = false;
  for (const raw of newPosts) {
    if (!raw) continue;
    const p = raw.data || raw;
    const postId = p.id || raw.id;
    if (!postId || p.deleted || p.isDeleted || raw.deleted || raw.isDeleted) {
      if (postId) applyDeletedPostsTombstone([postId]);
      continue;
    }
    if (deletedPostIds.has(postId) || isLoginShowcaseOnlyPost(postId) || isLoginShowcaseOnlyPost(p)) continue;
    if (!p.adaptedHeadline && !p.originalHeadline && !p.summary && !p.encryptedDiaryPayload) continue;

    // Normalize IDs and timestamps
    p.id = postId;
    p.createdAt = p.createdAt || raw.created_at || raw.createdAt || new Date().toISOString();

    // STRICT PRIVACY BARRIER: Never allow another user's Daily Chronicle diary entry into memory
    if (isPostChronicleDiary(p) && !isPostOwnedByCurrentUser(p)) {
      continue;
    }

    if (typeof p.encryptedDiaryPayload === 'string' && p.encryptedDiaryPayload.startsWith('ENC:v1:') && !p._diaryDecrypted) {
      hasPendingEncryptedChronicles = true;
    }

    // Sanitize image URLs (clean corrupted &amp; XML entities)
    if (typeof p.sourceImageUrl === 'string') p.sourceImageUrl = p.sourceImageUrl.replace(/&amp;/g, '&');
    if (typeof p.referencePhotoUrl === 'string') p.referencePhotoUrl = p.referencePhotoUrl.replace(/&amp;/g, '&');
    if (p.generationInputs) {
      if (typeof p.generationInputs.sourceImageUrl === 'string') p.generationInputs.sourceImageUrl = p.generationInputs.sourceImageUrl.replace(/&amp;/g, '&');
      if (typeof p.generationInputs.referencePhotoUrl === 'string') p.generationInputs.referencePhotoUrl = p.generationInputs.referencePhotoUrl.replace(/&amp;/g, '&');
    }

    if (!existingMap.has(postId)) {
      if (typeof applyLocalPostEngagementSnapshot === 'function') {
        applyLocalPostEngagementSnapshot(p);
      }
      existingMap.set(postId, p);
      addedCount++;
    } else {
      // Merge with existing ensuring fresh server/cloud fields overwrite stale local fields
      const existing = existingMap.get(postId);
      // Preserve already-decrypted diary fields if incoming cloud copy is still encrypted with the same payload
      if (existing._diaryDecrypted && p.encryptedDiaryPayload && !p._diaryDecrypted && existing.encryptedDiaryPayload === p.encryptedDiaryPayload) {
        const merged = { ...p, ...existing };
        merged.illustrationUrl = existing.illustrationUrl || p.illustrationUrl || '';
        merged.aiIllustrationUrl = existing.aiIllustrationUrl || p.aiIllustrationUrl || '';
        if (typeof applyLocalPostEngagementSnapshot === 'function') {
          applyLocalPostEngagementSnapshot(merged);
        }
        existingMap.set(postId, merged);
      } else {
        const merged = { ...existing, ...p };
        // Never let a stale local cache copy wipe out existing in-memory comments or reactions
        if (Array.isArray(existing.comments) && existing.comments.length > 0 && (!Array.isArray(p.comments) || p.comments.length < existing.comments.length)) {
          const byId = new Map();
          existing.comments.forEach(c => { if (c && c.id) byId.set(c.id, c); });
          if (Array.isArray(p.comments)) {
            p.comments.forEach(c => { if (c && c.id) byId.set(c.id, c); });
          }
          merged.comments = Array.from(byId.values());
          merged.commentCount = merged.comments.length;
        }
        if (Array.isArray(existing.heartedBy) && existing.heartedBy.length > 0 && (!Array.isArray(p.heartedBy) || p.heartedBy.length === 0)) {
          merged.heartedBy = existing.heartedBy;
          merged.heartCount = existing.heartedBy.length;
        }
        if (Array.isArray(existing.likedBy) && existing.likedBy.length > 0 && (!Array.isArray(p.likedBy) || p.likedBy.length === 0)) {
          merged.likedBy = existing.likedBy;
          merged.likeCount = existing.likedBy.length;
        }
        if (p.encryptedDiaryPayload && !p._diaryDecrypted && existing.encryptedDiaryPayload !== p.encryptedDiaryPayload) {
          delete merged._diaryDecrypted;
          delete merged.illustrationBase64;
          delete merged.posterBase64;
          hasPendingEncryptedChronicles = true;
          addedCount++;
        } else {
          merged.illustrationUrl = p.illustrationUrl || existing.illustrationUrl || '';
          merged.aiIllustrationUrl = p.aiIllustrationUrl || existing.aiIllustrationUrl || '';
          if (!merged.illustrationBase64 && existing.illustrationBase64) {
            merged.illustrationBase64 = existing.illustrationBase64;
          }
        }
        if (typeof applyLocalPostEngagementSnapshot === 'function') {
          applyLocalPostEngagementSnapshot(merged);
        }
        existingMap.set(postId, merged);
      }
    }
  }

  // Convert back to array and sort strictly chronologically (newest first)
  allPosts = Array.from(existingMap.values()).sort((a, b) => {
    const timeA = new Date(a.createdAt || a.created_at || 0).getTime();
    const timeB = new Date(b.createdAt || b.created_at || 0).getTime();
    return timeB - timeA; // Descending: newest stories stay at the top!
  });

  if (hasPendingEncryptedChronicles) {
    decryptAllOwnedChroniclePosts();
  } else if (currentUser) {
    upgradeUnencryptedOwnedChronicles();
  }

  return addedCount > 0;
}

async function fetchDirectSupabasePosts(limit = 12) {
  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 6000);
    const idResp = await fetch(`${SUPABASE_URL}/rest/v1/posts?select=id,created_at&id=like.slant*&or=(data->>isDiary.is.null,data->>isDiary.neq.true)&or=(data->>chronicleMode.is.null,data->>chronicleMode.neq.true)&or=(data->>isEncryptedDiary.is.null,data->>isEncryptedDiary.neq.true)&or=(data->>isDraft.is.null,data->>isDraft.neq.true)&or=(data->>isPrivate.is.null,data->>isPrivate.neq.true)&or=(data->>status.is.null,data->>status.neq.draft)&order=created_at.desc&limit=${limit}`, {
      signal: controller.signal,
      headers: {
        'apikey': SUPABASE_KEY,
        'Authorization': `Bearer ${SUPABASE_KEY}`
      }
    });
    clearTimeout(timeoutId);
    if (!idResp.ok) return [];
    const idRows = await idResp.json();
    if (!Array.isArray(idRows) || idRows.length === 0) return [];
    const orderedIds = idRows.map(r => r.id).filter(id => id && !id.startsWith('system_') && !id.startsWith('family_cast_') && !id.startsWith('curator_style_'));

    // Fetch posts via single indexed primary-key query (fast & resilient)
    const inFilter = orderedIds.map(id => '%22' + encodeURIComponent(id) + '%22').join(',');
    const pResp = await fetch(`${SUPABASE_URL}/rest/v1/posts?id=in.(${inFilter})`, {
      signal: controller.signal,
      headers: {
        'apikey': SUPABASE_KEY,
        'Authorization': `Bearer ${SUPABASE_KEY}`
      }
    });

    let orderedRows = [];
    if (pResp.ok) {
      const pRows = await pResp.json();
      const rowsMap = new Map();
      pRows.forEach(r => rowsMap.set(r.id, r));
      orderedRows = orderedIds.map(id => rowsMap.get(id)).filter(Boolean);
    }
    return orderedRows.map(r => {
      const p = r.data || r;
      p.id = p.id || r.id;
      p.createdAt = p.createdAt || r.created_at || new Date().toISOString();
      if (isPostPrivateOrDraft(p)) return null;
      if (p.illustrationUrl && (p.illustrationUrl.includes('unsplash.com') || p.illustrationUrl.includes('pollinations.ai'))) {
        p.illustrationUrl = '';
      }
      if (p.aiIllustrationUrl && (p.aiIllustrationUrl.includes('unsplash.com') || p.aiIllustrationUrl.includes('pollinations.ai'))) {
        p.aiIllustrationUrl = '';
      }
      if (!p.illustrationUrl && !p.illustrationBase64) {
        p.illustrationUrl = `/posters/${p.id}.png`;
        p.aiIllustrationUrl = p.illustrationUrl;
      }
      return p;
    }).filter(Boolean);
  } catch (err) {
    console.warn('fetchDirectSupabasePosts notice:', err);
    return [];
  }
}

// ============================================================
// DEEP LINKING & DIRECT POST NAVIGATION
// ============================================================
function getDeepLinkedPostId() {
  try {
    const params = new URLSearchParams(window.location.search);
    const fromQuery = params.get('p') || params.get('post') || params.get('id');
    if (fromQuery && fromQuery.trim()) {
      return decodeURIComponent(fromQuery.trim());
    }

    // Check path: /post/:id or /p/:id
    const pathMatch = window.location.pathname.match(/^\/(?:post|p)\/([^/?#]+)/i);
    if (pathMatch && pathMatch[1]) {
      return decodeURIComponent(pathMatch[1]).trim();
    }

    // Check hash: #slant-... or #post-... or #p=... or raw #id
    if (window.location.hash) {
      const rawHash = window.location.hash.replace(/^#\/?/, '').trim();
      const nonPostHashes = ['login', 'stories', 'feed', 'create', 'mystories', 'profile', 'admin', 'whitelist', 'gate'];
      if (rawHash && !nonPostHashes.includes(rawHash.toLowerCase())) {
        const cleaned = rawHash.replace(/^(?:post[-_]|p=)/i, '').trim();
        if (cleaned.length >= 3) {
          return decodeURIComponent(cleaned);
        }
      }
    }
  } catch (err) {
    console.warn('Error reading deep link post ID:', err);
  }
  return null;
}

function getPostShareUrl(post) {
  if (!post || !post.id) return window.location.origin;
  return `${window.location.origin}/?p=${encodeURIComponent(post.id)}`;
}

function getDeepLinkedSeriesInfo() {
  try {
    const params = new URLSearchParams(window.location.search);
    const seriesId = (params.get('series') || params.get('seriesId') || '').trim();
    const curator = (params.get('curator') || params.get('author') || params.get('creator') || '').trim().replace(/^@/, '');
    if (seriesId) {
      return {
        seriesId: decodeURIComponent(seriesId),
        curator: curator ? decodeURIComponent(curator) : ''
      };
    }
  } catch (_) {}
  return null;
}

function hasPublicDeepLinkInUrl() {
  try {
    if (getDeepLinkedPostId() || getDeepLinkedSeriesInfo()) return true;
    const params = new URLSearchParams(window.location.search);
    const c = params.get('curator') || params.get('author') || params.get('creator');
    return Boolean(c && c.trim());
  } catch (_) {
    return false;
  }
}

function getSeriesShareUrl(seriesId, authorHandle = '') {
  const cleanSeriesId = String(seriesId || '').trim();
  const cleanHandle = String(authorHandle || (typeof getUserDisplayName === 'function' ? getUserDisplayName() : '') || '').replace(/^@/, '').trim();
  if (!cleanSeriesId) return window.location.origin;
  if (cleanHandle) {
    return `${window.location.origin}/?curator=${encodeURIComponent(cleanHandle)}&series=${encodeURIComponent(cleanSeriesId)}`;
  }
  return `${window.location.origin}/?series=${encodeURIComponent(cleanSeriesId)}`;
}

function getSourceHeadline(post) {
  if (!post) return 'this topic';
  let title = (
    (typeof post.sourceHeadline === 'string' && post.sourceHeadline.trim()) ||
    (typeof post.originalHeadline === 'string' && post.originalHeadline.trim()) ||
    (typeof post.scrapedTitle === 'string' && post.scrapedTitle.trim()) ||
    (typeof post.sourceTitle === 'string' && post.sourceTitle.trim()) ||
    (typeof post.spark === 'string' && post.spark.trim()) ||
    (typeof post.adaptedHeadline === 'string' && post.adaptedHeadline.trim()) ||
    'this topic'
  ).trim();
  title = title.replace(/^["'“‘]+|["'”’]+$/g, '').trim();
  return title || 'this topic';
}

function getPostShareText(post) {
  if (!post) return '';
  const headline = (post.adaptedHeadline || post.originalHeadline || 'Curated Story').trim();
  const url = getPostShareUrl(post);
  return `"${headline}"\n\nRead my brief opinion (1-min read) on Slant:\n${url}`;
}

function buildSharePayload(files, title, text, url, mode = 'status') {
  if (!navigator.share) return null;

  let shareFiles = files;
  if (files && files.length > 0) {
    // In 'chat' mode, reverse files so messaging apps (such as WhatsApp) that read
    // incoming file streams in LIFO/reverse order place Poster 1 as the primary thumbnail and caption anchor.
    // In 'status' mode, preserve natural 1 -> 2 -> 3 sequential order so WhatsApp Status & Instagram Stories play in order.
    shareFiles = (mode === 'chat') ? [...files].reverse() : [...files];
  }

  if (shareFiles && shareFiles.length > 0 && navigator.canShare) {
    // 1. Try files + title + text (text already has the link embedded; omitting the separate
    // 'url' property prevents mobile browsers and WhatsApp from appending the link a second time)
    const filesWithText = { files: shareFiles, title, text };
    if (navigator.canShare(filesWithText)) {
      return filesWithText;
    }
    // 2. Try files only if text + files is rejected by device
    const filesOnly = { files: shareFiles };
    if (navigator.canShare(filesOnly)) {
      return filesOnly;
    }
  }

  // Fallback to text only without files (text already embeds the link, so omit redundant url)
  const textPayload = { title, text };
  if (navigator.canShare && navigator.canShare(textPayload)) {
    return textPayload;
  }
  // Ultimate text fallback if app strictly requires url property
  const fullTextPayload = { title, text, url };
  if (navigator.canShare && navigator.canShare(fullTextPayload)) {
    return fullTextPayload;
  }
  return null;
}

// SCROLL GATE FOR DEEP-LINKED POST GUESTS
let isDeepLinkScrollGated = false;
let deepLinkScrollGateListenersAttached = false;
let lastScrollGatePromptTime = 0;
let gateTouchStartY = 0;
let gateTouchStartX = 0;

function isAnyModalOpen() {
  const modal = document.querySelector('.modal-overlay.open, .modal-overlay.active, .modal-card.open');
  return !!modal;
}

function _onDeepLinkGateScroll() {
  if (!isDeepLinkScrollGated || currentUser) return;
  if (isAnyModalOpen()) return;
  const currentY = window.pageYOffset || document.documentElement.scrollTop || 0;
  if (currentY > 30) {
    triggerDeepLinkScrollGate('scroll');
  }
}

function _onDeepLinkGateWheel(e) {
  if (!isDeepLinkScrollGated || currentUser) {
    teardownDeepLinkScrollGateListeners();
    return;
  }
  if (isAnyModalOpen()) return;
  if (Math.abs(e.deltaY) > 8) {
    e.preventDefault();
    triggerDeepLinkScrollGate('wheel');
  }
}

function _onDeepLinkGateTouchStart(e) {
  if (!isDeepLinkScrollGated || currentUser) return;
  if (e.touches && e.touches.length > 0) {
    gateTouchStartY = e.touches[0].clientY;
    gateTouchStartX = e.touches[0].clientX;
  }
}

function _onDeepLinkGateTouchMove(e) {
  if (!isDeepLinkScrollGated || currentUser) {
    teardownDeepLinkScrollGateListeners();
    return;
  }
  if (isAnyModalOpen()) return;
  if (e.touches && e.touches.length > 0) {
    const diffY = Math.abs(e.touches[0].clientY - gateTouchStartY);
    const diffX = Math.abs(e.touches[0].clientX - gateTouchStartX);
    if (diffY > 18 && diffY > diffX) {
      e.preventDefault();
      triggerDeepLinkScrollGate('touch');
    }
  }
}

function _onDeepLinkGateKeydown(e) {
  if (!isDeepLinkScrollGated || currentUser) return;
  if (isAnyModalOpen()) return;
  const scrollKeys = ['ArrowDown', 'ArrowUp', 'PageDown', 'PageUp', 'Space', 'Home', 'End'];
  if (scrollKeys.includes(e.code) || scrollKeys.includes(e.key)) {
    e.preventDefault();
    triggerDeepLinkScrollGate('key');
  }
}

function teardownDeepLinkScrollGateListeners() {
  if (!deepLinkScrollGateListenersAttached) return;
  deepLinkScrollGateListenersAttached = false;
  window.removeEventListener('scroll', _onDeepLinkGateScroll);
  window.removeEventListener('wheel', _onDeepLinkGateWheel);
  window.removeEventListener('touchstart', _onDeepLinkGateTouchStart);
  window.removeEventListener('touchmove', _onDeepLinkGateTouchMove);
  window.removeEventListener('keydown', _onDeepLinkGateKeydown);
}

function setupDeepLinkScrollGate() {
  if (!isDeepLinkScrollGated || currentUser) {
    teardownDeepLinkScrollGateListeners();
    return;
  }
  if (deepLinkScrollGateListenersAttached) return;
  deepLinkScrollGateListenersAttached = true;

  window.addEventListener('scroll', _onDeepLinkGateScroll, { passive: true });
  window.addEventListener('wheel', _onDeepLinkGateWheel, { passive: false });
  window.addEventListener('touchstart', _onDeepLinkGateTouchStart, { passive: true });
  window.addEventListener('touchmove', _onDeepLinkGateTouchMove, { passive: false });
  window.addEventListener('keydown', _onDeepLinkGateKeydown, { passive: false });
}

function triggerDeepLinkScrollGate(reason = 'scroll') {
  if (!isDeepLinkScrollGated || currentUser) return;

  // Snap back to top of the shared post
  try {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  } catch (_) {}

  const now = Date.now();
  if (now - lastScrollGatePromptTime < 2200) {
    return;
  }
  lastScrollGatePromptTime = now;

  openAuthModal('Sign in to explore more visual stories on Slant.');
}

function appendDeepLinkFeedGate() {
  const container = document.getElementById('feedContainer');
  if (!container) return;

  const existing = document.getElementById('deepLinkFeedGate');
  if (existing) existing.remove();

  const barrier = document.createElement('div');
  barrier.className = 'deep-link-feed-gate';
  barrier.id = 'deepLinkFeedGate';
  barrier.innerHTML = `
    <div class="deep-link-gate-card">
      <div class="deep-link-gate-pill">✦ CURATED STORY SPOTLIGHT ✦</div>
      <div class="deep-link-gate-icon">🔒</div>
      <h3 class="deep-link-gate-title">Explore More Visual Stories</h3>
      <p class="deep-link-gate-sub">
        Sign in with Google to explore the full editorial feed, verify source receipts, and craft your own visual stories.
      </p>
      <button type="button" class="deep-link-gate-btn" onclick="openAuthModal('Sign in to explore more stories on Slant.')">
        <span>Sign in with Google</span>
        <span class="deep-link-gate-arrow">&rarr;</span>
      </button>
    </div>
  `;
  container.appendChild(barrier);
  if (typeof observeFeedBatchEndBarrier === 'function') {
    observeFeedBatchEndBarrier();
  }
}

function scrollToPostElement(targetCard) {
  if (!targetCard) return;
  const header = document.querySelector('header');
  const headerHeight = header ? header.offsetHeight : 60;
  const rect = targetCard.getBoundingClientRect();
  const screenHeight = window.innerHeight;

  let targetY;
  if (rect.height + headerHeight + 40 < screenHeight) {
    targetY = window.pageYOffset + rect.top - ((screenHeight - rect.height) / 2);
  } else {
    targetY = window.pageYOffset + rect.top - headerHeight - 16;
  }
  window.scrollTo({ top: Math.max(0, targetY), behavior: 'smooth' });
}

async function loadPosts() {
  // 1. Start seamless jerk-free logo video loop in initial loader
  if (!window._feedVideoLoop) {
    window._feedVideoLoop = setupSeamlessVideoLoop('feedLoaderVideoWrap', 'feedInitialVideoA', 'feedInitialVideoB', 0.45);
  }
  if (window._feedVideoLoop) {
    window._feedVideoLoop.start();
  } else {
    const initVid = document.getElementById('feedInitialVideoA') || document.getElementById('feedInitialVideo');
    if (initVid) {
      try {
        initVid.currentTime = 0;
        const playP = initVid.play();
        if (playP !== undefined) playP.catch(() => {});
      } catch (_) {}
    }
  }

  // 2. Fetch authoritative batch of 12 posts from /api/posts?limit=12 (with resilient fallback to direct Supabase)
  let fetchedLiveBatch = null;
  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 8000);
    const apiResp = await fetch(`/api/posts?limit=${FEED_BATCH_SIZE}&ts=${Date.now()}`, {
      cache: 'no-store',
      signal: controller.signal
    });
    clearTimeout(timeoutId);
    if (apiResp.ok) {
      const data = await apiResp.json();
      if (data && Array.isArray(data.deletedIds) && data.deletedIds.length > 0) {
        applyDeletedPostsTombstone(data.deletedIds);
      }
      if (data && Array.isArray(data.posts) && data.posts.length > 0) {
        fetchedLiveBatch = data.posts;
        if (data.total) feedCloudTotal = data.total;
        if (data.hasMore !== undefined) feedCloudHasMore = data.hasMore;
      }
    }
  } catch (e) {
    console.warn('Fast /api/posts fetch notice, falling back:', e);
  }

  // If /api/posts didn't return, fetch direct from Supabase via fast point lookups
  if (!fetchedLiveBatch || fetchedLiveBatch.length === 0) {
    try {
      const supaPosts = await fetchDirectSupabasePosts(FEED_BATCH_SIZE);
      if (Array.isArray(supaPosts) && supaPosts.length > 0) {
        fetchedLiveBatch = supaPosts;
      }
    } catch (_) {}
  }

  if (fetchedLiveBatch && fetchedLiveBatch.length > 0) {
    await decryptChroniclePostsInPlace(fetchedLiveBatch);
    mergeAndSortPosts(fetchedLiveBatch);
  } else {
    try {
      const fastResp = await fetch(`slant_feed.json?ts=${Date.now()}`, { cache: 'no-cache' });
      if (fastResp.ok) {
        const posts = await fastResp.json();
        if (Array.isArray(posts) && posts.length > 0) {
          await decryptChroniclePostsInPlace(posts);
          mergeAndSortPosts(posts);
        }
      }
    } catch (e) {
      console.warn('Could not load slant_feed.json:', e);
    }
  }

  // Merge locally cached user stories so they never vanish (strictly filtered to owned posts)
  try {
    sanitizeUserOwnershipAndCache();
    const localCache = JSON.parse(localStorage.getItem('slant_user_posts_cache') || '[]');
    if (Array.isArray(localCache) && localCache.length > 0) {
      const safeLocalCache = localCache.filter(p => p && (!isPostChronicleDiary(p) || isPostOwnedByCurrentUser(p)));
      if (safeLocalCache.length > 0) {
        await decryptChroniclePostsInPlace(safeLocalCache);
        mergeAndSortPosts(safeLocalCache);
      }
    }
  } catch (e) {
    console.warn('Error merging local user posts cache:', e);
  }

  // Pre-fetch deep-linked post from cloud if not yet in memory (never pre-fetch another user's private diary)
  const deepPostId = getDeepLinkedPostId();
  if (deepPostId) {
    currentFilter = 'all';
    const exists = allPosts.some(p => p && p.id === deepPostId);
    if (!exists) {
      try {
        const resp = await fetch(`${SUPABASE_URL}/rest/v1/posts?id=eq.${encodeURIComponent(deepPostId)}&select=*`, {
          headers: {
            'apikey': SUPABASE_KEY,
            'Authorization': `Bearer ${SUPABASE_KEY}`
          }
        });
        if (resp.ok) {
          const rows = await resp.json();
          if (Array.isArray(rows) && rows.length > 0) {
            const p = rows[0].data || rows[0];
            p.id = p.id || rows[0].id;
            p.createdAt = p.createdAt || rows[0].created_at || new Date().toISOString();
            if (!isPostPrivateOrDraft(p) || isPostOwnedByCurrentUser(p)) {
              if (!p.illustrationUrl && !p.illustrationBase64 && !isPostChronicleDiary(p)) {
                p.illustrationUrl = `/posters/${p.id}.png`;
                p.aiIllustrationUrl = p.illustrationUrl;
              }
              await decryptChroniclePostsInPlace([p]);
              mergeAndSortPosts([p]);
            }
          }
        }
      } catch (e) {
        console.warn('Error pre-fetching deep-linked post before initial render:', e);
      }
    }

    // Promote deep-linked post to the very front so visitor immediately sees it
    const deepIndex = allPosts.findIndex(p => p && p.id === deepPostId);
    if (deepIndex > 0) {
      const [deepPost] = allPosts.splice(deepIndex, 1);
      allPosts.unshift(deepPost);
    }
  }

  // 3. Render Batch 1 of 12 posts and WAIT for all 12 posters + video loop before dismissing loader
  if (allPosts.length > 0) {
    updateBadge(true, `Live Feed (${allPosts.length} posts)`);
    updateAuthUI();
    await renderFeed(true);
  } else {
    dismissInitialFeedLoader(true);
  }

  // 4. In background, silently sync remaining posts from cloud
  syncLiveCloudPosts(false);
  if (currentUser) {
    fetchAuthorStoriesFromCloud();
  }
}

async function syncLiveCloudPosts(forceRender = false) {
  let fetchedPosts = null;

  // 1. Primary: Fetch from /api/posts with timestamp and no-store to bypass any proxy/browser cache
  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 8000);
    const apiResp = await fetch(`/api/posts?limit=50&ts=${Date.now()}`, {
      cache: 'no-store',
      signal: controller.signal
    });
    clearTimeout(timeoutId);
    if (apiResp.ok) {
      const data = await apiResp.json();
      if (data && Array.isArray(data.deletedIds) && data.deletedIds.length > 0) {
        applyDeletedPostsTombstone(data.deletedIds);
      }
      if (data && Array.isArray(data.posts) && data.posts.length > 0) {
        fetchedPosts = data.posts;
        if (data.total) feedCloudTotal = data.total;
        if (data.hasMore !== undefined) feedCloudHasMore = data.hasMore;
      }
    }
  } catch (apiErr) {
    console.warn('/api/posts live sync error, trying direct Supabase fallback:', apiErr);
  }

  // 2. Resilient Fallback: If /api/posts failed or was unreachable, query Supabase directly via fast point lookups
  if (!fetchedPosts || fetchedPosts.length === 0) {
    try {
      const supaPosts = await fetchDirectSupabasePosts(15);
      if (Array.isArray(supaPosts) && supaPosts.length > 0) {
        fetchedPosts = supaPosts;
      }
    } catch (supaErr) {
      console.warn('Direct Supabase live sync completed or timed out:', supaErr);
    }
  }

  if (Array.isArray(fetchedPosts) && fetchedPosts.length > 0) {
    await fetchGlobalDeletedPostsRegistry();
    const validPosts = fetchedPosts.filter(p => p && !p.deleted && !p.isDeleted && !deletedPostIds.has(p.id) && (!isPostChronicleDiary(p) || isPostOwnedByCurrentUser(p)) && (p.adaptedHeadline || p.originalHeadline || p.summary || p.encryptedDiaryPayload));
    await decryptChroniclePostsInPlace(validPosts);
    const hasNew = mergeAndSortPosts(validPosts);

    // Persist synced user-created stories into local cache so they persist offline & across sessions
    try {
      const userStories = validPosts.filter(p => isPostOwnedByCurrentUser(p));
      if (userStories.length > 0) {
        const sanitizeForCache = (p) => {
          if (!p || !isPostOwnedByCurrentUser(p)) return null;
          const copy = { ...p };
          delete copy.originalPhotoBase64;
          if (copy.illustrationBase64 && copy.illustrationBase64.length > 50000) {
            delete copy.illustrationBase64;
          }
          if (!copy.illustrationUrl && !isPostChronicleDiary(copy)) {
            copy.illustrationUrl = '/posters/' + copy.id + '.png';
            copy.aiIllustrationUrl = copy.illustrationUrl;
          }
          return copy;
        };
        const existingLocal = JSON.parse(localStorage.getItem('slant_user_posts_cache') || '[]');
        const map = new Map();
        userStories.map(sanitizeForCache).filter(Boolean).forEach(p => { if (!deletedPostIds.has(p.id)) map.set(p.id, p); });
        existingLocal.map(sanitizeForCache).filter(Boolean).forEach(p => { if (!map.has(p.id) && !deletedPostIds.has(p.id) && !p.deleted && !p.isDeleted) map.set(p.id, p); });
        localStorage.setItem('slant_user_posts_cache', JSON.stringify(Array.from(map.values()).slice(0, 30)));
      }
    } catch (_) {}

    if (forceRender && currentRenderedBatch === 0 && window.scrollY < 400) {
      updateBadge(true, `Live Feed (${allPosts.length} posts)`);
      updateAuthUI();
      renderFeed();
    } else {
      currentBatchFilteredPosts = getFilteredPostsForFilter(allPosts, currentFilter, searchQuery);
      updateBadge(true, `Live Feed (${allPosts.length} posts)`);
      updateAuthUI();
      if (typeof syncAllRenderedPostEngagementDOM === 'function') {
        syncAllRenderedPostEngagementDOM();
      }
    }
  }

  // 3. Always refresh authenticated author's created stories & private drafts directly from Supabase
  if (currentUser && myCreatedPostIds && myCreatedPostIds.size > 0) {
    try {
      sanitizeUserOwnershipAndCache();
      const myIdsArray = Array.from(myCreatedPostIds).filter(id => !deletedPostIds.has(id)).slice(0, 30);
      const inFilter = myIdsArray.map(id => '%22' + encodeURIComponent(id) + '%22').join(',');
      const myResp = myIdsArray.length > 0 ? await fetch(`${SUPABASE_URL}/rest/v1/posts?id=in.(${inFilter})`, {
        headers: {
          'apikey': SUPABASE_KEY,
          'Authorization': `Bearer ${SUPABASE_KEY}`
        }
      }) : { ok: false };
      if (myResp.ok) {
        const myRows = await myResp.json();
        if (Array.isArray(myRows)) {
          const returnedIds = new Set();
          const softDeletedIds = [];
          const freshUserPosts = [];
          let purgedForeignIds = false;
          myRows.forEach(r => {
            const p = r.data || r;
            const id = p.id || r.id;
            if (!id) return;
            returnedIds.add(id);
            p.id = id;
            p.createdAt = p.createdAt || r.created_at || new Date().toISOString();
            // Strictly reject and un-claim any post that does not belong to currentUser
            if (!isPostOwnedByCurrentUser(p)) {
              myCreatedPostIds.delete(id);
              purgedForeignIds = true;
              return;
            }
            if (p.deleted || p.isDeleted || r.deleted || r.isDeleted || deletedPostIds.has(id)) {
              softDeletedIds.push(id);
              return;
            }
            freshUserPosts.push(p);
          });
          if (purgedForeignIds) {
            localStorage.setItem('slant_my_posts', JSON.stringify(Array.from(myCreatedPostIds)));
            syncUserMetadataToCloud();
          }
          // Any ID in myIdsArray that is missing from Supabase (hard-deleted on another device) is also purged!
          myIdsArray.forEach(id => {
            if (!returnedIds.has(id)) {
              softDeletedIds.push(id);
            }
          });
          let hadDeletions = false;
          if (softDeletedIds.length > 0) {
            hadDeletions = applyDeletedPostsTombstone(softDeletedIds);
            syncUserMetadataToCloud();
          }
          await decryptChroniclePostsInPlace(freshUserPosts);
          const hasDraftUpdates = mergeAndSortPosts(freshUserPosts);
          // Overwrite localStorage cache with fresh copies from Supabase
          const sanitizeForCache = (p) => {
            if (!p || !isPostOwnedByCurrentUser(p)) return null;
            const copy = { ...p };
            delete copy.originalPhotoBase64;
            if (copy.illustrationBase64 && copy.illustrationBase64.length > 50000) {
              delete copy.illustrationBase64;
            }
            if (!copy.illustrationUrl && !isPostChronicleDiary(copy)) {
              copy.illustrationUrl = '/posters/' + copy.id + '.png';
              copy.aiIllustrationUrl = copy.illustrationUrl;
            }
            return copy;
          };
          const existingLocal = JSON.parse(localStorage.getItem('slant_user_posts_cache') || '[]');
          const map = new Map();
          existingLocal.map(sanitizeForCache).filter(Boolean).forEach(p => { if (!deletedPostIds.has(p.id) && !p.deleted && !p.isDeleted) map.set(p.id, p); });
          freshUserPosts.map(sanitizeForCache).filter(Boolean).forEach(p => { if (!deletedPostIds.has(p.id)) map.set(p.id, p); });
          localStorage.setItem('slant_user_posts_cache', JSON.stringify(Array.from(map.values()).slice(0, 30)));
          if (hasDraftUpdates || hadDeletions) {
            softDeletesDOMPrune(softDeletedIds);
            if (currentRenderedBatch === 0 && window.scrollY < 400) {
              renderFeed();
            }
          }
        }
      }
    } catch (err) {
      console.warn('Sync user drafts error:', err);
    }
  }
}

async function fetchAuthorStoriesFromCloud() {
  try {
    if (!currentUser || !currentUser.email) {
      return;
    }
    const email = (currentUser.email || '').trim().toLowerCase();
    const handle = (currentUser.user_metadata?.user_name || currentUser.user_metadata?.name || email.split('@')[0] || '').replace('@', '').trim();
    const queryParts = [`email=${encodeURIComponent(email)}`];
    if (handle) {
      queryParts.push(`author=${encodeURIComponent(handle)}`);
    }

    const resp = await fetch(`/api/posts?${queryParts.join('&')}&limit=50&ts=${Date.now()}`);
    if (resp.ok) {
      const data = await resp.json();
      if (data && Array.isArray(data.deletedIds) && data.deletedIds.length > 0) {
        applyDeletedPostsTombstone(data.deletedIds);
      }
      if (data && Array.isArray(data.posts) && data.posts.length > 0) {
        const ownedPosts = data.posts.filter(p => p && p.id && !deletedPostIds.has(p.id) && !p.deleted && !p.isDeleted && isPostOwnedByCurrentUser(p));
        ownedPosts.forEach(p => {
          myCreatedPostIds.add(p.id);
        });
        localStorage.setItem('slant_my_posts', JSON.stringify(Array.from(myCreatedPostIds)));
        await decryptChroniclePostsInPlace(ownedPosts);
        const added = mergeAndSortPosts(ownedPosts);
        currentBatchFilteredPosts = getFilteredPostsForFilter(allPosts, currentFilter, searchQuery);
        updateBadge(true, `Live Feed (${allPosts.length} posts)`);
        updateAuthUI();
        if ((added || currentFilter === 'my_stories' || currentFilter === 'daily_chronicles' || currentFilter === 'diary') && currentRenderedBatch === 0 && window.scrollY < 400) {
          renderFeed();
        }
      }
    }
  } catch (err) {
    console.warn('fetchAuthorStoriesFromCloud error:', err);
  }
}

// Backward-compatible alias
const checkLiveSupabaseUpdates = syncLiveCloudPosts;

function updateBadge(connected, textOrCount) {
  const badge = document.getElementById('connectionBadge');
  const label = document.getElementById('connectionText');
  if (!badge || !label) return;

  if (!connected) {
    label.innerHTML = '<span class="badge-unit">Offline</span>';
    return;
  }

  let count = Array.isArray(allPosts) ? allPosts.length : 30;
  if (typeof textOrCount === 'number') {
    count = textOrCount;
  } else if (typeof textOrCount === 'string') {
    const m = textOrCount.match(/\d+/);
    if (m) count = parseInt(m[0], 10);
  }

  label.innerHTML = `<strong>${count}</strong> <span class="badge-unit">stories</span>`;
  badge.setAttribute('title', `${count} Active Editorial Stories`);
}

function setupEventListeners() {
  document.querySelectorAll('.filter-pill').forEach(pill => {
    pill.addEventListener('click', () => {
      const cat = pill.getAttribute('data-cat');
      selectCategory(cat);
    });
  });
}

function setupPullToRefresh() {
  const ptr = document.getElementById('ptrIndicator');
  const ptrIcon = document.getElementById('ptrIcon');
  const ptrLabel = document.getElementById('ptrLabel');
  if (!ptr) return;

  let startY = 0;
  let isPulling = false;
  let isRefreshing = false;
  const THRESHOLD = 60; // Distance in px to trigger refresh

  function getScrollTop() {
    return window.scrollY || window.pageYOffset || document.documentElement.scrollTop || 0;
  }

  function handleTouchStart(e) {
    if (isRefreshing) return;
    if (getScrollTop() <= 2) {
      startY = e.touches ? e.touches[0].clientY : e.clientY;
      isPulling = true;
    }
  }

  function handleTouchMove(e) {
    if (!isPulling || isRefreshing) return;
    const currentY = e.touches ? e.touches[0].clientY : e.clientY;
    const dy = currentY - startY;

    if (dy > 0 && getScrollTop() <= 2) {
      // Gentle dampening curve
      const pullDist = Math.min(80, dy * 0.45);
      if (pullDist > 8) {
        if (e.cancelable && e.preventDefault) e.preventDefault();
        ptr.style.height = `${pullDist}px`;
        ptr.classList.add('visible');

        if (pullDist >= THRESHOLD) {
          ptr.classList.add('ready');
          if (ptrLabel) ptrLabel.textContent = 'Release to refresh';
        } else {
          ptr.classList.remove('ready');
          if (ptrLabel) ptrLabel.textContent = 'Pull down to refresh';
        }
      }
    } else {
      ptr.style.height = '0px';
      ptr.classList.remove('visible', 'ready');
    }
  }

  async function handleTouchEnd() {
    if (!isPulling) return;
    isPulling = false;

    if (ptr.classList.contains('ready') && !isRefreshing) {
      isRefreshing = true;
      ptr.classList.remove('ready');
      ptr.classList.add('refreshing');
      ptr.style.height = '48px';
      if (ptrLabel) ptrLabel.textContent = 'Updating feed...';

      try {
        await syncFeed();
        if (ptrLabel) ptrLabel.textContent = 'Stories updated!';
      } catch (err) {
        console.error('Pull-to-refresh error:', err);
        if (ptrLabel) ptrLabel.textContent = 'Refresh complete';
      }

      setTimeout(() => {
        ptr.style.height = '0px';
        setTimeout(() => {
          ptr.classList.remove('refreshing', 'visible');
          if (ptrLabel) ptrLabel.textContent = 'Pull down to refresh';
          isRefreshing = false;
        }, 260);
      }, 500);
    } else {
      ptr.style.height = '0px';
      setTimeout(() => {
        ptr.classList.remove('visible', 'ready');
      }, 200);
    }
  }

  window.addEventListener('touchstart', handleTouchStart, { passive: true });
  window.addEventListener('touchmove', handleTouchMove, { passive: false });
  window.addEventListener('touchend', handleTouchEnd, { passive: true });
  window.addEventListener('touchcancel', handleTouchEnd, { passive: true });
}

function handleSearch(query) {
  searchQuery = (query || '').toLowerCase().trim();
  renderFeed();
}

async function checkDeepLink() {
  const params = new URLSearchParams(window.location.search);
  const deepPostId = getDeepLinkedPostId();
  if (deepPostId) {
    if (!currentUser) {
      isDeepLinkScrollGated = true;
      setupDeepLinkScrollGate();
    }

    function tryFocusDeepLinkedPost(attempts = 10) {
      const targetCard = document.getElementById('post-' + deepPostId) || document.querySelector(`[data-post-id="${deepPostId}"]`);
      if (targetCard) {
        dismissInitialFeedLoader(true);
        setTimeout(() => {
          scrollToPostElement(targetCard);
          targetCard.classList.add('deep-link-highlight');
          showTemporaryToast('📍 Viewing shared post');

          const targetPost = allPosts.find(p => p && p.id === deepPostId);
          if (targetPost) {
            const headline = targetPost.adaptedHeadline || targetPost.originalHeadline;
            if (headline) {
              document.title = `${headline} • Slant`;
            }
          }

          // Check if caller explicitly requested source proof modal open (?proof=true)
          if (params.get('proof') === 'true' || params.get('source') === 'proof') {
            const idx = allPosts.findIndex(p => p && p.id === deepPostId);
            if (idx >= 0) setTimeout(() => openDetailModal(idx), 400);
          }

          setTimeout(() => {
            targetCard.classList.remove('deep-link-highlight');
          }, 3500);
        }, 300);
        return;
      }

      if (attempts > 0) {
        setTimeout(() => tryFocusDeepLinkedPost(attempts - 1), 250);
      }
    }

    tryFocusDeepLinkedPost(10);
    return;
  }

  // Check login deep link / direct route or first-time visitor gateway
  if (isUninvitedGateActive || sessionStorage.getItem('slant_gate_active_email')) {
    return;
  }

  const isExplicitLogin = params.get('auth') === 'login' ||
    params.get('login') === 'true' ||
    window.location.hash === '#login' ||
    (window.location.pathname && window.location.pathname.endsWith('/login'));

  const curatorParam = params.get('curator') || params.get('author') || params.get('creator');
  const seriesParam = params.get('series') || params.get('seriesId');
  if ((curatorParam && curatorParam.trim()) || (seriesParam && seriesParam.trim())) {
    let cleanCurator = curatorParam ? decodeURIComponent(curatorParam.trim()).replace(/^@/, '') : '';
    const cleanSeriesId = seriesParam ? decodeURIComponent(seriesParam.trim()) : 'all';

    // If only ?series= was provided without ?curator=, infer curator from the matching post in allPosts
    if (!cleanCurator && cleanSeriesId && cleanSeriesId !== 'all' && Array.isArray(allPosts)) {
      const matchedSeriesPost = allPosts.find(p => {
        if (!p || p.deleted || p.isDeleted) return false;
        const sInfo = typeof getPostSeriesInfo === 'function' ? getPostSeriesInfo(p) : null;
        return sInfo && sInfo.id === cleanSeriesId;
      });
      if (matchedSeriesPost) {
        cleanCurator = String(matchedSeriesPost.creatorHandle || matchedSeriesPost.userEmail || '').replace(/^@/, '').trim();
      }
    }

    if (cleanCurator) {
      dismissInitialFeedLoader(true);
      updateAuthUI();
      setTimeout(() => {
        filterByCurator(cleanCurator, cleanSeriesId || 'all');
        window.scrollTo({ top: 0, behavior: 'smooth' });
        if (cleanSeriesId && cleanSeriesId !== 'all') {
          showTemporaryToast('📚 Viewing shared Series');
        }
      }, 260);
      return;
    }
  }

  if (!currentUser && (isExplicitLogin || !deepPostId)) {
    updateAuthUI();
  } else if (currentUser && window.location.hash === '#login') {
    try {
      const cleanUrl = window.location.pathname + window.location.search;
      history.replaceState(null, '', cleanUrl);
    } catch (_) {}
  }
}

// Listen for browser navigation / hashchange for #login or deep-linked post
window.addEventListener('hashchange', () => {
  if (window.location.hash === '#login') {
    if (currentUser) {
      try {
        const cleanUrl = window.location.pathname + window.location.search;
        history.replaceState(null, '', cleanUrl);
      } catch (_) {}
      return;
    }
    openAuthModal();
  } else {
    closeAuthModal();
    const deepId = getDeepLinkedPostId();
    if (deepId) {
      const card = document.getElementById('post-' + deepId) || document.querySelector(`[data-post-id="${deepId}"]`);
      if (card) {
        scrollToPostElement(card);
        card.classList.add('deep-link-highlight');
        setTimeout(() => card.classList.remove('deep-link-highlight'), 3500);
      }
    }
  }
});
/* ============================================================
   BATCHED 12-POST FEED ENGINE & PRE-CACHE LOADER
   - Feed is presented in strict, verified batches of 12
   - While batch 1 is downloading/decoding, slantlogovideo.mp4 loops
   - Next batch of 12 is silently pre-cached in background
   - Bottom logo loader seamlessly displays if user scrolls before ready
   ============================================================ */

const FEED_BATCH_SIZE = 12;
let currentRenderedBatch = 0;
let currentBatchFilteredPosts = [];
let isBatchLoading = false;
let nextBatchPreloadPromise = null;
let feedInfiniteScrollInitialized = false;
let feedCloudHasMore = true;
let feedCloudTotal = null;

function getPostCardImageUrl(post) {
  if (!post) return '';
  if (post.illustrationBase64) {
    return post.illustrationBase64.startsWith('data:')
      ? post.illustrationBase64
      : `data:image/png;base64,${post.illustrationBase64}`;
  }
  let url = post.illustrationUrl || post.aiIllustrationUrl || '';
  if (url.includes('unsplash.com') || url.includes('pollinations.ai')) {
    url = `/posters/${post.id}.png`;
  }
  if (!url && post.id) {
    url = `/posters/${post.id}.png`;
  }
  return url;
}

function preloadSingleImage(url) {
  if (!url) return Promise.resolve(false);
  return new Promise((resolve) => {
    const img = new Image();
    let settled = false;
    const onDone = () => {
      if (settled) return;
      settled = true;
      if (typeof img.decode === 'function') {
        img.decode()
          .then(() => resolve(img.naturalWidth > 0))
          .catch(() => resolve(img.naturalWidth > 0));
      } else {
        resolve(img.naturalWidth > 0);
      }
    };
    img.onload = onDone;
    img.onerror = () => {
      if (settled) return;
      settled = true;
      console.warn('Preload notice: could not load', url);
      resolve(false);
    };
    img.src = url;
    if (img.complete && img.naturalWidth > 0) {
      onDone();
    }
  });
}

function waitForCardImageDecode(cardElement) {
  if (!cardElement) return Promise.resolve(true);
  const img = cardElement.querySelector('.slide-hook-bg');
  if (!img || !img.src) return Promise.resolve(true);

  return new Promise((resolve) => {
    if (img.complete && img.naturalWidth > 0) {
      if (typeof img.decode === 'function') {
        img.decode().then(() => resolve(true)).catch(() => resolve(true));
      } else {
        resolve(true);
      }
      return;
    }

    let settled = false;
    const onDone = () => {
      if (settled) return;
      settled = true;
      if (typeof img.decode === 'function') {
        img.decode().then(() => resolve(true)).catch(() => resolve(true));
      } else {
        resolve(true);
      }
    };

    img.addEventListener('load', onDone, { once: true });
    img.addEventListener('error', () => {
      if (settled) return;
      settled = true;
      resolve(false);
    }, { once: true });
  });
}

async function preloadBatchImages(posts, timeoutMs = 8000) {
  if (!posts || posts.length === 0) return;
  const urls = posts.map(getPostCardImageUrl).filter(Boolean);
  if (urls.length === 0) return;
  const preloadPromises = urls.map(preloadSingleImage);
  const timeoutPromise = new Promise(resolve => setTimeout(resolve, timeoutMs));
  await Promise.race([
    Promise.all(preloadPromises),
    timeoutPromise
  ]);
}

let feedNextCardIndexSeq = 0;

function renderBatchCards(posts, offset = 0) {
  const container = document.getElementById('feedContainer');
  if (!container || !posts) return;
  posts.forEach((post, i) => {
    const cardIndex = Math.max(offset + i, feedNextCardIndexSeq++);
    if (cardIndex >= feedNextCardIndexSeq) feedNextCardIndexSeq = cardIndex + 1;
    const card = createPostCardElement(post, cardIndex);
    container.appendChild(card);
    setupCarouselGestures(cardIndex);
  });
  if (offset === 0 && typeof scheduleFirstTimeCleanPeekDemo === 'function') {
    scheduleFirstTimeCleanPeekDemo();
  }
}

let isNextBatchReady = false;
let swipeBlockedListenerAttached = false;

function appendBatchEndBarrier(batchIndex, currentCount, totalCount) {
  const container = document.getElementById('feedContainer');
  if (!container) return;

  const existing = document.getElementById('feedBatchEndBarrier');
  if (existing) existing.remove();

  const barrier = document.createElement('div');
  barrier.className = 'feed-batch-end-barrier';
  barrier.id = 'feedBatchEndBarrier';

  const isTrulyCaughtUp = (currentCount >= totalCount) && (!feedCloudHasMore || currentFilter !== 'all');
  if (isTrulyCaughtUp) {
    barrier.innerHTML = `
      <div class="batch-barrier-card">
        <div class="batch-barrier-pill">✦ ALL STORIES CAUGHT UP ✦</div>
        <h4 class="batch-barrier-title">You've reached the end of the feed</h4>
        <p class="batch-barrier-sub">All ${totalCount} original editorial stories have been read. Check back soon for new slants!</p>
      </div>
    `;
  } else {
    const remainingCount = totalCount > currentCount ? ` (${currentCount} OF ${totalCount} STORIES)` : '';
    barrier.innerHTML = `
      <div class="batch-barrier-card">
        <div class="batch-barrier-pill">✦ BATCH ${batchIndex + 1} COMPLETE${remainingCount} ✦</div>
        <h4 class="batch-barrier-title">Swipe up to load next 12 stories</h4>
        <p class="batch-barrier-sub">The next set of 12 original editorial postcards is ready.</p>
        <button class="batch-barrier-action-btn" id="loadNextBatchBtn" onclick="triggerNextFeedBatch()">
          <span>Load Next 12 Stories</span>
          <span class="batch-barrier-arrow">➔</span>
        </button>
      </div>
    `;
  }
  container.appendChild(barrier);
  if (typeof observeFeedBatchEndBarrier === 'function') {
    observeFeedBatchEndBarrier();
  }
}

async function triggerNextFeedBatch() {
  if (isBatchLoading) return;
  if (!currentBatchFilteredPosts) currentBatchFilteredPosts = [];

  const nextStartIdx = (currentRenderedBatch + 1) * FEED_BATCH_SIZE;

  // If we have rendered all currently loaded posts, check if more exist on the server
  if (nextStartIdx >= currentBatchFilteredPosts.length) {
    if (feedCloudHasMore && currentFilter === 'all') {
      isBatchLoading = true;
      const batchLoader = document.getElementById('feedBatchLoader');
      if (batchLoader) {
        batchLoader.style.display = 'flex';
        const bVid = batchLoader.querySelector('video');
        if (bVid) {
          try {
            bVid.currentTime = 0;
            const p = bVid.play();
            if (p !== undefined) p.catch(() => {});
          } catch (_) {}
        }
      }

      try {
        const nextOffset = allPosts.length;
        const apiResp = await fetch(`/api/posts?offset=${nextOffset}&limit=${FEED_BATCH_SIZE}&ts=${Date.now()}`);
        if (apiResp.ok) {
          const data = await apiResp.json();
          if (data && Array.isArray(data.deletedIds) && data.deletedIds.length > 0) {
            applyDeletedPostsTombstone(data.deletedIds);
          }
          if (data && Array.isArray(data.posts) && data.posts.length > 0) {
            mergeAndSortPosts(data.posts);
            if (data.total) feedCloudTotal = data.total;
            feedCloudHasMore = (data.hasMore === true);
            currentBatchFilteredPosts = getFilteredPostsForFilter(allPosts, currentFilter, searchQuery);
          } else {
            feedCloudHasMore = false;
          }
        } else {
          feedCloudHasMore = false;
        }
      } catch (err) {
        console.warn('Error loading older batch from server:', err);
        feedCloudHasMore = false;
      }

      if (batchLoader) {
        batchLoader.style.display = 'none';
        const bVid = batchLoader.querySelector('video');
        if (bVid) {
          try { bVid.pause(); } catch (_) {}
        }
      }
      isBatchLoading = false;
    }

    if (nextStartIdx >= currentBatchFilteredPosts.length) {
      showTemporaryToast('You are all caught up! ✨');
      const barrier = document.getElementById('feedBatchEndBarrier');
      if (barrier) {
        appendBatchEndBarrier(currentRenderedBatch, currentBatchFilteredPosts.length, currentBatchFilteredPosts.length);
      }
      return;
    }
  }

  isBatchLoading = true;
  const nextBatch = currentBatchFilteredPosts.slice(nextStartIdx, nextStartIdx + FEED_BATCH_SIZE);
  const wasAlreadyReady = isNextBatchReady;

  // Show bottom logo video batch loader
  const batchLoader = document.getElementById('feedBatchLoader');
  if (batchLoader) {
    batchLoader.style.display = 'flex';
    const bVid = batchLoader.querySelector('video');
    if (bVid) {
      try {
        bVid.currentTime = 0;
        const p = bVid.play();
        if (p !== undefined) p.catch(() => {});
      } catch (_) {}
    }
  }

  // If next batch was NOT ready, logo video keeps looping until ALL 12 are loaded!
  try {
    if (nextBatchPreloadPromise) {
      await nextBatchPreloadPromise;
    } else {
      await preloadBatchImages(nextBatch, 15000);
    }
    // If it had to wait on network, give smooth 1.2s minimum loop transition so it doesn't jerk
    if (!wasAlreadyReady) {
      await new Promise(r => setTimeout(r, 1200));
    }
  } catch (err) {
    console.warn('Batch preload warning:', err);
  }

  // Remove old barrier
  const oldBarrier = document.getElementById('feedBatchEndBarrier');
  if (oldBarrier) oldBarrier.remove();

  // Hide batch video loader
  if (batchLoader) {
    batchLoader.style.display = 'none';
    const bVid = batchLoader.querySelector('video');
    if (bVid) {
      try { bVid.pause(); } catch (_) {}
    }
  }

  // Render the next 12 cards
  renderBatchCards(nextBatch, nextStartIdx);
  currentRenderedBatch++;

  // Place the new barrier at the end of this batch
  const effectiveTotal = feedCloudTotal && feedCloudTotal > currentBatchFilteredPosts.length ? feedCloudTotal : currentBatchFilteredPosts.length;
  appendBatchEndBarrier(currentRenderedBatch, Math.min((currentRenderedBatch + 1) * FEED_BATCH_SIZE, currentBatchFilteredPosts.length), effectiveTotal);

  isBatchLoading = false;
  isNextBatchReady = false;

  // Smoothly scroll to the first card of the new batch
  const firstNewPost = nextBatch && nextBatch[0];
  const firstNewCard = (firstNewPost && document.getElementById(`post-${firstNewPost.id}`)) || document.getElementById(`post-card-${nextStartIdx}`);
  if (firstNewCard) {
    firstNewCard.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  // Silently pre-cache upcoming batch in background
  const upcomingStartIdx = (currentRenderedBatch + 1) * FEED_BATCH_SIZE;
  const upcomingBatch = currentBatchFilteredPosts.slice(upcomingStartIdx, upcomingStartIdx + FEED_BATCH_SIZE);
  if (upcomingBatch.length > 0) {
    nextBatchPreloadPromise = preloadBatchImages(upcomingBatch, 15000).then(() => {
      isNextBatchReady = true;
    });
  } else {
    nextBatchPreloadPromise = null;
  }
}

// Global alias for compatibility
const loadNextFeedBatch = triggerNextFeedBatch;

let isFeedBarrierVisible = false;
let feedBarrierObserver = null;

function observeFeedBatchEndBarrier() {
  const barrier = document.getElementById('feedBatchEndBarrier');
  if (!barrier || typeof IntersectionObserver === 'undefined') return;
  if (feedBarrierObserver) {
    feedBarrierObserver.disconnect();
  }
  feedBarrierObserver = new IntersectionObserver((entries) => {
    for (const entry of entries) {
      isFeedBarrierVisible = entry.isIntersecting;
    }
  }, { rootMargin: '120px 0px' });
  feedBarrierObserver.observe(barrier);
}

function setupSwipeBlockedListener() {
  observeFeedBatchEndBarrier();
  if (swipeBlockedListenerAttached) return;
  swipeBlockedListenerAttached = true;

  let touchStartY = 0;
  let isTriggering = false;

  window.addEventListener('touchstart', (e) => {
    if (e.touches && e.touches[0]) {
      touchStartY = e.touches[0].clientY;
    }
  }, { passive: true });

  window.addEventListener('touchmove', (e) => {
    if (isBatchLoading || isTriggering || !isFeedBarrierVisible) return;
    if (e.touches && e.touches[0]) {
      const currentY = e.touches[0].clientY;
      const diff = touchStartY - currentY; // positive = dragged up against bottom block
      if (diff > 50) {
        isTriggering = true;
        triggerNextFeedBatch();
        setTimeout(() => { isTriggering = false; }, 1500);
      }
    }
  }, { passive: true });

  // On desktop / trackpad: wheel scroll past bottom
  window.addEventListener('wheel', (e) => {
    if (isBatchLoading || isTriggering || !isFeedBarrierVisible || e.deltaY <= 25) return;
    isTriggering = true;
    triggerNextFeedBatch();
    setTimeout(() => { isTriggering = false; }, 1500);
  }, { passive: true });
}

function getPostFromIndexOrId(indexOrId) {
  if (indexOrId === 'preview') return (typeof currentSynthesizedPost !== 'undefined' ? currentSynthesizedPost : null);
  if (indexOrId === 'sample') return (typeof window.currentSampleStoryPost !== 'undefined' ? window.currentSampleStoryPost : null);
  if (typeof indexOrId === 'string' && indexOrId.startsWith('sample_')) {
    const sampleIdx = parseInt(indexOrId.replace('sample_', ''), 10);
    const selectedPosts = window._selectedSamplePosts || [];
    if (selectedPosts[sampleIdx] && selectedPosts[sampleIdx].post) {
      return selectedPosts[sampleIdx].post;
    }
  }
  if (typeof indexOrId === 'number' || (typeof indexOrId === 'string' && /^\d+$/.test(indexOrId))) {
    // First check DOM card with matching carousel-<idx> to resolve exact post ID even after in-place deletions
    const carouselEl = document.getElementById(`carousel-${indexOrId}`);
    if (carouselEl) {
      const parentCard = carouselEl.closest('.post-card');
      const domPostId = parentCard && parentCard.getAttribute('data-post-id');
      if (domPostId) {
        const byDomId = (typeof allPosts !== 'undefined' && allPosts.find(p => p && p.id === domPostId));
        if (byDomId) return byDomId;
      }
    }
    const idx = parseInt(indexOrId, 10);
    return (typeof currentBatchFilteredPosts !== 'undefined' && currentBatchFilteredPosts[idx]) || (typeof allPosts !== 'undefined' && allPosts[idx]) || null;
  }
  return (typeof allPosts !== 'undefined' && allPosts.find(p => p && p.id === indexOrId)) ||
    (typeof FEATURED_LOGIN_POSTS !== 'undefined' && FEATURED_LOGIN_POSTS.find(p => p && p.id === indexOrId)) ||
    null;
}

function getFilteredPostsForFilter(posts, filter, query) {
  if (!Array.isArray(posts)) return [];
  const q = (query || '').toLowerCase().trim();
  const isChroniclesFilter = (filter === 'daily_chronicles' || filter === 'diary');

  const matchesQuery = (post) => {
    if (!q) return true;
    const title = (post.adaptedHeadline || post.originalHeadline || '').toLowerCase();
    const pub = (post.publicationName || '').toLowerCase();
    const summary = (post.summary || '').toLowerCase();
    const hook = (post.hook || '').toLowerCase();
    const cat = (post.categoryBadge || '').toLowerCase();
    return title.includes(q) || pub.includes(q) || summary.includes(q) || hook.includes(q) || cat.includes(q);
  };

  const result = posts.filter(post => {
    if (!post || post.deleted || post.isDeleted || deletedPostIds.has(post.id) || isLoginShowcaseOnlyPost(post)) return false;

    const isChronicleDiary = isPostChronicleDiary(post);
    const isPrivateDraft = isPostPrivateOrDraft(post);
    const isOwnedByMe = isPostOwnedByCurrentUser(post);
    const deepPostId = typeof getDeepLinkedPostId === 'function' ? getDeepLinkedPostId() : null;

    // Private diary entries must NEVER be visible to anyone other than their creator (not even via deep link)
    if (isChronicleDiary && !isOwnedByMe) {
      return false;
    }

    // Never render an encrypted diary card that has not been decrypted by the owner's key
    if (isChronicleDiary && post.encryptedDiaryPayload && !post._diaryDecrypted) {
      return false;
    }

    // Unpublished perspective drafts must NEVER be visible to anyone other than their creator (not even via deep link)
    if (isPrivateDraft && !isOwnedByMe) {
      return false;
    }

    // Dedicated "Daily Chronicles" section: strictly private to creator, shows non-draft chronicle entries
    if (isChroniclesFilter) {
      if (!isChronicleDiary || post.isDiaryDraftOnly || !isOwnedByMe) return false;
      return matchesQuery(post);
    }

    // Dedicated "Drafts" section: shows unpublished perspective drafts and draft-only chronicle entries
    if (filter === 'drafts') {
      if (!isOwnedByMe) return false;
      if (isChronicleDiary) {
        return Boolean(post.isDiaryDraftOnly) && matchesQuery(post);
      }
      return isPrivateDraft && matchesQuery(post);
    }

    // STRICT SEPARATION: Daily Chronicle posts NEVER appear in the regular feed ('all', 'my_stories', 'saved', 'opinion', or topic categories)
    if (isChronicleDiary) {
      return false;
    }

    if (filter === 'saved') {
      if (!savedPostIds.has(post.id)) return false;
      if (activeSavedBucketFilter && activeSavedBucketFilter !== 'all' && Array.isArray(saveBuckets)) {
        const targetBucket = saveBuckets.find(b => b && b.id === activeSavedBucketFilter);
        if (targetBucket && Array.isArray(targetBucket.postIds) && !targetBucket.postIds.includes(post.id)) {
          return false;
        }
      }
      return matchesQuery(post);
    }

    if (filter === 'series') {
      if (activeFeedSeriesFilter === '__new__') return false;
      const sInfo = getPostSeriesInfo(post);
      if (!sInfo) return false;
      // Only owner can see private series posts; other users only see public posts in a series
      if (isPrivateDraft && !isOwnedByMe) return false;
      if (activeFeedSeriesFilter && activeFeedSeriesFilter !== 'all') {
        return sInfo.id === activeFeedSeriesFilter && matchesQuery(post);
      }
      return isOwnedByMe && matchesQuery(post);
    }

    if (filter === 'my_stories') {
      if (!isOwnedByMe) return false;
      const sInfo = getPostSeriesInfo(post);
      // Show all published stories plus any private posts that belong to a Series
      return (!isPrivateDraft || Boolean(sInfo)) && matchesQuery(post);
    }

    // Hide unpublished drafts from regular feed and topic categories (unless directly deep-linked by the owner)
    if (isPrivateDraft && (post.id !== deepPostId || !isOwnedByMe)) {
      return false;
    }

    if (filter !== 'all') {
      const cat = (post.categoryBadge || '').toLowerCase();
      const type = (post.sourceType || '').toLowerCase();
      const isMySlant = post.isMySlant === true || type === 'my_slant' || type === 'inner_voice' || (post.publicationName || '').toLowerCase().includes('my slant') || (post.publicationName || '').toLowerCase().includes('inner voice');
      if (filter === 'opinion' && !(isMySlant || cat.includes('opinion') || cat.includes('slant') || cat.includes('op-ed') || cat.includes('editorial') || cat.includes('perspective'))) return false;
      if (filter === 'tech' && !(cat.includes('tech') || cat.includes('quantum') || cat.includes('ai') || cat.includes('astro'))) return false;
      if (filter === 'health' && !(cat.includes('health') || cat.includes('cures') || cat.includes('bio'))) return false;
      if (filter === 'climate' && !(cat.includes('climate') || cat.includes('energy') || cat.includes('renewable'))) return false;
      if (filter === 'economy' && !(cat.includes('economy') || cat.includes('global') || cat.includes('market') || cat.includes('capital') || cat.includes('finance'))) return false;
      if (filter === 'literary' && !(type === 'book_excerpt' || cat.includes('literary') || cat.includes('book') || cat.includes('literature'))) return false;
    }

    return matchesQuery(post);
  });

  // Ensure Daily Chronicles are strictly ordered from latest to oldest
  if (isChroniclesFilter) {
    result.sort((a, b) => {
      const timeA = new Date(a.createdAt || a.created_at || a.date || 0).getTime();
      const timeB = new Date(b.createdAt || b.created_at || b.date || 0).getTime();
      return timeB - timeA;
    });
  }

  return result;
}

