let isFamilyCastFetching = false;
window._familyVaultPendingIncoming = [];
window._familyVaultPendingOutgoing = [];
window._familyVaultApprovedLinks = [];
window._familyVaultNeedsOnboarding = false;
window._vaultOnboardingPromptedThisSession = false;

async function loadFamilyCastProfile(forceRefresh = false) {
  try {
    localStorage.removeItem('slant_family_cast');
  } catch (_) {}

  if (!currentUser || !currentUser.email) {
    familyCastProfileCache = getDefaultClientFamilyCast();
    return familyCastProfileCache;
  }

  const storageKey = getFamilyCastLocalStorageKey();
  const local = storageKey ? localStorage.getItem(storageKey) : null;
  if (local && !familyCastProfileCache) {
    try {
      familyCastProfileCache = sanitizeLoadedFamilyCast(JSON.parse(local));
    } catch (_) {}
  }

  // If local cache exists and not forcing cloud refresh, return immediately
  // but trigger background cloud revalidation so multi-device updates sync seamlessly
  if (familyCastProfileCache && !forceRefresh) {
    if (!isFamilyCastFetching) {
      setTimeout(() => {
        loadFamilyCastProfile(true).catch(() => {});
      }, 50);
    }
    return familyCastProfileCache;
  }

  if (isFamilyCastFetching) {
    return familyCastProfileCache || getDefaultClientFamilyCast();
  }

  isFamilyCastFetching = true;
  const userIdentifier = currentUser.email.trim().toLowerCase();
  try {
    const resp = await fetch('/api/synthesize', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'get_family_cast',
        userIdentifier
      })
    });
    if (resp.ok) {
      const data = await resp.json();
      window._familyVaultPendingIncoming = Array.isArray(data?.pendingIncoming) ? data.pendingIncoming : [];
      window._familyVaultPendingOutgoing = Array.isArray(data?.pendingOutgoing) ? data.pendingOutgoing : [];
      window._familyVaultApprovedLinks = Array.isArray(data?.approvedLinks) ? data.approvedLinks : [];
      window._familyVaultNeedsOnboarding = Boolean(data?.needsOnboarding);

      renderFamilyApprovalNotificationsUI();

      if (data && data.cast && Array.isArray(data.cast.members)) {
        familyCastProfileCache = sanitizeLoadedFamilyCast(data.cast);

        // If this user has no Self profile yet (first login), pre-seed a Self card with their display name
        const hasSelfMember = familyCastProfileCache.members.some(m => m && (m.relationship === 'self' || m.id === 'member_father'));
        if (!hasSelfMember && !isCurrentClientUserShridhar()) {
          const initialName = cleanVaultShortName(currentUser.displayName || currentUser.name || userIdentifier.split('@')[0], '');
          const selfSeed = {
            id: 'member_father',
            relationship: 'self',
            roleLabel: 'Self',
            name: initialName,
            aliases: initialName ? [initialName.toLowerCase(), 'myself', 'me', 'i'] : ['myself', 'me', 'i'],
            age: null,
            heightCm: 170,
            heightDesc: '5ft 7in (170cm) • 100% baseline',
            structuredTraits: {
              bodyVolume: 'medium',
              tummyProfile: 'subtle_10',
              faceFullness: 'oval_balanced',
              heightCm: 170,
              baseHeightRatio: 1.00,
              hairStyle: 'short_side_part',
              facialHair: 'none',
              landmarks: []
            },
            uncompromisableAnchors: '',
            visualTraits: '',
            vehicleRole: 'driver_right',
            photoBase64: null,
            photos: {}
          };
          familyCastProfileCache.members.unshift(selfSeed);
          window._familyVaultNeedsOnboarding = true;
        }

        try {
          if (storageKey) {
            localStorage.setItem(storageKey, JSON.stringify(familyCastProfileCache));
          }
        } catch (_) {}

        const currentSlant = (document.getElementById('creatorSlantTakeInput')?.value || '') + ' ' + (document.getElementById('creatorSparkInput')?.value || '');
        if (!window._userManuallyToggledCast && currentSlant.trim()) {
          checkAndTriggerFamilyCast(currentSlant);
        }

        if (!activeVaultMemberId && familyCastProfileCache.members.length > 0) {
          activeVaultMemberId = familyCastProfileCache.members[0].id;
        }

        const modal = document.getElementById('familyCastModal');
        if (modal && (modal.classList.contains('open') || modal.classList.contains('active'))) {
          const activeEl = document.activeElement;
          const isTyping = activeEl && (activeEl.tagName === 'INPUT' || activeEl.tagName === 'TEXTAREA' || activeEl.tagName === 'SELECT');
          renderVaultMemberTabs();
          if (!isTyping) {
            renderActiveMemberScreen();
          }
        }
        renderFamilyCastStagingUI();

        // Automatically prompt First-Login Reference & Family Vault setup if user has not configured their Self reference yet
        const onboardingDismissedKey = 'slant_vault_onboard_prompted_' + userIdentifier;
        if (window._familyVaultNeedsOnboarding && !window._vaultOnboardingPromptedThisSession && !sessionStorage.getItem(onboardingDismissedKey)) {
          window._vaultOnboardingPromptedThisSession = true;
          try { sessionStorage.setItem(onboardingDismissedKey, '1'); } catch (_) {}
          setTimeout(() => {
            openFamilyCastModal({ isOnboarding: true });
          }, 900);
        }

        isFamilyCastFetching = false;
        return familyCastProfileCache;
      }
    }
  } catch (err) {
    console.warn('Load family cast error:', err);
  } finally {
    isFamilyCastFetching = false;
  }

  if (!familyCastProfileCache) {
    familyCastProfileCache = getDefaultClientFamilyCast();
    try {
      if (storageKey) {
        localStorage.setItem(storageKey, JSON.stringify(familyCastProfileCache));
      }
    } catch (_) {}
  }
  return familyCastProfileCache;
}

async function saveFamilyCastProfile(updatedCast) {
  if (!updatedCast || !Array.isArray(updatedCast.members)) return;
  try {
    localStorage.removeItem('slant_family_cast');
  } catch (_) {}
  if (!currentUser || !currentUser.email) return;

  const cleanCast = sanitizeLoadedFamilyCast(updatedCast);
  familyCastProfileCache = cleanCast;
  const storageKey = getFamilyCastLocalStorageKey();
  try {
    if (storageKey) {
      localStorage.setItem(storageKey, JSON.stringify(cleanCast));
    }
  } catch (_) {}

  const userIdentifier = currentUser.email.trim().toLowerCase();
  try {
    fetch('/api/synthesize', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'save_family_cast',
        userIdentifier,
        cast: cleanCast
      })
    }).catch(() => {});
  } catch (_) {}
}

function openFamilyCastModal(options = {}) {
  const modal = document.getElementById('familyCastModal');
  if (!modal) {
    console.warn('familyCastModal not found');
    return;
  }

  const onboardBanner = document.getElementById('vaultOnboardingBanner');
  if (onboardBanner) {
    const showOnboard = Boolean((options && options.isOnboarding) || window._familyVaultNeedsOnboarding);
    onboardBanner.style.display = showOnboard ? 'flex' : 'none';
  }

  renderFamilyApprovalNotificationsUI();

  // Pre-render with cached data or defaults
  const cast = familyCastProfileCache || getDefaultClientFamilyCast();
  if (!activeVaultMemberId && cast.members?.length > 0) {
    activeVaultMemberId = cast.members[0].id;
  }

  try {
    renderVaultMemberTabs();
    renderActiveMemberScreen();
  } catch (err) {
    console.error('Error rendering cast modal:', err);
  }

  // If opening for first-login onboarding, automatically expand the Name/Age/Height details accordion
  if ((options && options.isOnboarding) || window._familyVaultNeedsOnboarding) {
    setTimeout(() => {
      const detailsEl = document.getElementById('vaultMemberDetailsAccordion');
      if (detailsEl) detailsEl.open = true;
    }, 150);
  }

  // Always force cloud revalidation when modal is opened so updates from mobile sync immediately
  loadFamilyCastProfile(true).then((freshCast) => {
    if (freshCast && Array.isArray(freshCast.members) && freshCast.members.length > 0) {
      if (!activeVaultMemberId || !freshCast.members.some(m => m.id === activeVaultMemberId)) {
        activeVaultMemberId = freshCast.members[0].id;
      }
    }
    const activeEl = document.activeElement;
    const isTyping = activeEl && (activeEl.tagName === 'INPUT' || activeEl.tagName === 'TEXTAREA' || activeEl.tagName === 'SELECT');
    renderVaultMemberTabs();
    if (!isTyping) {
      renderActiveMemberScreen();
    }
  }).catch(() => {});

  modal.classList.add('open');
  modal.classList.add('active');
  modal.style.display = 'flex';
  modal.style.opacity = '1';
  modal.style.visibility = 'visible';
  modal.style.pointerEvents = 'auto';
  document.body.style.overflow = 'hidden';
}

function dismissVaultOnboardingBanner() {
  window._familyVaultNeedsOnboarding = false;
  const el = document.getElementById('vaultOnboardingBanner');
  if (el) el.style.display = 'none';
}

function renderFamilyApprovalNotificationsUI() {
  const pending = Array.isArray(window._familyVaultPendingIncoming) ? window._familyVaultPendingIncoming : [];
  const globalBanner = document.getElementById('familyApprovalNotificationBanner');
  const vaultBar = document.getElementById('vaultIncomingRequestsBar');
  const drawerBadge = document.getElementById('drawerFamilyPendingBadge');

  if (drawerBadge) {
    if (pending.length > 0) {
      drawerBadge.textContent = String(pending.length);
      drawerBadge.style.display = 'inline-block';
    } else {
      drawerBadge.style.display = 'none';
    }
  }

  const buildItemsHtml = () => pending.map(req => {
    const reqName = escapeHtml(req.requesterName || req.fromName || req.requesterHandle || req.fromHandle || req.requesterEmail || req.fromEmail || 'A Slant member');
    const rawHandle = req.requesterHandle || req.fromHandle || '';
    const reqHandle = rawHandle ? ` (${escapeHtml(rawHandle)})` : '';
    const relLabel = escapeHtml(req.targetRoleLabel || req.relationLabel || req.relationshipToRequester || req.relationship || 'Family Member');
    const safeId = escapeHtml(req.id || '');
    return `
      <div class="family-notif-item">
        <div class="family-notif-info">
          <div class="family-notif-title">👥 Family Vault &amp; Photo Reference Request</div>
          <div class="family-notif-desc">
            <strong>${reqName}</strong>${reqHandle} added you as <strong>${relLabel}</strong> and requested permission to use your reference likeness when generating family illustrations &amp; share the Family Vault.
          </div>
        </div>
        <div class="family-notif-actions">
          <button type="button" class="family-notif-approve-btn" onclick="respondToFamilyVaultRequest('${safeId}', 'approve')">✓ Approve &amp; Share Vault</button>
          <button type="button" class="family-notif-decline-btn" onclick="respondToFamilyVaultRequest('${safeId}', 'decline')">✕ Decline</button>
        </div>
      </div>
    `;
  }).join('');

  if (globalBanner) {
    if (pending.length > 0 && currentUser && currentUser.email) {
      globalBanner.innerHTML = buildItemsHtml();
      globalBanner.style.display = 'block';
    } else {
      globalBanner.innerHTML = '';
      globalBanner.style.display = 'none';
    }
  }

  if (vaultBar) {
    if (pending.length > 0) {
      vaultBar.innerHTML = buildItemsHtml();
      vaultBar.style.display = 'block';
    } else {
      vaultBar.innerHTML = '';
      vaultBar.style.display = 'none';
    }
  }
}

let _vaultSlantSearchTimer = null;

function toggleVaultSlantSearchPanel(forceState) {
  const panel = document.getElementById('vaultLinkSlantUserPanel');
  if (!panel) return;
  const shouldOpen = typeof forceState === 'boolean'
    ? forceState
    : (panel.style.display === 'none' || !panel.style.display);
  panel.style.display = shouldOpen ? 'block' : 'none';
  if (shouldOpen) {
    const input = document.getElementById('vaultSlantUserSearchInput');
    if (input) {
      input.focus();
      searchSlantUsersForFamilyVault(input.value || '');
    }
  }
}

function onVaultSlantSearchInput(val) {
  if (_vaultSlantSearchTimer) clearTimeout(_vaultSlantSearchTimer);
  _vaultSlantSearchTimer = setTimeout(() => {
    searchSlantUsersForFamilyVault(val);
  }, 220);
}

async function searchSlantUsersForFamilyVault(query = '') {
  const resultsEl = document.getElementById('vaultSlantUserSearchResults');
  if (!resultsEl || !currentUser || !currentUser.email) return;

  resultsEl.innerHTML = '<div style="font-size:11.5px; color:#94A3B8; padding:6px 4px;">Searching Slant directory...</div>';
  try {
    const viewerEmail = currentUser.email.trim().toLowerCase();
    const resp = await fetch('/api/synthesize', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'search_slant_users',
        query: String(query || '').trim(),
        viewerEmail,
        requesterEmail: viewerEmail
      })
    });
    if (!resp.ok) throw new Error('Search request failed');
    const data = await resp.json();
    const users = Array.isArray(data?.users) ? data.users : [];
    if (users.length === 0) {
      resultsEl.innerHTML = '<div style="font-size:11.5px; color:#94A3B8; padding:6px 4px;">No matching Slant users found. Try typing their name, @handle, or full Gmail address.</div>';
      return;
    }

    const outgoingSet = new Set((window._familyVaultPendingOutgoing || []).map(r => String(r.targetEmail || r.toEmail || '').toLowerCase()));
    const approvedSet = new Set((window._familyVaultApprovedLinks || []).flatMap(r => [
      String(r.requesterEmail || r.fromEmail || '').toLowerCase(),
      String(r.targetEmail || r.toEmail || '').toLowerCase()
    ]));

    resultsEl.innerHTML = users.map(u => {
      const email = String(u.email || '').trim().toLowerCase();
      const name = u.name || email.split('@')[0];
      const handle = u.handle || ('@' + name.replace(/\s+/g, ''));
      const isApproved = approvedSet.has(email);
      const isPending = outgoingSet.has(email);
      const initials = String(name || 'U').trim().charAt(0).toUpperCase();
      const safeEmail = escapeHtml(email);
      const safeName = escapeHtml(name).replace(/'/g, '&#39;');
      const safeHandle = escapeHtml(handle).replace(/'/g, '&#39;');

      return `
        <div class="vault-link-user-row">
          <div class="vault-link-user-meta">
            ${u.avatarUrl ? `<img src="${escapeHtml(u.avatarUrl)}" class="vault-link-user-avatar" alt="">` : `<span class="vault-link-user-avatar">${escapeHtml(initials)}</span>`}
            <div style="min-width:0;">
              <div class="vault-link-user-name">${escapeHtml(name)} <span style="font-weight:500; color:#38BDF8;">${escapeHtml(handle)}</span></div>
              <div class="vault-link-user-sub">${escapeHtml(email)}${u.hasVaultSelf ? ' • ✓ Reference Vault Ready' : ''}</div>
            </div>
          </div>
          ${isApproved
            ? `<span class="vault-tab-status-pill is-shared">✓ Linked in Family Vault</span>`
            : (isPending
                ? `<span class="vault-tab-status-pill is-pending">⏳ Approval Sent</span>`
                : `<button type="button" class="vault-link-send-btn" onclick="sendFamilyVaultLinkRequest('${safeEmail}', '${safeName}', '${safeHandle}')">+ Send Request</button>`
              )}
        </div>
      `;
    }).join('');
  } catch (err) {
    resultsEl.innerHTML = '<div style="font-size:11.5px; color:#FCA5A5; padding:6px 4px;">Could not search Slant directory right now.</div>';
  }
}

async function sendFamilyVaultLinkRequest(targetEmail, targetName, targetHandle) {
  if (!currentUser || !currentUser.email || !targetEmail) return;
  const relSelect = document.getElementById('vaultSlantUserRelationSelect');
  const rawRel = (relSelect && relSelect.value) ? relSelect.value : 'spouse|Spouse';
  const [relationship, roleLabel] = rawRel.split('|');

  const selfMember = (familyCastProfileCache && Array.isArray(familyCastProfileCache.members))
    ? familyCastProfileCache.members.find(m => m && (m.relationship === 'self' || m.id === 'member_father'))
    : null;
  const requesterEmail = currentUser.email.trim().toLowerCase();
  const requesterName = (selfMember && selfMember.name) || currentUser.displayName || currentUser.name || requesterEmail.split('@')[0];
  const requesterHandle = currentUser.handle || ('@' + String(requesterName).replace(/\s+/g, ''));

  try {
    const resp = await fetch('/api/synthesize', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'send_family_vault_request',
        fromEmail: requesterEmail,
        requesterEmail,
        fromName: requesterName,
        requesterName,
        fromHandle: requesterHandle,
        requesterHandle,
        toEmail: targetEmail,
        targetEmail,
        toName: targetName,
        targetName,
        toHandle: targetHandle,
        targetHandle,
        relationship: relationship || 'family',
        relationLabel: roleLabel || relationship || 'Family Member',
        roleLabel: roleLabel || relationship || 'Family Member'
      })
    });
    const data = await resp.json();
    if (data && data.success) {
      showTemporaryToast(`✓ Sent Family Vault request to ${targetName || targetEmail} (${roleLabel})!`);
      await loadFamilyCastProfile(true);
      try {
        renderVaultMemberTabs();
        renderActiveMemberScreen();
      } catch (_) {}
      const q = document.getElementById('vaultSlantUserSearchInput')?.value || '';
      searchSlantUsersForFamilyVault(q);
    } else {
      showTemporaryToast(data?.error || 'Could not send family request.');
    }
  } catch (err) {
    showTemporaryToast('Network error sending family request.');
  }
}

async function respondToFamilyVaultRequest(requestId, decision) {
  if (!currentUser || !currentUser.email || !requestId) return;
  const responderEmail = currentUser.email.trim().toLowerCase();
  try {
    const resp = await fetch('/api/synthesize', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'respond_family_vault_request',
        requestId,
        userIdentifier: responderEmail,
        responderEmail,
        decision
      })
    });
    const data = await resp.json();
    if (data && data.success) {
      window._familyVaultPendingIncoming = Array.isArray(data.pendingIncoming) ? data.pendingIncoming : [];
      window._familyVaultPendingOutgoing = Array.isArray(data.pendingOutgoing) ? data.pendingOutgoing : [];
      window._familyVaultApprovedLinks = Array.isArray(data.approvedLinks) ? data.approvedLinks : [];
      window._familyVaultNeedsOnboarding = Boolean(data.needsOnboarding);
      renderFamilyApprovalNotificationsUI();

      if (data.cast && Array.isArray(data.cast.members)) {
        familyCastProfileCache = sanitizeLoadedFamilyCast(data.cast);
        const storageKey = getFamilyCastLocalStorageKey();
        try {
          if (storageKey) localStorage.setItem(storageKey, JSON.stringify(familyCastProfileCache));
        } catch (_) {}
        if (familyCastProfileCache.members.length > 0 && (!activeVaultMemberId || !familyCastProfileCache.members.some(m => m.id === activeVaultMemberId))) {
          activeVaultMemberId = familyCastProfileCache.members[0].id;
        }
      }

      showTemporaryToast(
        decision === 'approve'
          ? '✓ Approved! Shared Family Vault & reference likeness access is now active for all linked family members.'
          : 'Family Vault request declined.'
      );
      await loadFamilyCastProfile(true);
      try {
        renderVaultMemberTabs();
        renderActiveMemberScreen();
        renderFamilyCastStagingUI();
      } catch (_) {}
    } else {
      showTemporaryToast(data?.error || 'Could not process family request response.');
    }
  } catch (err) {
    showTemporaryToast('Network error responding to family request.');
  }
}

function closeFamilyCastModal() {
  const modal = document.getElementById('familyCastModal');
  if (modal) {
    modal.classList.remove('open');
    modal.classList.remove('active');
    modal.style.display = 'none';
    modal.style.opacity = '';
    modal.style.visibility = '';
    modal.style.pointerEvents = '';
  }
  document.body.style.overflow = '';
  renderFamilyCastStagingUI();
}

let activeVaultMemberId = null;
let activeVaultPoseSlotIdx = 0;
let isAnalyzingVaultPhotos = false;

function toggleInfoTip(event, tipId) {
  if (event) {
    event.stopPropagation();
    event.preventDefault();
  }
  const el = document.getElementById(tipId);
  if (!el) return;
  const isHidden = (el.style.display === 'none' || !el.style.display);
  el.style.display = isHidden ? 'block' : 'none';
}

function renderVaultMemberTabs() {
  const track = document.getElementById('vaultMemberTabsList');
  if (!track) return;

  const cast = familyCastProfileCache || getDefaultClientFamilyCast();
  const members = cast.members || [];

  if (!activeVaultMemberId && members.length > 0) {
    activeVaultMemberId = members[0].id;
  }

  const icons = {
    self: '👨',
    spouse: '👩',
    elder_son: '👦',
    younger_son: '🧒',
    child: '🧒'
  };

  const tabsHtml = members.map(m => {
    const isActive = (m.id === activeVaultMemberId);
    const photosObj = m.photos || {};
    const primaryAvatar = m.photoBase64 || photosObj.frontal || m.stylizedAvatarUrl;
    const isPending = m.approvalStatus === 'pending';
    const isShared = Boolean(m.isSharedFromSlantUser && m.approvalStatus === 'approved');
    const statusBadge = isPending
      ? `<span class="vault-tab-status-pill is-pending" title="Waiting for ${escapeHtml(m.linkedUserEmail || m.name)} to approve">⏳ Pending</span>`
      : (isShared ? `<span class="vault-tab-status-pill is-shared" title="Linked &amp; approved Shared Family Vault member">🤝 Shared</span>` : '');

    return `
      <button type="button" class="vault-member-tab-item ${isActive ? 'active' : ''}" onclick="selectVaultMember('${m.id}')" title="${escapeHtml(m.name || m.roleLabel)}">
        ${primaryAvatar ? `<img src="${primaryAvatar}" class="tab-avatar-mini" alt="">` : `<span class="tab-avatar-emoji">${icons[m.relationship] || '👤'}</span>`}
        <span>${escapeHtml(m.name || m.roleLabel)}</span>
        ${statusBadge}
      </button>
    `;
  }).join('');

  const addBtnHtml = `
    <button type="button" class="vault-member-tab-item vault-add-member-tab" onclick="addNewVaultMember()" title="Add family member">
      <span>＋</span>
    </button>
  `;

  track.innerHTML = tabsHtml + addBtnHtml;
}

function selectVaultMember(memberId) {
  activeVaultMemberId = memberId;
  activeVaultPoseSlotIdx = 0;
  const prevDetails = document.getElementById('vaultMemberDetailsAccordion');
  if (prevDetails) prevDetails.open = false;
  renderVaultMemberTabs();
  renderActiveMemberScreen();
  const body = document.getElementById('vaultActiveMemberScreen');
  if (body) body.scrollTop = 0;
}

const VAULT_POSE_CONFIGS = [
  {
    key: 'frontal',
    num: 1,
    title: 'Front Face & Smile',
    sampleImg: '/pose_guide_frontal.jpg',
    tip: 'Direct eye-level, soft daylight, natural smile.'
  },
  {
    key: 'profile',
    num: 2,
    title: '35° Turn / Jawline',
    sampleImg: '/pose_guide_profile.jpg',
    tip: 'Turn head 30–45° to capture nose slope & jawline depth.'
  },
  {
    key: 'stature',
    num: 3,
    title: 'Hair & Waist-Up Stature',
    sampleImg: '/pose_guide_stature.jpg',
    tip: 'Waist-up standing view showing natural hair volume & build.'
  }
];

function stepVaultPoseSlot(delta) {
  const total = 3;
  const nextIdx = ((activeVaultPoseSlotIdx + (delta || 1)) % total + total) % total;
  goToVaultPoseSlot(nextIdx);
}

function goToVaultPoseSlot(slotIdx) {
  activeVaultPoseSlotIdx = Math.max(0, Math.min(2, Number(slotIdx) || 0));
  const track = document.getElementById('vaultPoseTrack');
  if (!track) {
    renderActiveMemberScreen();
    return;
  }

  // Smoothly slide track in-place while keeping the outer frame 100% steady
  track.style.transform = `translateX(-${activeVaultPoseSlotIdx * (100 / 3)}%)`;

  const cast = familyCastProfileCache || getDefaultClientFamilyCast();
  const member = (cast.members || []).find(m => m.id === activeVaultMemberId);
  const photos = (member && member.photos) ? member.photos : {};
  const pose = VAULT_POSE_CONFIGS[activeVaultPoseSlotIdx];
  const currentPosePhoto = photos[pose.key] || null;

  const stepPill = document.getElementById('vaultPoseStepPill');
  if (stepPill) stepPill.textContent = `Pose ${pose.num} / 3`;

  const titleEl = document.getElementById('vaultPoseTitleText');
  if (titleEl) titleEl.textContent = pose.title;

  const tipEl = document.getElementById('vaultPoseTipBox');
  if (tipEl) tipEl.textContent = pose.tip;

  const frameEl = document.getElementById('vaultPoseViewportFrame');
  if (frameEl) {
    frameEl.classList.toggle('has-user-photo', Boolean(currentPosePhoto));
    frameEl.classList.toggle('is-sample-pose', !currentPosePhoto);
  }

  const uploadBtn = document.getElementById('vaultPosePrimaryUploadBtn');
  if (uploadBtn) {
    uploadBtn.onclick = () => triggerSlotUpload(pose.key);
    uploadBtn.innerHTML = `<span>📷 ${currentPosePhoto ? 'Change Photo' : 'Add Photo'}</span>`;
  }

  const removeBtn = document.getElementById('vaultPoseRemoveBtn');
  if (removeBtn) {
    removeBtn.style.display = currentPosePhoto ? 'inline-flex' : 'none';
    removeBtn.onclick = () => removeSlotPhoto(pose.key);
  }

  const dots = document.querySelectorAll('#vaultPoseDotsRow .vault-pose-dot');
  dots.forEach((dot, idx) => {
    dot.classList.toggle('active', idx === activeVaultPoseSlotIdx);
  });
}

function addNewVaultMember() {
  const cast = familyCastProfileCache || getDefaultClientFamilyCast();
  if (!Array.isArray(cast.members)) cast.members = [];

  const newId = 'member_' + Date.now();
  const newMember = {
    id: newId,
    relationship: 'child',
    roleLabel: 'New Member',
    name: '',
    age: null,
    heightDesc: '',
    visualTraits: '',
    aliases: [],
    vehicleRole: 'passenger_rear',
    photoBase64: null,
    photos: {}
  };

  cast.members.push(newMember);
  activeCastMemberIds.add(newId);
  saveFamilyCastProfile(cast);
  activeVaultMemberId = newId;
  activeVaultPoseSlotIdx = 0;

  renderVaultMemberTabs();
  renderActiveMemberScreen();
  renderFamilyCastStagingUI();

  setTimeout(() => {
    const detailsEl = document.getElementById('vaultMemberDetailsAccordion');
    if (detailsEl) {
      detailsEl.open = true;
      slideUpVaultMemberDetailsSection();
    }
    const nameInput = document.getElementById('vField_name');
    if (nameInput) nameInput.focus({ preventScroll: true });
  }, 100);
}

function slideUpVaultMemberDetailsSection() {
  const container = document.getElementById('vaultActiveMemberScreen');
  const detailsEl = document.getElementById('vaultMemberDetailsAccordion');
  if (!container || !detailsEl) return;

  requestAnimationFrame(() => {
    const containerRect = container.getBoundingClientRect();
    const detailsRect = detailsEl.getBoundingClientRect();
    const scrollTarget = container.scrollTop + (detailsRect.top - containerRect.top) - 8;
    container.scrollTo({
      top: Math.max(0, scrollTarget),
      behavior: 'smooth'
    });
  });
}

function renderActiveMemberScreen() {
  const container = document.getElementById('vaultActiveMemberScreen');
  if (!container) return;

  const wasDetailsOpen = Boolean(document.getElementById('vaultMemberDetailsAccordion')?.open);

  const cast = familyCastProfileCache || getDefaultClientFamilyCast();
  const members = cast.members || [];
  let member = members.find(m => m.id === activeVaultMemberId);

  if (!member) {
    if (members.length > 0) {
      member = members[0];
      activeVaultMemberId = member.id;
    } else {
      container.innerHTML = '<div style="text-align:center; padding:32px; color:var(--text-secondary);">No family members registered. Tap ＋ above.</div>';
      return;
    }
  }

  // Normalize photos object
  member.photos = member.photos || {};
  if (member.photoBase64 && !member.photos.frontal) {
    member.photos.frontal = member.photoBase64;
  }

  const isDefaultPrimary = (member.id === 'member_father');
  const photos = member.photos;

  // Calculate Next member label
  const currentIdx = members.findIndex(m => m.id === member.id);
  const hasNext = (currentIdx !== -1 && currentIdx < members.length - 1);
  const nextMember = hasNext ? members[currentIdx + 1] : null;
  const nextLabel = nextMember ? `Next: ${escapeHtml(nextMember.name || nextMember.roleLabel)} ➔` : 'Save & Done ✓';

  const saveBtnText = document.getElementById('vaultSaveNextBtnText');
  if (saveBtnText) saveBtnText.textContent = nextLabel;

  const activePoseIdx = Math.max(0, Math.min(2, activeVaultPoseSlotIdx || 0));
  const pose = VAULT_POSE_CONFIGS[activePoseIdx];
  const currentPosePhoto = photos[pose.key] || null;

  container.innerHTML = `
    <div class="vault-active-member-container">
      ${member.approvalStatus === 'pending' ? `
        <div style="margin-bottom:10px; padding:10px 12px; border-radius:11px; background:rgba(245,158,11,0.13); border:1px solid rgba(245,158,11,0.4); color:#FDE68A; font-size:11.5px; line-height:1.4;">
          <strong>⏳ Waiting for Approval from ${escapeHtml(member.name || member.linkedUserEmail || 'Slant User')} (${escapeHtml(member.roleLabel || member.relationship)}):</strong>
          An approval notification has been sent to their Slant account. For privacy, their reference likeness will only be used in photo generation once they approve, which will also unlock shared Family Vault access for everyone involved.
        </div>
      ` : (member.isSharedFromSlantUser ? `
        <div style="margin-bottom:10px; padding:9px 12px; border-radius:11px; background:rgba(16,185,129,0.12); border:1px solid rgba(16,185,129,0.35); color:#6EE7B7; font-size:11.5px; line-height:1.4;">
          <strong>🤝 Approved Shared Family Vault Member (${escapeHtml(member.roleLabel || member.relationship)}):</strong>
          Synced with <strong>${escapeHtml(member.linkedUserEmail || member.name)}</strong>. Both accounts share access to this Family Vault and can use each other's approved reference likeness in family illustrations.
        </div>
      ` : '')}
      <!-- Single-Card Steady Sliding Pose Carousel -->
      <div class="vault-pose-slider-card" id="vaultPoseSliderCard">
        <div class="vault-pose-slider-top">
          <div class="vault-pose-slider-title-group">
            <span class="vault-pose-step-pill" id="vaultPoseStepPill">Pose ${pose.num} / 3</span>
            <span class="vault-pose-stage-title" id="vaultPoseTitleText">${escapeHtml(pose.title)}</span>
            <button type="button" class="ui-info-dot-btn" onclick="toggleInfoTip(event, 'vaultPoseTipBox')" title="Pose tip">i</button>
          </div>
          <div class="vault-pose-top-right">
            ${!isDefaultPrimary ? `<button type="button" class="vault-member-delete-icon-btn" onclick="deleteActiveMember('${member.id}')" title="Remove member">🗑️</button>` : ''}
            <button type="button" class="vault-pose-next-btn" onclick="stepVaultPoseSlot(1)" title="Next Pose">
              <span>Next Pose ➔</span>
            </button>
          </div>
        </div>

        <div class="ui-info-popover-box" id="vaultPoseTipBox" style="display:none; width:100%; box-sizing:border-box;">
          ${escapeHtml(pose.tip)}
        </div>

        <!-- Steady Portrait Viewport with 3-Slide Track & Left/Right Arrows -->
        <div class="vault-pose-stage-wrap" id="vaultPoseStageTouchArea">
          <button type="button" class="vault-pose-nav-arrow prev" onclick="stepVaultPoseSlot(-1)" aria-label="Previous Pose">&#x2039;</button>

          <div class="vault-pose-portrait-frame ${currentPosePhoto ? 'has-user-photo' : 'is-sample-pose'}" id="vaultPoseViewportFrame">
            <div class="vault-pose-track" id="vaultPoseTrack" style="transform: translateX(-${activePoseIdx * (100 / 3)}%);">
              ${VAULT_POSE_CONFIGS.map((cfg) => {
                const slotPhoto = photos[cfg.key] || null;
                return `
                  <div class="vault-pose-slide" onclick="triggerSlotUpload('${cfg.key}')">
                    <img src="${slotPhoto || cfg.sampleImg}" class="vault-pose-clear-img" alt="${escapeHtml(cfg.title)}" draggable="false">
                    <span class="vault-pose-status-pill ${slotPhoto ? 'is-saved' : 'is-sample'}">
                      ${slotPhoto ? '✓ Photo Added' : 'Sample Pose • Tap to Add'}
                    </span>
                  </div>
                `;
              }).join('')}
            </div>
          </div>

          <button type="button" class="vault-pose-nav-arrow next" onclick="stepVaultPoseSlot(1)" aria-label="Next Pose">&#x203A;</button>
        </div>

        <!-- Pose Action Row & Dots -->
        <div class="vault-pose-controls-row">
          <div class="vault-pose-action-btns">
            <button type="button" class="vault-pose-add-btn" id="vaultPosePrimaryUploadBtn">
              <span>📷 ${currentPosePhoto ? 'Change Photo' : 'Add Photo'}</span>
            </button>
            <button type="button" class="vault-pose-remove-btn" id="vaultPoseRemoveBtn" style="display:${currentPosePhoto ? 'inline-flex' : 'none'};" title="Remove this photo">✕</button>
          </div>

          <div class="vault-pose-dots" id="vaultPoseDotsRow">
            ${VAULT_POSE_CONFIGS.map((cfg, idx) => `
              <button type="button"
                      class="vault-pose-dot ${idx === activePoseIdx ? 'active' : ''} ${photos[cfg.key] ? 'filled' : ''}"
                      onclick="goToVaultPoseSlot(${idx})"
                      title="Pose ${cfg.num}: ${escapeHtml(cfg.title)}"></button>
            `).join('')}
          </div>
        </div>

        <div class="vault-analyzing-progress" id="vaultAnalyzingProgress" style="display:none;">
          <span class="vault-spinner"></span>
          <span id="vaultAnalyzingText">Updating character likeness...</span>
        </div>
      </div>

      <!-- Collapsible Member Details (Tucked Away to Keep UI Clean) -->
      <details class="vault-compact-details" id="vaultMemberDetailsAccordion" ${wasDetailsOpen ? 'open' : ''}>
        <summary class="vault-compact-summary">
          <span>✏️ Edit Name, Age &amp; Character Details</span>
          <span class="vault-summary-meta">${escapeHtml(member.name || member.roleLabel)}${member.age ? ` • ${member.age}y` : ''} <span class="vault-summary-chevron">▴</span></span>
        </summary>
        <div class="vault-form-grid" style="margin-top: 10px;">
          <div class="vault-field-group">
            <label>Role</label>
            <select id="vField_relation" onchange="handleActiveMemberFieldChange('relationship', this.value)">
              <option value="self" ${member.relationship === 'self' ? 'selected' : ''}>Father / Self</option>
              <option value="spouse" ${member.relationship === 'spouse' ? 'selected' : ''}>Mother / Spouse</option>
              <option value="elder_son" ${member.relationship === 'elder_son' ? 'selected' : ''}>Elder Son</option>
              <option value="younger_son" ${member.relationship === 'younger_son' ? 'selected' : ''}>Younger Son</option>
              <option value="child" ${member.relationship === 'child' ? 'selected' : ''}>Child / Other</option>
            </select>
          </div>

          <div class="vault-field-group">
            <label>Name</label>
            <input type="text" id="vField_name" value="${escapeHtml(member.name || '')}" placeholder="e.g. Shridhar" oninput="handleActiveMemberFieldChange('name', this.value)">
          </div>

          <div class="vault-field-group">
            <label>Age</label>
            <input type="number" id="vField_age" value="${member.age || ''}" placeholder="e.g. 40" min="1" max="100" oninput="handleActiveMemberFieldChange('age', parseInt(this.value, 10) || null)">
          </div>

          <div class="vault-field-group">
            <label>Stature</label>
            <input type="text" id="vField_height" value="${escapeHtml(member.heightDesc || '')}" placeholder="e.g. 5ft 10in" oninput="handleActiveMemberFieldChange('heightDesc', this.value)">
          </div>

          <!-- Interactive Quantified Body Volume, Tummy & Visual Trait Selector -->
          ${(() => {
            const st = ensureMemberStructuredTraits(member);
            const lms = new Set(st.landmarks || []);
            return `
              <div class="vault-field-group full-width vault-structured-traits-box">
                <div class="vault-structured-header">
                  <span>🎯 Quantified Body Volume, Tummy &amp; Trait Selector</span>
                  <span class="vault-structured-sub">Tap to select &amp; auto-update traits below</span>
                </div>

                <div class="vault-trait-row">
                  <span class="vault-trait-row-label">Body Frame / Volume</span>
                  <div class="vault-trait-chips">
                    <button type="button" class="vault-trait-chip ${st.bodyVolume === 'lean' ? 'active' : ''}" onclick="selectVaultStructuredTrait('bodyVolume', 'lean')">Lean / Slim</button>
                    <button type="button" class="vault-trait-chip ${st.bodyVolume === 'medium' ? 'active' : ''}" onclick="selectVaultStructuredTrait('bodyVolume', 'medium')">Medium Balanced</button>
                    <button type="button" class="vault-trait-chip ${st.bodyVolume === 'broad_full' ? 'active' : ''}" onclick="selectVaultStructuredTrait('bodyVolume', 'broad_full')">Broad / Full-Bodied</button>
                    <button type="button" class="vault-trait-chip ${st.bodyVolume === 'heavy_plus' ? 'active' : ''}" onclick="selectVaultStructuredTrait('bodyVolume', 'heavy_plus')">Heavy / Plus</button>
                  </div>
                </div>

                <div class="vault-trait-row">
                  <span class="vault-trait-row-label">Midsection / Waist Profile (6-Step Granular Scale)</span>
                  <div class="vault-trait-chips">
                    <button type="button" class="vault-trait-chip ${st.tummyProfile === 'flat' ? 'active' : ''}" onclick="selectVaultStructuredTrait('tummyProfile', 'flat')">0% • Flat / Toned</button>
                    <button type="button" class="vault-trait-chip ${st.tummyProfile === 'straight_5' ? 'active' : ''}" onclick="selectVaultStructuredTrait('tummyProfile', 'straight_5')">5% • Straight-Cut (No Bulge)</button>
                    <button type="button" class="vault-trait-chip ${st.tummyProfile === 'subtle_10' ? 'active' : ''}" onclick="selectVaultStructuredTrait('tummyProfile', 'subtle_10')">10% • Subtle Softness (Flush w/ Chest)</button>
                    <button type="button" class="vault-trait-chip ${st.tummyProfile === 'slight_tummy' ? 'active' : ''}" onclick="selectVaultStructuredTrait('tummyProfile', 'slight_tummy')">15% • Mild Relaxed Waist</button>
                    <button type="button" class="vault-trait-chip ${st.tummyProfile === 'visible_tummy' ? 'active' : ''}" onclick="selectVaultStructuredTrait('tummyProfile', 'visible_tummy')">25% • Rounded Tummy</button>
                    <button type="button" class="vault-trait-chip ${st.tummyProfile === 'prominent_belly' ? 'active' : ''}" onclick="selectVaultStructuredTrait('tummyProfile', 'prominent_belly')">35%+ • Prominent Belly</button>
                  </div>
                </div>

                <div class="vault-trait-row">
                  <span class="vault-trait-row-label">Actual Standing Height (Auto-Calculates Pairwise % Against Every Member)</span>
                  ${(() => {
                    const currentCm = resolveMemberHeightCm(member);
                    const hInfo = cmToFeetInches(currentCm);
                    const pairwiseRows = computePairwiseStatureMatrixForMember(member, members);
                    const ftOptions = [3, 4, 5, 6].map(ft => `<option value="${ft}" ${hInfo.feet === ft ? 'selected' : ''}>${ft} ft</option>`).join('');
                    const inOptions = Array.from({ length: 12 }, (_, i) => `<option value="${i}" ${hInfo.inches === i ? 'selected' : ''}>${i} in</option>`).join('');
                    return `
                      <div class="vault-height-inputs-bar">
                        <div class="vault-height-unit-box" title="Height in Feet & Inches">
                          <select id="vField_heightFt" onchange="handleVaultMemberFeetInchesChange()">${ftOptions}</select>
                          <select id="vField_heightIn" onchange="handleVaultMemberFeetInchesChange()">${inOptions}</select>
                        </div>
                        <div class="vault-height-unit-box" title="Height in Centimeters (cm)">
                          <input type="number" id="vField_heightCm" value="${hInfo.cm}" min="75" max="220" onchange="handleVaultMemberHeightCmChange(this.value)">
                          <span class="vault-height-unit-label">cm</span>
                        </div>
                        <div class="vault-trait-chips" style="margin-left:2px;">
                          <button type="button" class="vault-trait-chip ${Math.abs(currentCm - 178) <= 1 ? 'active' : ''}" onclick="handleVaultMemberHeightCmChange(178)">5'10" (178cm • Dad)</button>
                          <button type="button" class="vault-trait-chip ${Math.abs(currentCm - 162) <= 1 ? 'active' : ''}" onclick="handleVaultMemberHeightCmChange(162)">5'4" (162cm • Mom)</button>
                          <button type="button" class="vault-trait-chip ${Math.abs(currentCm - 142) <= 1 ? 'active' : ''}" onclick="handleVaultMemberHeightCmChange(142)">4'8" (142cm • Elder 11y)</button>
                          <button type="button" class="vault-trait-chip ${Math.abs(currentCm - 127) <= 1 ? 'active' : ''}" onclick="handleVaultMemberHeightCmChange(127)">4'2" (127cm • Younger 7y)</button>
                        </div>
                      </div>
                      ${pairwiseRows.length > 0 ? `
                        <div class="vault-pairwise-stature-matrix">
                          <span class="vault-pairwise-matrix-title">📐 Auto-Calculated Pairwise Relative Stature (${escapeHtml(hInfo.shortLabel)} — Works Even When Tallest Member Is Not in Scene)</span>
                          <div class="vault-pairwise-pills">
                            ${pairwiseRows.map(r => `
                              <div class="vault-pairwise-pill">• vs. <strong>${escapeHtml(r.otherName)} (${escapeHtml(r.otherShortHeight)})</strong>: ${escapeHtml(r.summary)}</div>
                            `).join('')}
                          </div>
                        </div>
                      ` : ''}
                    `;
                  })()}
                </div>

                <div class="vault-trait-row">
                  <span class="vault-trait-row-label">Face &amp; Cheek Volume</span>
                  <div class="vault-trait-chips">
                    <button type="button" class="vault-trait-chip ${st.faceFullness === 'slim_angular' ? 'active' : ''}" onclick="selectVaultStructuredTrait('faceFullness', 'slim_angular')">Slim / Angular</button>
                    <button type="button" class="vault-trait-chip ${st.faceFullness === 'oval_balanced' ? 'active' : ''}" onclick="selectVaultStructuredTrait('faceFullness', 'oval_balanced')">Balanced Oval</button>
                    <button type="button" class="vault-trait-chip ${st.faceFullness === 'soft_full_cheeks' ? 'active' : ''}" onclick="selectVaultStructuredTrait('faceFullness', 'soft_full_cheeks')">Soft Fuller Cheeks</button>
                    <button type="button" class="vault-trait-chip ${st.faceFullness === 'round_full_submental' ? 'active' : ''}" onclick="selectVaultStructuredTrait('round_full_submental' === st.faceFullness ? 'faceFullness' : 'faceFullness', 'round_full_submental')">Full Round &amp; Under-Chin</button>
                  </div>
                </div>

                <div class="vault-trait-row">
                  <span class="vault-trait-row-label">Facial Hair &amp; Landmarks (Tap to Toggle)</span>
                  <div class="vault-trait-chips">
                    <button type="button" class="vault-trait-chip ${st.facialHair === 'light_stubble' ? 'active' : ''}" onclick="selectVaultStructuredTrait('facialHair', 'light_stubble')">Light Stubble</button>
                    <button type="button" class="vault-trait-chip ${st.facialHair === 'trimmed_beard' ? 'active' : ''}" onclick="selectVaultStructuredTrait('facialHair', 'trimmed_beard')">Trimmed Beard</button>
                    <button type="button" class="vault-trait-chip ${st.facialHair === 'none' ? 'active' : ''}" onclick="selectVaultStructuredTrait('facialHair', 'none')">Clean-Shaven</button>
                    <button type="button" class="vault-trait-chip ${lms.has('round_glasses') ? 'active' : ''}" onclick="toggleVaultStructuredLandmark('round_glasses')">Round Glasses</button>
                    <button type="button" class="vault-trait-chip ${lms.has('rect_glasses') ? 'active' : ''}" onclick="toggleVaultStructuredLandmark('rect_glasses')">Rect Glasses</button>
                    <button type="button" class="vault-trait-chip ${lms.has('forehead_bindi') ? 'active' : ''}" onclick="toggleVaultStructuredLandmark('forehead_bindi')">Forehead Bindi</button>
                    <button type="button" class="vault-trait-chip ${lms.has('hairline_kumkum') ? 'active' : ''}" onclick="toggleVaultStructuredLandmark('hairline_kumkum')">Hairline Kumkum</button>
                    <button type="button" class="vault-trait-chip ${lms.has('stud_earrings') ? 'active' : ''}" onclick="toggleVaultStructuredLandmark('stud_earrings')">Stud Earrings</button>
                  </div>
                </div>
              </div>
            `;
          })()}

          <div class="vault-field-group full-width">
            <div class="vault-label-with-hint" style="flex-direction:row; align-items:center; justify-content:space-between; gap:6px; width:100%;">
              <div style="display:flex; align-items:center; gap:6px;">
                <label>Identity Anchors</label>
                <button type="button" class="ui-info-dot-btn" onclick="toggleInfoTip(event, 'vaultAnchorsInfoTip')" title="About Identity Anchors">i</button>
              </div>
              <button type="button" id="vaultReanalyzeBtn" onclick="analyzeActiveMemberAllPhotos()" style="background:rgba(212,175,55,0.14); border:1px solid rgba(212,175,55,0.4); color:#F3D27A; border-radius:999px; padding:3px 10px; font-size:11px; font-weight:600; cursor:pointer;">✨ Re-Extract from Photo</button>
            </div>
            <div class="ui-info-popover-box" id="vaultAnchorsInfoTip" style="display:none; margin-bottom:6px;">
              Core facial geometry, forehead landmarks (bindi/kumkum), hair length &amp; parting, and body build auto-extracted from your uploaded photos and kept consistent across every scene.
            </div>
            <textarea id="vField_anchors" rows="2" placeholder="Auto-extracted from your uploaded photo(s): face shape, hair length, landmarks, build" oninput="handleActiveMemberFieldChange('uncompromisableAnchors', this.value)">${escapeHtml(member.uncompromisableAnchors || '')}</textarea>
          </div>

          <div class="vault-field-group full-width">
            <label>Visual Traits</label>
            <textarea id="vField_traits" rows="2" placeholder="Auto-extracted from your photos" oninput="handleActiveMemberFieldChange('visualTraits', this.value)">${escapeHtml(member.visualTraits || '')}</textarea>
          </div>

          <div class="vault-field-group full-width">
            <label>Nicknames (Comma separated)</label>
            <input type="text" id="vField_aliases" value="${escapeHtml(Array.isArray(member.aliases) ? member.aliases.join(', ') : '')}" placeholder="e.g. dad, shridhar, me" oninput="handleActiveMemberAliasesChange(this.value)">
          </div>
        </div>
      </details>
    </div>
  `;

  const uploadBtn = document.getElementById('vaultPosePrimaryUploadBtn');
  if (uploadBtn) {
    uploadBtn.onclick = () => triggerSlotUpload(VAULT_POSE_CONFIGS[activeVaultPoseSlotIdx].key);
  }
  const removeBtn = document.getElementById('vaultPoseRemoveBtn');
  if (removeBtn) {
    removeBtn.onclick = () => removeSlotPhoto(VAULT_POSE_CONFIGS[activeVaultPoseSlotIdx].key);
  }

  // Whenever the user clicks "Edit Name, Age & Character Details", automatically slide the lower edit section up into full view
  const detailsEl = document.getElementById('vaultMemberDetailsAccordion');
  if (detailsEl) {
    detailsEl.addEventListener('toggle', () => {
      if (detailsEl.open) {
        slideUpVaultMemberDetailsSection();
      } else {
        container.scrollTo({ top: 0, behavior: 'smooth' });
      }
    });
  }

  // Bind steady horizontal swipe (touch & pointer) on the viewport frame without moving the photo element
  const viewportFrame = document.getElementById('vaultPoseViewportFrame');
  if (viewportFrame) {
    let startX = 0;
    let startY = 0;
    let isPointerDown = false;
    let didSwipe = false;

    viewportFrame.addEventListener('touchstart', (e) => {
      if (e.touches && e.touches[0]) {
        startX = e.touches[0].clientX;
        startY = e.touches[0].clientY;
        didSwipe = false;
      }
    }, { passive: true });

    viewportFrame.addEventListener('touchend', (e) => {
      if (e.changedTouches && e.changedTouches[0]) {
        const dx = e.changedTouches[0].clientX - startX;
        const dy = e.changedTouches[0].clientY - startY;
        if (Math.abs(dx) > 28 && Math.abs(dx) > Math.abs(dy)) {
          didSwipe = true;
          stepVaultPoseSlot(dx < 0 ? 1 : -1);
        }
      }
    }, { passive: true });

    viewportFrame.addEventListener('mousedown', (e) => {
      isPointerDown = true;
      didSwipe = false;
      startX = e.clientX;
      startY = e.clientY;
    });

    viewportFrame.addEventListener('mouseup', (e) => {
      if (!isPointerDown) return;
      isPointerDown = false;
      const dx = e.clientX - startX;
      const dy = e.clientY - startY;
      if (Math.abs(dx) > 28 && Math.abs(dx) > Math.abs(dy)) {
        didSwipe = true;
        stepVaultPoseSlot(dx < 0 ? 1 : -1);
      }
    });

    // Prevent click-to-upload from firing right after a horizontal swipe
    viewportFrame.addEventListener('click', (e) => {
      if (didSwipe) {
        e.stopPropagation();
        e.preventDefault();
        didSwipe = false;
      }
    }, true);
  }
}

function triggerSlotUpload(slotType) {
  const input = document.getElementById('slotFile_' + slotType);
  if (input) input.click();
}

function handleSlotPhotoSelect(slotType, event) {
  const file = event.target.files && event.target.files[0];
  if (!file) return;

  compressImage(file, 640, 0.85, function(base64Data, mimeType) {
    const cast = familyCastProfileCache || getDefaultClientFamilyCast();
    const member = (cast.members || []).find(m => m.id === activeVaultMemberId);
    if (!member) return;

    member.photos = member.photos || {};
    member.photos[slotType] = base64Data;

    // Set primary avatar if frontal or if no primary avatar exists yet
    if (slotType === 'frontal' || !member.photoBase64) {
      member.photoBase64 = base64Data;
    }

    // Automatically advance to the next pose slot so user can smoothly add the next pose
    if (activeVaultPoseSlotIdx < 2) {
      activeVaultPoseSlotIdx += 1;
    }

    saveFamilyCastProfile(cast);
    renderVaultMemberTabs();
    renderActiveMemberScreen();
    renderFamilyCastStagingUI();

    // Automatically cross-reference and extract traits with AI vision
    analyzeActiveMemberAllPhotos();
  });
}

function removeSlotPhoto(slotType) {
  const cast = familyCastProfileCache || getDefaultClientFamilyCast();
  const member = (cast.members || []).find(m => m.id === activeVaultMemberId);
  if (!member) return;

  member.photos = member.photos || {};
  delete member.photos[slotType];

  const remainingPhotos = Object.values(member.photos).filter(Boolean);
  if (member.photoBase64 && !remainingPhotos.includes(member.photoBase64)) {
    member.photoBase64 = remainingPhotos[0] || null;
  }

  saveFamilyCastProfile(cast);
  renderVaultMemberTabs();
  renderActiveMemberScreen();
  renderFamilyCastStagingUI();
  showTemporaryToast('Photo removed from slot.');
}

async function analyzeActiveMemberAllPhotos() {
  const cast = familyCastProfileCache || getDefaultClientFamilyCast();
  const member = (cast.members || []).find(m => m.id === activeVaultMemberId);
  if (!member || isAnalyzingVaultPhotos) return;

  const photos = member.photos || {};
  const photoList = [];
  if (photos.frontal) photoList.push({ slot: 'frontal', imageBase64: photos.frontal, imageMimeType: 'image/jpeg' });
  if (photos.profile) photoList.push({ slot: 'profile', imageBase64: photos.profile, imageMimeType: 'image/jpeg' });
  if (photos.stature) photoList.push({ slot: 'stature', imageBase64: photos.stature, imageMimeType: 'image/jpeg' });

  if (photoList.length === 0) {
    showTemporaryToast('Please tap a photo slot above to attach a photo first.');
    return;
  }

  isAnalyzingVaultPhotos = true;
  const bar = document.getElementById('vaultAnalyzingProgress');
  const reanalyzeBtn = document.getElementById('vaultReanalyzeBtn');
  if (bar) bar.style.display = 'flex';
  if (reanalyzeBtn) reanalyzeBtn.disabled = true;

  try {
    let data = null;

    // 1. Try primary endpoint /api/cast-traits
    try {
      const resp = await fetch('/api/cast-traits', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          photos: photoList,
          relation: member.relationship,
          approxAge: member.age,
          name: member.name
        })
      });
      if (resp.ok) {
        data = await resp.json();
      }
    } catch (_) {}

    // 2. Fallback to /api/synthesize
    if (!data || !data.success) {
      try {
        const resp2 = await fetch('/api/synthesize', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            action: 'extract_cast_traits',
            photos: photoList,
            relation: member.relationship,
            approxAge: member.age,
            name: member.name
          })
        });
        if (resp2.ok) {
          data = await resp2.json();
        }
      } catch (_) {}
    }

    if (data && data.success && data.visualTraits) {
      member.visualTraits = data.visualTraits;
      if (data.detectedAge && !member.age) member.age = data.detectedAge;
      if (data.bodyBuild) member.bodyBuild = data.bodyBuild;
      if (data.statureDesc && (!member.heightDesc || member.heightDesc.includes('Standard') || !member.heightDesc.trim())) {
        member.heightDesc = data.statureDesc;
      }
      if (data.uncompromisableAnchors) {
        member.uncompromisableAnchors = data.uncompromisableAnchors;
      }
      if (data.structuredTraits && typeof data.structuredTraits === 'object') {
        member.structuredTraits = Object.assign(ensureMemberStructuredTraits(member), data.structuredTraits);
      }

      saveFamilyCastProfile(cast);
      renderActiveMemberScreen();
      renderFamilyCastStagingUI();
      showTemporaryToast(`✓ Extracted Visual Traits & Identity Anchors from ${photoList.length} photo(s)!`);
    } else {
      showTemporaryToast('Photos attached. You can describe any additional visual features below.');
    }
  } catch (err) {
    console.warn('Multi-photo analysis notice:', err);
  } finally {
    isAnalyzingVaultPhotos = false;
    if (bar) bar.style.display = 'none';
    if (reanalyzeBtn) reanalyzeBtn.disabled = false;
  }
}

let isGeneratingAvatar = false;

async function generateActiveMemberStylizedAvatar() {
  if (isGeneratingAvatar) return;
  const cast = familyCastProfileCache || getDefaultClientFamilyCast();
  const member = (cast.members || []).find(m => m.id === activeVaultMemberId);
  if (!member) return;

  const photo = member.photos?.frontal || member.photos?.profile || member.photos?.stature || member.photoBase64;
  if (!photo) {
    showTemporaryToast('Please attach at least one reference photo first.');
    return;
  }

  isGeneratingAvatar = true;
  const prog = document.getElementById('vaultAvatarProgress');
  const btn = document.getElementById('btnRegenAvatar') || document.getElementById('btnCreateAvatar');
  if (prog) prog.style.display = 'flex';
  if (btn) btn.disabled = true;

  try {
    const userEmail = getResolvedCreatorEmail();
    const resp = await fetch('/api/synthesize', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'generate_stylized_avatar',
        memberId: member.id,
        imageBase64: photo,
        relation: member.relationship,
        name: member.name,
        approxAge: member.age,
        visualTraits: member.visualTraits,
        uncompromisableAnchors: member.uncompromisableAnchors,
        creatorEmail: userEmail
      })
    });

    if (resp.ok) {
      const data = await resp.json();
      if (data && data.success && data.avatarUrl) {
        member.stylizedAvatarUrl = data.avatarUrl;
        saveFamilyCastProfile(cast);
        renderActiveMemberScreen();
        renderVaultMemberTabs();
        showTemporaryToast(`✓ Generated Stylized Editorial Model for ${escapeHtml(member.name || member.roleLabel)}!`);
      } else {
        showTemporaryToast(data?.error || 'Failed to generate stylized avatar.');
      }
    } else {
      showTemporaryToast('Avatar generation service temporarily busy.');
    }
  } catch (err) {
    console.warn('Avatar generation error:', err);
    showTemporaryToast('Failed to connect to avatar generation service.');
  } finally {
    isGeneratingAvatar = false;
    if (prog) prog.style.display = 'none';
    if (btn) btn.disabled = false;
  }
}

function syncStructuredTraitsIntoTextFields(member, allMembersOverride = null) {
  if (!member) return;
  const st = ensureMemberStructuredTraits(member);
  const allMembers = Array.isArray(allMembersOverride)
    ? allMembersOverride
    : ((familyCastProfileCache && familyCastProfileCache.members) || []);
  const fatherObj = allMembers.find(m => m && (m.id === 'member_father' || m.relationship === 'self'));
  const fatherCm = fatherObj ? resolveMemberHeightCm(fatherObj) : 178;
  const memberCm = resolveMemberHeightCm(member);
  member.heightCm = memberCm;
  st.heightCm = memberCm;
  st.baseHeightRatio = Number((memberCm / Math.max(1, fatherCm)).toFixed(2));
  const hInfo = cmToFeetInches(memberCm);
  const pairwiseRows = computePairwiseStatureMatrixForMember(member, allMembers);

  const volumePhraseMap = {
    lean: 'lean slim frame',
    medium: 'balanced medium frame',
    broad_full: 'fuller medium-heavy build with broad shoulders',
    heavy_plus: 'heavy full-bodied plus frame'
  };
  const tummyPhraseMap = {
    flat: 'flat toned waist (0% belly projection, waist narrower than chest)',
    straight_5: 'straight-cut torso (5% waist profile where the shirt hangs straight down flush with the ribcage, zero belly bulge, strictly NOT a skinny V-taper and strictly NO protruding belly)',
    subtle_10: 'straight-cut everyday waist with subtle 10% lower-waist softness that stays completely flush with the chest line under a straight-draping shirt (strictly neither a skinny V-taper gym waist nor a protruding pot-belly or round paunch)',
    slight_tummy: 'mild 15% relaxed waist contour under a loosely draped shirt that never sticks out past the chest line (strictly NOT a skinny V-taper gym body and strictly NO large protruding pot-belly)',
    visible_tummy: 'noticeable 25% rounded tummy contour under shirt (strictly NOT lean or flat-stomached)',
    prominent_belly: 'prominent full rounded belly (~35%+ round stomach silhouette)'
  };
  const tummyShortLabelMap = {
    flat: 'flat waist (0%)',
    straight_5: 'straight-cut waist (5% • no bulge)',
    subtle_10: 'subtle waist softness (10% • flush w/ chest)',
    slight_tummy: 'mild relaxed waist (15%)',
    visible_tummy: 'rounded tummy (25%)',
    prominent_belly: 'prominent round belly (35%+)'
  };
  const facePhraseMap = {
    slim_angular: 'slim angular face',
    oval_balanced: 'balanced oval face',
    soft_full_cheeks: 'soft fuller round-oval face with warm full cheeks',
    round_full_submental: 'soft fuller round-oval face with full cheeks and natural under-chin/submental fullness'
  };
  const facialHairMap = {
    none: 'clean-shaven face',
    light_stubble: 'short light neat trimmed stubble beard',
    trimmed_beard: 'neat trimmed dark beard',
    full_beard: 'full dark beard'
  };
  const landmarkLabels = {
    round_glasses: 'thin-rimmed round eyeglasses',
    rect_glasses: 'rectangular eyeglasses',
    forehead_bindi: 'small black circular forehead bindi',
    hairline_kumkum: 'subtle red kumkum at upper forehead hairline',
    stud_earrings: 'small gold stud earrings'
  };

  const volPhrase = volumePhraseMap[st.bodyVolume] || volumePhraseMap.medium;
  const tummyPhrase = tummyPhraseMap[st.tummyProfile] || tummyPhraseMap.subtle_10;
  const tummyShort = tummyShortLabelMap[st.tummyProfile] || tummyShortLabelMap.subtle_10;
  const facePhrase = facePhraseMap[st.faceFullness] || facePhraseMap.oval_balanced;
  const beardPhrase = (member.relationship === 'self') ? (facialHairMap[st.facialHair] || facialHairMap.light_stubble) : '';
  const activeLms = (st.landmarks || []).map(k => landmarkLabels[k]).filter(Boolean);

  const pairwiseShort = pairwiseRows.slice(0, 2).map(r => `${r.pctVsOther}% of ${r.otherName} (${r.diffCm < 0 ? `-${r.diffIn}in` : `+${r.diffIn}in`})`).join(' • ');
  const pairwiseFull = pairwiseRows.map(r => r.summary).join('; ');
  const ratioStr = `${hInfo.label}${pairwiseShort ? ` [${pairwiseShort}]` : ` (${st.baseHeightRatio}x Father height)`}`;

  member.heightDesc = `${ratioStr}, ${volPhrase} with ${tummyShort}`;

  const quantifiedSummary = `Quantified Volume & Stature: ${facePhrase}${beardPhrase ? ', ' + beardPhrase : ''}${activeLms.length ? ', ' + activeLms.join(', ') : ''}, ${volPhrase} with ${tummyPhrase}, actual height ${hInfo.label}${pairwiseFull ? ` (${pairwiseFull})` : ''}.`;

  const cleanExisting = (str) => String(str || '')
    .replace(/\s*Quantified Volume & Stature:[\s\S]*$/i, '')
    .replace(/\bsturdy,?\s*broad-shouldered solid(?: adult)? (?:frame|build)\b/gi, `${volPhrase} with ${tummyPhrase}`)
    .replace(/\band\s+a\s+fuller\s+medium-heavy\s+adult\s+build\s+with\s+broad\s+shoulders\s+and\s+a\s+visible\s+rounded\s+dad-bod\s+tummy[^.]*/gi, `and a ${volPhrase} with ${tummyPhrase}`)
    .replace(/\band\s+a\s+fuller\s+medium-heavy\s+adult\s+build\s+with\s+a\s+visible\s+rounded\s+dad-bod\s+tummy[^.]*/gi, `and a ${volPhrase} with ${tummyPhrase}`)
    .trim();

  const baseAnchors = cleanExisting(member.uncompromisableAnchors);
  const baseTraits = cleanExisting(member.visualTraits);

  member.uncompromisableAnchors = (baseAnchors ? `${baseAnchors.replace(/\.$/, '')}. ` : '') + quantifiedSummary;
  member.visualTraits = (baseTraits ? `${baseTraits.replace(/\.$/, '')}. ` : '') + quantifiedSummary;
}

function handleVaultMemberHeightCmChange(rawCm) {
  const cast = familyCastProfileCache || getDefaultClientFamilyCast();
  const member = (cast.members || []).find(m => m.id === activeVaultMemberId);
  if (!member) return;
  const safeCm = Math.max(75, Math.min(220, Math.round(Number(rawCm) || resolveMemberHeightCm(member))));
  const st = ensureMemberStructuredTraits(member);
  member.heightCm = safeCm;
  st.heightCm = safeCm;
  // Re-sync all members so pairwise percentages against this member update across the whole family
  (cast.members || []).forEach(m => syncStructuredTraitsIntoTextFields(m, cast.members));
  saveFamilyCastProfile(cast);
  renderActiveMemberScreen();
  renderFamilyCastStagingUI();
}

function handleVaultMemberFeetInchesChange() {
  const ftEl = document.getElementById('vField_heightFt');
  const inEl = document.getElementById('vField_heightIn');
  if (!ftEl || !inEl) return;
  const newCm = feetInchesToCm(ftEl.value, inEl.value);
  handleVaultMemberHeightCmChange(newCm);
}

function selectVaultStructuredTrait(category, value) {
  const cast = familyCastProfileCache || getDefaultClientFamilyCast();
  const member = (cast.members || []).find(m => m.id === activeVaultMemberId);
  if (!member) return;

  const st = ensureMemberStructuredTraits(member);
  st[category] = value;
  syncStructuredTraitsIntoTextFields(member, cast.members);
  saveFamilyCastProfile(cast);
  renderActiveMemberScreen();
  renderFamilyCastStagingUI();
}

function toggleVaultStructuredLandmark(tag) {
  const cast = familyCastProfileCache || getDefaultClientFamilyCast();
  const member = (cast.members || []).find(m => m.id === activeVaultMemberId);
  if (!member) return;

  const st = ensureMemberStructuredTraits(member);
  const set = new Set(st.landmarks || []);
  if (set.has(tag)) {
    set.delete(tag);
  } else {
    if (tag === 'round_glasses') set.delete('rect_glasses');
    if (tag === 'rect_glasses') set.delete('round_glasses');
    set.add(tag);
  }
  st.landmarks = Array.from(set);
  syncStructuredTraitsIntoTextFields(member);
  saveFamilyCastProfile(cast);
  renderActiveMemberScreen();
  renderFamilyCastStagingUI();
}

function handleActiveMemberFieldChange(field, val) {
  const cast = familyCastProfileCache || getDefaultClientFamilyCast();
  const member = (cast.members || []).find(m => m.id === activeVaultMemberId);
  if (!member) return;

  member[field] = val;
  if (field === 'relationship' && !member.name) {
    member.roleLabel = val;
  }
  saveFamilyCastProfile(cast);
  renderVaultMemberTabs();
  renderFamilyCastStagingUI();
}

function handleActiveMemberAliasesChange(raw) {
  const cast = familyCastProfileCache || getDefaultClientFamilyCast();
  const member = (cast.members || []).find(m => m.id === activeVaultMemberId);
  if (!member) return;

  const aliases = raw.split(',').map(a => a.trim().toLowerCase()).filter(Boolean);
  member.aliases = aliases;
  saveFamilyCastProfile(cast);
}

function saveActiveMemberAndNext() {
  const cast = familyCastProfileCache || getDefaultClientFamilyCast();
  const members = cast.members || [];
  const currentIdx = members.findIndex(m => m.id === activeVaultMemberId);

  // Read current form inputs
  if (currentIdx !== -1) {
    const member = members[currentIdx];
    const rel = document.getElementById('vField_relation')?.value;
    const name = document.getElementById('vField_name')?.value?.trim();
    const age = parseInt(document.getElementById('vField_age')?.value, 10) || null;
    const height = document.getElementById('vField_height')?.value?.trim();
    const anchors = document.getElementById('vField_anchors')?.value?.trim();
    const traits = document.getElementById('vField_traits')?.value?.trim();
    const aliasesRaw = document.getElementById('vField_aliases')?.value?.trim();

    if (rel) member.relationship = rel;
    if (name !== undefined) {
      member.name = name;
      member.roleLabel = name || rel;
    }
    member.age = age;
    if (height !== undefined) member.heightDesc = height;
    if (anchors !== undefined) member.uncompromisableAnchors = anchors;
    if (traits !== undefined) member.visualTraits = traits;
    if (aliasesRaw) {
      member.aliases = aliasesRaw.split(',').map(a => a.trim().toLowerCase()).filter(Boolean);
    }

    saveFamilyCastProfile(cast);
    showTemporaryToast(`✓ Saved ${escapeHtml(member.name || member.roleLabel)}!`);
  }

  // If next member exists, switch to next member
  if (currentIdx !== -1 && currentIdx < members.length - 1) {
    const nextMember = members[currentIdx + 1];
    activeVaultMemberId = nextMember.id;
    const prevDetails = document.getElementById('vaultMemberDetailsAccordion');
    if (prevDetails) prevDetails.open = false;
    renderVaultMemberTabs();
    renderActiveMemberScreen();
    const body = document.getElementById('vaultActiveMemberScreen');
    if (body) body.scrollTop = 0;
  } else {
    // Last member reached
    showTemporaryToast('✓ All family members saved in vault!');
    closeFamilyCastModal();
  }
}

function deleteActiveMember(memberId) {
  const cast = familyCastProfileCache || getDefaultClientFamilyCast();
  if (!Array.isArray(cast.members)) return;

  cast.members = cast.members.filter(m => m.id !== memberId);
  activeCastMemberIds.delete(memberId);
  saveFamilyCastProfile(cast);

  if (cast.members.length > 0) {
    activeVaultMemberId = cast.members[0].id;
  } else {
    activeVaultMemberId = null;
  }

  renderVaultMemberTabs();
  renderActiveMemberScreen();
  renderFamilyCastStagingUI();
  showTemporaryToast('Member removed from vault.');
}

