let editModalOriginalSnapshot = null;
let editModalLastReviewedSignature = null;
let lastEditModalPolishedResults = [];
let lastEditModalCorrections = [];
let currentEditPolishFilter = 'all';
let editPolishDisplayMode = 'highlighted';

function captureEditModalSnapshot() {
  const catInput = document.getElementById('editModalCategory');
  const pubInput = document.getElementById('editModalPublication');
  const headInput = document.getElementById('editModalHeadline');
  const excerptInput = document.getElementById('editModalNewsExcerpt');
  const handleInput = document.getElementById('editModalHandle');
  const s2TitleInput = document.getElementById('editModalS2Title');
  const opinionInput = document.getElementById('editModalOpinion');
  const whyInput = document.getElementById('editModalWhyItMatters');
  const metricInput = document.getElementById('editModalMetric');
  const s3Head = document.getElementById('editModalS3Headline');
  const s3Quote = document.getElementById('editModalS3Quote');
  const s3Obs = document.getElementById('editModalS3Observation');
  const s3Ref = document.getElementById('editModalS3Reflection');

  editModalOriginalSnapshot = {
    category: catInput ? catInput.value : '',
    publication: pubInput ? pubInput.value : '',
    headline: headInput ? headInput.value : '',
    excerpt: excerptInput ? excerptInput.value : '',
    handle: handleInput ? handleInput.value : '',
    s2Title: s2TitleInput ? s2TitleInput.value : '',
    opinion: opinionInput ? opinionInput.value : '',
    whyItMatters: whyInput ? whyInput.value : '',
    metric: metricInput ? metricInput.value : '',
    s3Headline: s3Head ? s3Head.value : '',
    s3Quote: s3Quote ? s3Quote.value : '',
    s3Observation: s3Obs ? s3Obs.value : '',
    s3Reflection: s3Ref ? s3Ref.value : ''
  };
  editModalLastReviewedSignature = null;
  lastEditModalPolishedResults = [];
  lastEditModalCorrections = [];
}

function getEditedProseFields(filterTab = null) {
  if (!editModalOriginalSnapshot) return [];

  const fieldDefs = [
    { tab: 0, id: 'editModalHeadline', label: 'Slide 1: Hook Headline', snapshotKey: 'headline', minLen: 3 },
    { tab: 0, id: 'editModalNewsExcerpt', label: 'Slide 1: Source Headline / Spark', snapshotKey: 'excerpt', minLen: 3 },
    { tab: 1, id: 'editModalS2Title', label: 'Slide 2: Stance Title', snapshotKey: 's2Title', minLen: 3 },
    { tab: 1, id: 'editModalOpinion', label: 'Slide 2: Curator Take', snapshotKey: 'opinion', minLen: 5 },
    { tab: 1, id: 'editModalWhyItMatters', label: 'Slide 2: Why It Matters', snapshotKey: 'whyItMatters', minLen: 5 },
    { tab: 2, id: 'editModalS3Headline', label: 'Slide 3: Broadsheet Headline', snapshotKey: 's3Headline', minLen: 3 },
    { tab: 2, id: 'editModalS3Quote', label: 'Slide 3: Highlight Quote', snapshotKey: 's3Quote', minLen: 5 },
    { tab: 2, id: 'editModalS3Observation', label: 'Slide 3: Broadsheet Essay', snapshotKey: 's3Observation', minLen: 10 },
    { tab: 2, id: 'editModalS3Reflection', label: 'Slide 3: Reflection', snapshotKey: 's3Reflection', minLen: 5 }
  ];

  const changed = [];
  for (const def of fieldDefs) {
    if (filterTab !== null && def.tab !== filterTab) continue;
    const el = document.getElementById(def.id);
    if (!el) continue;
    const curVal = el.value.trim();
    const origVal = (editModalOriginalSnapshot[def.snapshotKey] || '').trim();
    if (curVal !== origVal && curVal.length >= def.minLen) {
      changed.push({
        ...def,
        element: el,
        oldVal: origVal,
        newVal: curVal
      });
    }
  }
  return changed;
}

function openEditPosterModal(initialTab = null) {
  if (!currentSynthesizedPost) return;

  const isChronicle = isChronicleModePost(currentSynthesizedPost);
  const isChronicleCardsOnly = isChronicle && isChronicleWithoutWatercolorPoster(currentSynthesizedPost);
  const editTab0 = document.getElementById('editTab0');
  const editTab1 = document.getElementById('editTab1');
  const editTab2 = document.getElementById('editTab2');
  if (editTab0) {
    editTab0.textContent = isChronicleCardsOnly ? 'Title & Header' : (isChronicle ? 'Poster 1: Cover' : 'Slide 1: Hook');
  }
  if (editTab1) {
    editTab1.textContent = isChronicleCardsOnly ? 'Card 2: Reflection' : (isChronicle ? 'Poster 3: Reflection' : 'Slide 2: Take');
  }
  if (editTab2) {
    editTab2.textContent = isChronicleCardsOnly ? 'Card 1: Moments ✏️' : (isChronicle ? 'Poster 2: Moments ✏️' : 'Slide 3: Broadsheet & Essay ✏️');
  }

  let tabToOpen = 0;
  if (typeof initialTab === 'number') {
    tabToOpen = initialTab;
  } else {
    const curSlide = currentPreviewSlide || 0;
    if (isChronicleCardsOnly) {
      tabToOpen = (curSlide === 0) ? 2 : 1;
    } else if (curSlide === 0) {
      tabToOpen = 0;
    } else if (curSlide === 1) {
      // Poster 2 in both Daily Chronicle (Moments) and Regular Slant (The Essay) lives in editTabPane2
      tabToOpen = 2;
    } else if (curSlide === 2) {
      // Poster 3 in Daily Chronicle (Reflection) lives in editTabPane1
      tabToOpen = isChronicle ? 1 : 2;
    }
  }
  switchEditModalTab(tabToOpen);

  const catInput = document.getElementById('editModalCategory');
  const pubInput = document.getElementById('editModalPublication');
  const headInput = document.getElementById('editModalHeadline');
  const excerptInput = document.getElementById('editModalNewsExcerpt');
  const handleInput = document.getElementById('editModalHandle');
  const s2TitleInput = document.getElementById('editModalS2Title');
  const opinionInput = document.getElementById('editModalOpinion');
  const whyInput = document.getElementById('editModalWhyItMatters');
  const metricInput = document.getElementById('editModalMetric');
  const s3Head = document.getElementById('editModalS3Headline');
  const s3Quote = document.getElementById('editModalS3Quote');
  const s3Obs = document.getElementById('editModalS3Observation');
  const s3Ref = document.getElementById('editModalS3Reflection');

  if (catInput) catInput.value = currentSynthesizedPost.categoryBadge || 'OPINION';
  if (pubInput) pubInput.value = currentSynthesizedPost.publicationName || currentSynthesizedPost.sourcePublication || currentSynthesizedPost.sourceDomain || '';
  if (headInput) headInput.value = currentSynthesizedPost.adaptedHeadline || '';
  if (excerptInput) excerptInput.value = currentSynthesizedPost.sourceHeadline || currentSynthesizedPost.spark || currentSynthesizedPost.originalHeadline || currentSynthesizedPost.newsprintExcerpt || currentSynthesizedPost.hook || '';
  if (handleInput) handleInput.value = currentSynthesizedPost.creatorHandle || '@curator';
  if (s2TitleInput) s2TitleInput.value = currentSynthesizedPost.critiqueBadge || (currentSynthesizedPost.keyTakeaways && currentSynthesizedPost.keyTakeaways[0] ? currentSynthesizedPost.keyTakeaways[0].toUpperCase() : 'THE CRITICAL PERSPECTIVE');
  if (opinionInput) opinionInput.value = currentSynthesizedPost.curatorTake || currentSynthesizedPost.creatorOpinion || '';
  if (whyInput) whyInput.value = currentSynthesizedPost.whyItMatters || '';
  if (metricInput) metricInput.value = currentSynthesizedPost.keyMetric || '';

  // Poster 1 Artwork source toggle
  const artRow = document.getElementById('editModalArtworkToggleRow');
  if (artRow) {
    const hasPhoto = !!(currentSynthesizedPost.referencePhotoUrl);
    artRow.style.display = hasPhoto ? 'block' : 'none';
    const isUsingExact = (currentSynthesizedPost.illustrationUrl === currentSynthesizedPost.referencePhotoUrl);
    const pillExact = document.getElementById('editArtPillExact');
    const pillLik = document.getElementById('editArtPillLikeness');
    const pillMet = document.getElementById('editArtPillMetaphor');
    if (pillExact) pillExact.classList.toggle('active', isUsingExact);
    if (pillLik) pillLik.classList.toggle('active', !isUsingExact && currentSynthesizedPost.characterRepresentation === 'likeness');
    if (pillMet) pillMet.classList.toggle('active', !isUsingExact && currentSynthesizedPost.characterRepresentation !== 'likeness');
  }

  if (s3Head) {
    s3Head.value = currentSynthesizedPost.broadsheetHeadline || currentSynthesizedPost.originalHeadline || currentSynthesizedPost.adaptedHeadline || '';
  }
  if (s3Quote) {
    s3Quote.value = currentSynthesizedPost.receiptHighlightQuote || currentSynthesizedPost.broadsheetHighlight || currentSynthesizedPost.pullQuote || '';
  }
  if (s3Obs) {
    const rawSum = String(currentSynthesizedPost.summary || currentSynthesizedPost.broadsheetObservation || '').trim();
    const sumParas = splitEditorialParagraphsOrMoments(rawSum);
    const exArrRaw = Array.isArray(currentSynthesizedPost.resolvedArticleExcerpts) && currentSynthesizedPost.resolvedArticleExcerpts.length > 0
      ? currentSynthesizedPost.resolvedArticleExcerpts
      : (Array.isArray(currentSynthesizedPost.articleExcerpts) ? currentSynthesizedPost.articleExcerpts : []);
    const exArr = splitEditorialParagraphsOrMoments(exArrRaw);
    s3Obs.value = (exArr.length >= sumParas.length && exArr.length > 0) ? exArr.join('\n\n') : (sumParas.length > 0 ? sumParas.join('\n\n') : rawSum);
  }
  if (s3Ref) {
    s3Ref.value = currentSynthesizedPost.broadsheetReflection || currentSynthesizedPost.whyItMatters || '';
  }

  captureEditModalSnapshot();
  hideEditModalReviewCard();

  const modal = document.getElementById('editPosterModal');
  if (modal) {
    modal.classList.add('open');
    modal.classList.add('active');
    modal.style.display = 'flex';
  }
}

function closeEditPosterModal() {
  const modal = document.getElementById('editPosterModal');
  if (modal) {
    modal.classList.remove('open');
    modal.classList.remove('active');
    modal.style.display = 'none';
  }
  hideEditPolishPopover();
}

function switchEditModalTab(tabIdx) {
  const isChronicle = isChronicleModePost(currentSynthesizedPost);
  const isChronicleCardsOnly = isChronicle && isChronicleWithoutWatercolorPoster(currentSynthesizedPost);
  if (isChronicleCardsOnly) {
    currentPreviewSlide = (tabIdx === 1) ? 1 : 0;
  } else if (tabIdx === 0) {
    currentPreviewSlide = 0;
  } else if (tabIdx === 2) {
    currentPreviewSlide = 1;
  } else if (tabIdx === 1) {
    currentPreviewSlide = isChronicle ? 2 : 1;
  }
  for (let i = 0; i < 3; i++) {
    const tabBtn = document.getElementById(`editTab${i}`);
    const tabPane = document.getElementById(`editTabPane${i}`);
    if (tabBtn) tabBtn.classList.toggle('active', i === tabIdx);
    if (tabPane) tabPane.style.display = (i === tabIdx) ? 'flex' : 'none';
  }
}

function hideEditModalReviewCard() {
  const card = document.getElementById('editModalReviewCard');
  if (card) card.style.display = 'none';
  hideEditPolishPopover();
}

async function reviewActiveTabChanges(tabIdx) {
  let fieldsToReview = getEditedProseFields(tabIdx);

  if (fieldsToReview.length === 0) {
    const primaryMap = {
      0: { id: 'editModalHeadline', label: 'Slide 1: Hook Headline', snapshotKey: 'headline', minLen: 3 },
      1: { id: 'editModalOpinion', label: 'Slide 2: Curator Take', snapshotKey: 'opinion', minLen: 5 },
      2: { id: 'editModalS3Observation', label: 'Slide 3: Broadsheet Essay', snapshotKey: 's3Observation', minLen: 10 }
    };
    const primary = primaryMap[tabIdx];
    if (primary) {
      const el = document.getElementById(primary.id);
      const val = el ? el.value.trim() : '';
      if (val && val.length >= primary.minLen) {
        fieldsToReview = [{
          ...primary,
          element: el,
          oldVal: val,
          newVal: val
        }];
      }
    }
  }

  if (fieldsToReview.length === 0) {
    showTemporaryToast('⚠️ Please write some text on this slide before reviewing.');
    return;
  }

  await runEditModalReview(fieldsToReview, tabIdx);
}

async function runEditModalReview(fieldsToReview, fromTab = null) {
  const saveBtn = document.getElementById('editModalSaveBtn');
  const saveBtnText = document.getElementById('editModalSaveBtnText');
  const reviewCard = document.getElementById('editModalReviewCard');
  const display = document.getElementById('editPolishedTextDisplay');

  let activeTabReviewBtn = null;
  if (typeof fromTab === 'number') {
    activeTabReviewBtn = document.getElementById(`editSlide${fromTab}ReviewBtn`);
  }

  const originalSaveBtnHtml = saveBtnText ? saveBtnText.innerHTML : 'Save Changes & Update Posters';
  const originalTabBtnHtml = activeTabReviewBtn ? activeTabReviewBtn.innerHTML : '';

  if (saveBtn) saveBtn.disabled = true;
  if (saveBtnText) saveBtnText.innerHTML = '<span class="btn-spark-icon spinning">⏳</span> Analyzing edits for phrasing & grammar...';
  if (activeTabReviewBtn) {
    activeTabReviewBtn.disabled = true;
    activeTabReviewBtn.innerHTML = '<span class="btn-spark-icon spinning">⏳</span> Reviewing...';
  }

  try {
    const reviewPromises = fieldsToReview.map(async (field) => {
      try {
        const resp = await fetch('/api/synthesize', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            action: 'polish_take',
            includeVisualOptions: false,
            skipStructureBeats: true,
            text: field.newVal
          })
        });

        if (resp.ok) {
          const data = await resp.json();
          if (data && data.success !== false && (data.polished || data.highlightedHtml)) {
            return {
              field,
              success: true,
              polished: data.polished || field.newVal,
              highlightedHtml: data.highlightedHtml || escapeHtml(data.polished || field.newVal),
              corrections: Array.isArray(data.corrections) ? data.corrections : [],
              counts: data.counts || { spelling: 0, grammar: 0, punctuation: 0, phrasing: 0, total: 0 }
            };
          }
        }
      } catch (err) {
        console.warn('Error reviewing field:', field.label, err);
      }

      const fallback = formatCuratorTakeApt(field.newVal);
      return {
        field,
        success: false,
        polished: fallback,
        highlightedHtml: escapeHtml(fallback),
        corrections: [],
        counts: { spelling: 0, grammar: 0, punctuation: 0, phrasing: 0, total: 0 }
      };
    });

    const results = await Promise.all(reviewPromises);
    lastEditModalPolishedResults = results;

    const aggregatedCounts = { spelling: 0, grammar: 0, punctuation: 0, phrasing: 0, total: 0 };
    let allCorrections = [];
    results.forEach(r => {
      aggregatedCounts.spelling += (r.counts?.spelling || 0);
      aggregatedCounts.grammar += (r.counts?.grammar || 0);
      aggregatedCounts.punctuation += (r.counts?.punctuation || 0);
      aggregatedCounts.phrasing += (r.counts?.phrasing || 0);
      aggregatedCounts.total += (r.counts?.total || 0);
      if (Array.isArray(r.corrections)) {
        allCorrections = allCorrections.concat(r.corrections);
      }
    });

    lastEditModalCorrections = allCorrections;
    editModalLastReviewedSignature = fieldsToReview.map(f => `${f.id}:${f.newVal}`).join('|||');

    if (aggregatedCounts.total === 0) {
      showTemporaryToast('✨ Great job! Your edits read naturally and are free of errors.');
      applyEditModalFormValues();
      renderCreatorPreview(currentPreviewSlide || 0);
      closeEditPosterModal();
      return;
    }

    const countAllEl = document.getElementById('editCountAll');
    const countSpellEl = document.getElementById('editCountSpelling');
    const countGramEl = document.getElementById('editCountGrammar');
    const countPunctEl = document.getElementById('editCountPunctuation');
    const countPhraseEl = document.getElementById('editCountPhrasing');
    const countTotalEl = document.getElementById('editPolishTotalCorrectionsCount');
    const fidelityBadge = document.getElementById('editReviewFidelityBadge');

    if (countAllEl) countAllEl.textContent = aggregatedCounts.total;
    if (countSpellEl) countSpellEl.textContent = aggregatedCounts.spelling;
    if (countGramEl) countGramEl.textContent = aggregatedCounts.grammar;
    if (countPunctEl) countPunctEl.textContent = aggregatedCounts.punctuation;
    if (countPhraseEl) countPhraseEl.textContent = aggregatedCounts.phrasing;
    if (countTotalEl) countTotalEl.textContent = aggregatedCounts.total;
    if (fidelityBadge) fidelityBadge.textContent = `${aggregatedCounts.total} Notes • 100% Your Voice`;

    currentEditPolishFilter = 'all';
    if (display) display.removeAttribute('data-filter');
    const chips = document.querySelectorAll('#editPolishLegendBar .polish-legend-chip');
    chips.forEach(chip => chip.classList.toggle('active', chip.id === 'editFilterChipAll'));

    const btnHighlight = document.getElementById('editReviewToggleHighlighted');
    const btnClean = document.getElementById('editReviewToggleClean');
    if (btnHighlight) btnHighlight.classList.add('active');
    if (btnClean) btnClean.classList.remove('active');
    editPolishDisplayMode = 'highlighted';

    if (display) {
      let sectionsHtml = '';
      results.forEach(r => {
        sectionsHtml += `
          <div class="edit-review-field-section">
            <div class="edit-review-field-label">${escapeHtml(r.field.label)}</div>
            <div class="edit-review-field-content edit-review-field-highlighted">${r.highlightedHtml}</div>
            <div class="edit-review-field-content edit-review-field-clean" style="display:none;">${escapeHtml(r.polished)}</div>
          </div>
        `;
      });
      display.innerHTML = sectionsHtml;
      attachEditPolishMarkListeners(display);
    }

    if (reviewCard) {
      reviewCard.style.display = 'flex';
      reviewCard.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }

    showTemporaryToast(`✨ Review ready with ${aggregatedCounts.total} coaching notes. Tap any highlighted word!`);
  } catch (err) {
    console.error('Error running edit modal review:', err);
    showTemporaryToast('⚠️ Review connection issue. You can still save your changes.');
  } finally {
    if (saveBtn) saveBtn.disabled = false;
    if (saveBtnText) saveBtnText.innerHTML = originalSaveBtnHtml;
    if (activeTabReviewBtn) {
      activeTabReviewBtn.disabled = false;
      activeTabReviewBtn.innerHTML = originalTabBtnHtml;
    }
  }
}

function attachEditPolishMarkListeners(container) {
  if (!container) return;
  const marks = container.querySelectorAll('.polish-mark');
  marks.forEach(mark => {
    mark.addEventListener('click', (e) => {
      e.stopPropagation();
      marks.forEach(m => m.classList.remove('active'));
      mark.classList.add('active');
      const original = mark.getAttribute('data-original') || '';
      const replacement = mark.textContent || '';
      const type = mark.getAttribute('data-type') || 'phrasing';
      const reason = mark.getAttribute('data-reason') || 'Improved phrasing and flow';
      showEditPolishPopover(mark, original, replacement, type, reason);
    });
  });
}

function setEditReviewDisplayMode(mode) {
  editPolishDisplayMode = mode;
  const btnHighlight = document.getElementById('editReviewToggleHighlighted');
  const btnClean = document.getElementById('editReviewToggleClean');
  if (btnHighlight) btnHighlight.classList.toggle('active', mode === 'highlighted');
  if (btnClean) btnClean.classList.toggle('active', mode === 'clean');

  const display = document.getElementById('editPolishedTextDisplay');
  if (!display) return;

  const highlightedEls = display.querySelectorAll('.edit-review-field-highlighted');
  const cleanEls = display.querySelectorAll('.edit-review-field-clean');

  highlightedEls.forEach(el => el.style.display = (mode === 'highlighted') ? 'block' : 'none');
  cleanEls.forEach(el => el.style.display = (mode === 'clean') ? 'block' : 'none');
  hideEditPolishPopover();
}

function filterEditPolishHighlights(category) {
  const display = document.getElementById('editPolishedTextDisplay');
  hideEditPolishPopover();

  if (currentEditPolishFilter === category && category !== 'all') {
    category = 'all';
  }
  currentEditPolishFilter = category;

  const chips = document.querySelectorAll('#editPolishLegendBar .polish-legend-chip');
  chips.forEach(chip => chip.classList.remove('active'));

  if (category === 'all') {
    document.getElementById('editFilterChipAll')?.classList.add('active');
    if (display) display.removeAttribute('data-filter');
  } else {
    const chipMap = {
      spelling: 'editFilterChipSpelling',
      grammar: 'editFilterChipGrammar',
      punctuation: 'editFilterChipPunctuation',
      phrasing: 'editFilterChipPhrasing'
    };
    if (chipMap[category]) {
      document.getElementById(chipMap[category])?.classList.add('active');
    }
    if (display) display.setAttribute('data-filter', category);
  }
}

function showEditPolishPopover(targetEl, original, replacement, type, reason) {
  const popover = document.getElementById('editPolishPopover');
  if (!popover || !targetEl) return;

  const badgeEl = document.getElementById('editPopoverBadge');
  const origEl = document.getElementById('editPopoverOriginal');
  const repEl = document.getElementById('editPopoverReplacement');
  const reasonEl = document.getElementById('editPopoverReason');

  if (badgeEl) {
    badgeEl.textContent = (type || 'phrasing').toUpperCase();
    badgeEl.className = `popover-badge badge-${type || 'phrasing'}`;
  }
  if (origEl) origEl.textContent = original || 'None';
  if (repEl) repEl.textContent = replacement || '';
  if (reasonEl) reasonEl.textContent = reason || 'Refined phrasing for flow';

  const rect = targetEl.getBoundingClientRect();
  const parentRect = targetEl.closest('.review-card-body-wrap')?.getBoundingClientRect() || rect;

  const top = rect.bottom - parentRect.top + 6;
  const left = Math.max(10, Math.min(parentRect.width - 290, rect.left - parentRect.left));

  popover.style.top = `${top}px`;
  popover.style.left = `${left}px`;
  popover.style.display = 'block';
}

function hideEditPolishPopover() {
  const popover = document.getElementById('editPolishPopover');
  if (popover) popover.style.display = 'none';
  document.querySelectorAll('#editPolishedTextDisplay .polish-mark.active').forEach(m => m.classList.remove('active'));
}

function acceptEditPolishedChanges() {
  if (Array.isArray(lastEditModalPolishedResults)) {
    lastEditModalPolishedResults.forEach(r => {
      if (r.field && r.field.element && r.polished) {
        r.field.element.value = r.polished;
      }
    });
  }
  saveEditedSlideContent(true);
  showTemporaryToast('✨ Polished edits accepted & posters updated!');
}

function keepEditOriginalChanges() {
  saveEditedSlideContent(true);
  showTemporaryToast('✏️ Posters updated with your exact wording!');
}

function applyEditModalFormValues() {
  if (!currentSynthesizedPost) return;

  const catInput = document.getElementById('editModalCategory');
  const pubInput = document.getElementById('editModalPublication');
  const headInput = document.getElementById('editModalHeadline');
  const excerptInput = document.getElementById('editModalNewsExcerpt');
  const handleInput = document.getElementById('editModalHandle');
  const s2TitleInput = document.getElementById('editModalS2Title');
  const opinionInput = document.getElementById('editModalOpinion');
  const whyInput = document.getElementById('editModalWhyItMatters');
  const metricInput = document.getElementById('editModalMetric');
  const s3Head = document.getElementById('editModalS3Headline');
  const s3Quote = document.getElementById('editModalS3Quote');
  const s3Obs = document.getElementById('editModalS3Observation');
  const s3Ref = document.getElementById('editModalS3Reflection');

  // Slide 1
  if (catInput && catInput.value.trim()) currentSynthesizedPost.categoryBadge = catInput.value.trim().toUpperCase();
  if (pubInput && pubInput.value.trim()) {
    currentSynthesizedPost.publicationName = pubInput.value.trim();
    currentSynthesizedPost.sourcePublication = pubInput.value.trim();
  }
  if (headInput && headInput.value.trim()) currentSynthesizedPost.adaptedHeadline = headInput.value.trim();
  if (excerptInput && excerptInput.value.trim()) {
    const val = excerptInput.value.trim();
    currentSynthesizedPost.sourceHeadline = val;
    currentSynthesizedPost.originalHeadline = val;
    currentSynthesizedPost.spark = val;
    currentSynthesizedPost.newsprintExcerpt = val;
    currentSynthesizedPost.hook = val;
  }
  if (handleInput && handleInput.value.trim()) currentSynthesizedPost.creatorHandle = handleInput.value.trim();

  // Slide 2
  if (s2TitleInput && s2TitleInput.value.trim()) {
    currentSynthesizedPost.critiqueBadge = s2TitleInput.value.trim();
    currentSynthesizedPost.keyTakeaways = currentSynthesizedPost.keyTakeaways || [];
    currentSynthesizedPost.keyTakeaways[0] = s2TitleInput.value.trim();
  }
  if (opinionInput && opinionInput.value.trim()) {
    const cleanOpinion = opinionInput.value.trim();
    currentSynthesizedPost.creatorOpinion = cleanOpinion;
    currentSynthesizedPost.curatorTake = cleanOpinion;
    if (Array.isArray(currentSynthesizedPost.chronicleReflections) && currentSynthesizedPost.chronicleReflections.length > 0) {
      currentSynthesizedPost.chronicleReflections[0].quote = cleanOpinion;
    }
    if (Array.isArray(currentSynthesizedPost.generationInputs?.chronicleReflections) && currentSynthesizedPost.generationInputs.chronicleReflections.length > 0) {
      currentSynthesizedPost.generationInputs.chronicleReflections[0].quote = cleanOpinion;
    }
  }
  if (whyInput && whyInput.value.trim()) currentSynthesizedPost.whyItMatters = whyInput.value.trim();
  if (metricInput && metricInput.value.trim()) currentSynthesizedPost.keyMetric = metricInput.value.trim();

  // Slide 3 (or Poster 2 Moments in Daily Chronicle): All content editable for all sources
  if (s3Head) {
    const headVal = s3Head.value.trim();
    currentSynthesizedPost.broadsheetHeadline = headVal;
  }
  if (s3Quote) {
    const quoteVal = s3Quote.value.trim();
    currentSynthesizedPost.receiptHighlightQuote = quoteVal;
    currentSynthesizedPost.broadsheetHighlight = quoteVal;
    currentSynthesizedPost.pullQuote = quoteVal;
  }
  if (s3Obs) {
    const rawObs = s3Obs.value.trim();
    const obsParas = splitEditorialParagraphsOrMoments(rawObs);
    const cleanObs = obsParas.length > 0 ? obsParas.join('\n\n') : rawObs;
    currentSynthesizedPost.summary = cleanObs;
    currentSynthesizedPost.broadsheetObservation = cleanObs;
    currentSynthesizedPost.articleExcerpts = obsParas;
    currentSynthesizedPost.resolvedArticleExcerpts = obsParas;
    if (isChronicleModePost(currentSynthesizedPost) && obsParas.length > 0) {
      const existingMoments = Array.isArray(currentSynthesizedPost.chronicleMoments)
        ? currentSynthesizedPost.chronicleMoments
        : (Array.isArray(currentSynthesizedPost.generationInputs?.chronicleMoments) ? currentSynthesizedPost.generationInputs.chronicleMoments : []);
      const updatedMoments = obsParas.map((pText, idx) => {
        const prev = existingMoments[idx] || {};
        const strippedText = String(pText || '').replace(/^(?:0?[1-9]\s*[·•.-]\s*)?Moment\s+\d+(?:\s*[·•.-]\s*[^:]{1,38})?:\s*/i, '').trim();
        return {
          ...prev,
          index: idx + 1,
          title: prev.title || `Moment ${String(idx + 1).padStart(2, '0')}`,
          text: strippedText || pText
        };
      });
      currentSynthesizedPost.chronicleMoments = updatedMoments;
      if (currentSynthesizedPost.generationInputs && typeof currentSynthesizedPost.generationInputs === 'object') {
        currentSynthesizedPost.generationInputs.chronicleMoments = updatedMoments;
      }
    }
  }
  if (s3Ref) {
    const refVal = s3Ref.value.trim();
    currentSynthesizedPost.broadsheetReflection = refVal;
    currentSynthesizedPost.whyItMatters = refVal;
  }

  // Clear cached bifurcation and poster file caches so fresh edits render immediately
  delete currentSynthesizedPost._cachedBifurcation;
  delete currentSynthesizedPost._calibratedBifurcation;
  if (typeof posterFilesCache !== 'undefined' && posterFilesCache) {
    if (currentSynthesizedPost.id) posterFilesCache.delete(currentSynthesizedPost.id);
    posterFilesCache.delete('preview');
  }
}

async function saveEditedSlideContent(skipReview = false) {
  if (!currentSynthesizedPost) return;

  const changedFields = getEditedProseFields();

  if (!skipReview && changedFields.length > 0) {
    const signature = changedFields.map(f => `${f.id}:${f.newVal}`).join('|||');
    if (signature !== editModalLastReviewedSignature) {
      await runEditModalReview(changedFields);
      return;
    }
  }

  applyEditModalFormValues();

  // Re-render preview with edited values and stay on current edited slide
  renderCreatorPreview(currentPreviewSlide);

  closeEditPosterModal();
  showTemporaryToast('✏️ Poster updated with edits!');
}

async function handleStep3Share() {
  if (!currentSynthesizedPost) return;

  const post = currentSynthesizedPost;
  const shareUrl = getPostShareUrl(post);
  const headline = post.adaptedHeadline || post.originalHeadline || 'Slant Editorial Carousel';
  const shareText = getPostShareText(post);

  try {
    showTemporaryToast('📸 Preparing posters to share...');
    const files = await capturePostSlidesAsFiles(post, 0);
    if (files && files.length > 0) {
      openSharePostersModal(post, files);
      return;
    }
  } catch (err) {
    console.warn('capturePostSlidesAsFiles error during share:', err);
  }

  // Fallback to text share sheet (text already embeds the link, so omit separate url to avoid duplicate)
  const shareData = {
    title: headline,
    text: shareText
  };

  if (navigator.share) {
    try {
      if (navigator.canShare && !navigator.canShare(shareData)) {
        shareData.url = shareUrl;
      }
      await navigator.share(shareData);
    } catch (err) {
      if (err.name !== 'AbortError') {
        copyShareUrlFallback(shareUrl);
      }
    }
  } else {
    copyShareUrlFallback(shareUrl);
  }
}

function copyShareUrlFallback(customUrl) {
  const urlToCopy = customUrl || window.location.origin;
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(urlToCopy).then(() => {
      showTemporaryToast('📋 Share link copied to clipboard!');
    }).catch(() => {
      showTemporaryToast('📋 Link: ' + urlToCopy);
    });
  } else {
    showTemporaryToast('📋 Link: ' + urlToCopy);
  }
}

async function handleStep3Download() {
  if (!currentSynthesizedPost) return;
  const dlBtn = document.getElementById('step3DownloadBtn');
  const dlLbl = document.getElementById('step3DownloadLabel');

  try {
    showTemporaryToast('📥 Rendering 3 high-res posters for your gallery...');
    if (dlLbl) dlLbl.textContent = 'Saving...';

    const files = await capturePostSlidesAsFiles(currentSynthesizedPost, 0);
    if (files && files.length > 0) {
      downloadShareFiles(files);
      if (dlBtn) dlBtn.classList.add('active');
      if (dlLbl) dlLbl.textContent = 'Downloaded';
      showTemporaryToast('✅ 3 posters saved to your gallery / downloads!');
      return;
    }
  } catch (err) {
    console.warn('High-res trio render failed, falling back to direct poster download:', err);
  }

  // Resilient fallback: direct image download
  const imgUrl = currentSynthesizedPost.illustrationUrl || currentSynthesizedPost.posterBase64 || currentSynthesizedPost.imageUrl;
  if (imgUrl) {
    const a = document.createElement('a');
    a.href = imgUrl;
    const slug = (currentSynthesizedPost.categoryBadge || 'slant').toLowerCase().replace(/[^a-z0-9]+/g, '-');
    a.download = `${slug}-poster-slide${(currentPreviewSlide || 0) + 1}.png`;
    a.target = '_blank';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);

    if (dlBtn) dlBtn.classList.add('active');
    if (dlLbl) dlLbl.textContent = 'Downloaded';
    showTemporaryToast('📥 Poster saved to your gallery / downloads!');
  } else {
    showTemporaryToast('📥 Poster ready for export!');
  }
}

async function compressImageForCloud(base64Data, maxWidth = 900, quality = 0.82) {
  if (!base64Data || typeof base64Data !== 'string') {
    return base64Data;
  }
  let src = base64Data;
  if (!src.startsWith('data:image')) {
    const isPng = src.startsWith('iVBORw');
    src = `data:image/${isPng ? 'png' : 'jpeg'};base64,${src}`;
  }
  return new Promise((resolve) => {
    try {
      const img = new Image();
      img.onload = () => {
        try {
          let w = img.width;
          let h = img.height;
          if (w > maxWidth) {
            h = Math.round((h * maxWidth) / w);
            w = maxWidth;
          }
          const canvas = document.createElement('canvas');
          canvas.width = w;
          canvas.height = h;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(img, 0, 0, w, h);
          let result = canvas.toDataURL('image/webp', quality);
          if (!result || !result.startsWith('data:image/webp')) {
            result = canvas.toDataURL('image/jpeg', quality);
          }
          resolve(result);
        } catch (_) {
          resolve(base64Data);
        }
      };
      img.onerror = () => resolve(base64Data);
      img.src = src;
    } catch (_) {
      resolve(base64Data);
    }
  });
}

async function uploadArtworkToSupabaseStorage(postId, base64Data) {
  if (!base64Data || typeof base64Data !== 'string') return null;
  try {
    let cleanB64 = base64Data;
    let mime = 'image/webp';
    let ext = 'webp';
    if (!base64Data.startsWith('data:image/')) {
      const isPng = base64Data.startsWith('iVBORw');
      base64Data = `data:image/${isPng ? 'png' : 'jpeg'};base64,${base64Data}`;
    }
    const match = base64Data.match(/^data:(image\/[^;]+);base64,/);
    if (match) {
      mime = match[1];
      ext = mime.includes('png') ? 'png' : (mime.includes('jpeg') || mime.includes('jpg') ? 'jpg' : 'webp');
      cleanB64 = base64Data.slice(match[0].length);
    }
    const byteCharacters = atob(cleanB64);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);
    const blob = new Blob([byteArray], { type: mime });
    const fileName = `${postId}.${ext}`;

    const uploadResp = await fetch(`${SUPABASE_URL}/storage/v1/object/posters/${fileName}`, {
      method: 'POST',
      headers: {
        'apikey': SUPABASE_KEY,
        'Authorization': `Bearer ${SUPABASE_KEY}`,
        'Content-Type': mime,
        'x-upsert': 'true'
      },
      body: blob
    });

    if (uploadResp.ok) {
      // Also save alternate extension for full edge CDN compatibility
      const altExt = ext === 'webp' ? 'png' : 'webp';
      fetch(`${SUPABASE_URL}/storage/v1/object/posters/${postId}.${altExt}`, {
        method: 'POST',
        headers: {
          'apikey': SUPABASE_KEY,
          'Authorization': `Bearer ${SUPABASE_KEY}`,
          'Content-Type': mime,
          'x-upsert': 'true'
        },
        body: blob
      }).catch(() => {});

      return `${SUPABASE_URL}/storage/v1/object/public/posters/${fileName}?v=${Date.now()}`;
    } else {
      console.warn('Direct storage upload HTTP status:', uploadResp.status);
    }
  } catch (err) {
    console.warn('Direct storage upload error:', err);
  }
  return null;
}

async function saveSynthesizedPost(options = {}) {
  if (!currentSynthesizedPost) return;

  if (!currentSynthesizedPost.illustrationBase64 && !currentSynthesizedPost.posterBase64 && currentSynthesizedPost.artworkError) {
    const proceed = confirm('Visual poster artwork is still pending or timed out.\n\nTap OK to save as a text draft (artwork will be generated on demand), or Cancel to Retry generating the artwork first.');
    if (!proceed) {
      return;
    }
  }

  const isChronicle = isChronicleModePost(currentSynthesizedPost);
  const asDraftOnly = Boolean(options && options.asDraftOnly);
  const saveBtn = document.getElementById('step3SaveBtn');
  const saveLbl = document.getElementById('step3SaveLabel');
  const bottomSaveBtn = document.getElementById('step3BottomSaveDraftBtn');
  if (saveBtn) saveBtn.disabled = true;
  if (saveLbl) saveLbl.textContent = 'Saving...';
  if (bottomSaveBtn) {
    bottomSaveBtn.disabled = true;
    bottomSaveBtn.innerHTML = (isChronicle && !asDraftOnly)
      ? '<span>Saving to My Diary... ⏳</span>'
      : '<span>Saving Draft... ⏳</span>';
  }

  if (currentUser) {
    currentSynthesizedPost.user_id = currentUser.id;
    currentSynthesizedPost.userEmail = currentUser.email;
  }
  currentSynthesizedPost.createdAt = new Date().toISOString();
  currentSynthesizedPost.isUserCreated = true;
  currentSynthesizedPost.isDraft = true;
  currentSynthesizedPost.isPrivate = true;
  currentSynthesizedPost.isPubliclyPublished = false;
  currentSynthesizedPost.allowComments = Boolean(creatorAllowComments);
  if (isChronicle) {
    currentSynthesizedPost.isDiaryDraftOnly = asDraftOnly;
    currentSynthesizedPost.isDiary = !asDraftOnly;
  }
  currentSynthesizedPost.status = 'draft';

  const savedSeriesObj = (!isChronicle && activeCreatorSeriesId && Array.isArray(creatorSeriesList))
    ? creatorSeriesList.find(s => s && s.id === activeCreatorSeriesId)
    : (!isChronicle ? getPostSeriesInfo(currentSynthesizedPost) : null);
  if (savedSeriesObj) {
    currentSynthesizedPost.seriesId = savedSeriesObj.id;
    currentSynthesizedPost.seriesTitle = savedSeriesObj.title;
    if (!currentSynthesizedPost.generationInputs) currentSynthesizedPost.generationInputs = {};
    currentSynthesizedPost.generationInputs.seriesId = savedSeriesObj.id;
    currentSynthesizedPost.generationInputs.seriesTitle = savedSeriesObj.title;
    if (savedSeriesObj.description) {
      currentSynthesizedPost.generationInputs.seriesDescription = savedSeriesObj.description;
    }
    if (savedSeriesObj.customCoverImage && savedSeriesObj.customCoverImage.startsWith('http')) {
      currentSynthesizedPost.generationInputs.seriesCoverImage = savedSeriesObj.customCoverImage;
    }
  }

  // 1. Clean & compress payload: store lightweight CDN pointer so Supabase rows never trigger timeout
  const postToSave = { ...currentSynthesizedPost };
  if (savedSeriesObj) {
    postToSave.seriesId = savedSeriesObj.id;
    postToSave.seriesTitle = savedSeriesObj.title;
  }
  const savedSlantTake = currentSynthesizedPost.polishedCuratorTake || currentSynthesizedPost.generationInputs?.slantTake || currentSynthesizedPost.userSlantTake || '';
  if (savedSlantTake) {
    postToSave.polishedCuratorTake = savedSlantTake;
    postToSave.userSlantTake = savedSlantTake;
    if (!postToSave.generationInputs) postToSave.generationInputs = {};
    postToSave.generationInputs.slantTake = savedSlantTake;
  }
  if (currentSynthesizedPost.generationInputs) {
    postToSave.generationInputs = currentSynthesizedPost.generationInputs;
  }
  const activeDraftLedger = currentSynthesizedPost.sourceLedger || currentSourceLedger || postToSave.generationInputs?.sourceLedger || null;
  if (activeDraftLedger) {
    postToSave.sourceLedger = activeDraftLedger;
    if (!postToSave.generationInputs) postToSave.generationInputs = {};
    postToSave.generationInputs.sourceLedger = activeDraftLedger;
  }
  if (currentSynthesizedPost.contextProvided) {
    postToSave.contextProvided = currentSynthesizedPost.contextProvided;
  }
  if (currentSynthesizedPost.userSlantTake) {
    postToSave.userSlantTake = currentSynthesizedPost.userSlantTake;
  }
  if (currentSynthesizedPost.sourceContext) {
    postToSave.sourceContext = currentSynthesizedPost.sourceContext;
  }
  postToSave.isDraft = true;
  postToSave.isPrivate = true;
  postToSave.isPubliclyPublished = false;
  if (isChronicle) {
    postToSave.isDiaryDraftOnly = asDraftOnly;
    postToSave.isDiary = !asDraftOnly;
  }
  postToSave.status = 'draft';

  let hasUploadedPublicUrl = false;
  let rawPoster = currentSynthesizedPost.illustrationBase64 || currentSynthesizedPost.posterBase64 || currentSynthesizedPost.originalPhotoBase64;
  if (rawPoster && typeof rawPoster === 'string' && rawPoster.length > 50) {
    if (!rawPoster.startsWith('data:image/')) {
      const isPng = rawPoster.startsWith('iVBORw');
      rawPoster = `data:image/${isPng ? 'png' : 'jpeg'};base64,${rawPoster}`;
    }
    try {
      const compressed = await compressImageForCloud(rawPoster, 960, 0.85);
      const publicUrl = await uploadArtworkToSupabaseStorage(postToSave.id, compressed);
      if (publicUrl) {
        hasUploadedPublicUrl = true;
        postToSave.illustrationUrl = publicUrl;
        postToSave.aiIllustrationUrl = publicUrl;
        currentSynthesizedPost.illustrationUrl = publicUrl;
        currentSynthesizedPost.aiIllustrationUrl = publicUrl;
      }
    } catch (_) {}
  }

  if (!postToSave.illustrationUrl) {
    postToSave.illustrationUrl = `/posters/${postToSave.id}.png`;
    postToSave.aiIllustrationUrl = postToSave.illustrationUrl;
    postToSave.artworkPending = true;
  }

  // Purge heavy base64 fields only if direct cloud upload already succeeded, otherwise let backend upload it
  if (hasUploadedPublicUrl) {
    delete postToSave.posterBase64;
    delete postToSave.illustrationBase64;
  }
  delete postToSave.originalPhotoBase64;
  delete postToSave.sourceImageBase64;
  delete postToSave.catalystPhotoBase64;
  if (typeof postToSave.catalystPhoto === 'string' && postToSave.catalystPhoto.startsWith('data:image/')) {
    delete postToSave.catalystPhoto;
  }
  if (postToSave.generationInputs) {
    delete postToSave.generationInputs.sourceImageBase64;
    delete postToSave.generationInputs.catalystPhotoBase64;
    delete postToSave.generationInputs.innerVoiceImageBase64;
    if (typeof postToSave.generationInputs.catalystPhoto === 'string' && postToSave.generationInputs.catalystPhoto.startsWith('data:image/')) {
      delete postToSave.generationInputs.catalystPhoto;
    }
    if (typeof postToSave.generationInputs.referencePhotoUrl === 'string' && postToSave.generationInputs.referencePhotoUrl.startsWith('data:image/')) {
      delete postToSave.generationInputs.referencePhotoUrl;
    }
  }

  // 1b. Client-side AES-256-GCM encryption for Personal Diary (Daily Chronicles) before cloud or local storage
  const finalCloudPayload = isChronicle ? await encryptChroniclePostForCloud(postToSave) : postToSave;
  if (isChronicle && finalCloudPayload && finalCloudPayload.encryptedDiaryPayload) {
    currentSynthesizedPost.encryptedDiaryPayload = finalCloudPayload.encryptedDiaryPayload;
    currentSynthesizedPost.isEncryptedDiary = true;
    currentSynthesizedPost._diaryDecrypted = true;
    _upgradedChronicleIds.add(currentSynthesizedPost.id);
  }

  // 2. Cloud save: POST to /api/posts
  let savedToCloud = false;
  try {
    const resp = await fetch('/api/posts', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(finalCloudPayload)
    });
    if (resp.ok) savedToCloud = true;
  } catch (err) {
    console.warn('Backend save call error:', err);
  }

  // 3. Fallback: Direct Supabase write
  if (!savedToCloud) {
    try {
      const supaResp = await fetch(`${SUPABASE_URL}/rest/v1/posts`, {
        method: 'POST',
        headers: {
          'apikey': SUPABASE_KEY,
          'Authorization': `Bearer ${SUPABASE_KEY}`,
          'Content-Type': 'application/json',
          'Prefer': 'resolution=merge-duplicates'
        },
        body: JSON.stringify({ id: finalCloudPayload.id, data: finalCloudPayload })
      });
      if (supaResp.ok) savedToCloud = true;
    } catch (supaErr) {
      console.warn('Direct Supabase save error:', supaErr);
    }
  }

  // 4. Local storage persistent cache for user profile (stores encrypted payload for Chronicles)
  try {
    const sanitizeForCache = (p) => {
      if (!p) return null;
      const copy = { ...p };
      delete copy.originalPhotoBase64;
      delete copy.posterBase64;
      delete copy.sourceImageBase64;
      delete copy.catalystPhotoBase64;
      if (copy.illustrationBase64 && copy.illustrationBase64.length > 50000) {
        delete copy.illustrationBase64;
      }
      if (!copy.illustrationUrl) {
        copy.illustrationUrl = `${SUPABASE_URL}/storage/v1/object/public/posters/${copy.id}.webp`;
        copy.aiIllustrationUrl = copy.illustrationUrl;
      }
      return copy;
    };

    const localPosts = JSON.parse(localStorage.getItem('slant_user_posts_cache') || '[]');
    const filtered = localPosts.filter(p => p && p.id !== currentSynthesizedPost.id).map(sanitizeForCache).filter(Boolean);
    const sanitizedCurrent = sanitizeForCache(finalCloudPayload);
    if (sanitizedCurrent) filtered.unshift(sanitizedCurrent);
    localStorage.setItem('slant_user_posts_cache', JSON.stringify(filtered.slice(0, 30)));
  } catch (lsErr) {
    console.warn('Could not cache user draft to localStorage:', lsErr);
  }

  // 5. Track in local storage ID set & sync with cloud profile
  myCreatedPostIds.add(currentSynthesizedPost.id);
  localStorage.setItem('slant_my_posts', JSON.stringify(Array.from(myCreatedPostIds)));
  syncUserMetadataToCloud();

  if (saveBtn) {
    saveBtn.disabled = false;
    saveBtn.classList.add('active');
  }
  if (saveLbl) saveLbl.textContent = 'Saved';
  if (bottomSaveBtn) {
    bottomSaveBtn.disabled = false;
    bottomSaveBtn.innerHTML = isChronicle ? '<span>📔 Save to My Diary</span>' : '<span>🔖 Save Draft</span>';
  }

  // Graduate active Step 1 form draft since the 3-poster deck is now saved
  if (typeof clearActiveFormDraftAfterSynthesis === 'function') {
    clearActiveFormDraftAfterSynthesis();
  }

  // 6. Merge & sort chronologically into allPosts
  mergeAndSortPosts([currentSynthesizedPost]);
  updateAuthUI();
  if (isChronicle) {
    selectCategory(asDraftOnly ? 'drafts' : 'daily_chronicles');
  } else {
    renderFeed();
  }

  // 7. Close modal & reset state & notify user
  closeCreatorModal(true);
  resetCreatorState();
  showTemporaryToast(isChronicle
    ? (asDraftOnly
      ? '🔖 Saved to My Drafts! You can keep editing it anytime before saving to your Diary Calendar.'
      : '📔 Saved to My Diary! AES-256 Encrypted & added to your Diary Calendar.')
    : (savedSeriesObj
      ? `🔒 Saved privately to Series "${savedSeriesObj.title}"! Visible only to you (tap Publish anytime).`
      : '🔒 Saved as private draft! Visible only to you in your Feed & Drafts.'));
}

async function publishSynthesizedPost() {
  if (!currentSynthesizedPost) return;
  if (isChronicleModePost(currentSynthesizedPost)) {
    return saveSynthesizedPost();
  }

  const publishBtn = document.getElementById('publishBtn');
  const actionPublishBtn = document.getElementById('step3PublishActionBtn');
  const actionPublishLbl = document.getElementById('step3PublishActionLabel');
  if (publishBtn) {
    publishBtn.disabled = true;
    publishBtn.innerHTML = '<span>Publishing to Live Feed... ⏳</span>';
  }
  if (actionPublishBtn) actionPublishBtn.disabled = true;
  if (actionPublishLbl) actionPublishLbl.textContent = 'Publishing...';

  if (currentUser) {
    currentSynthesizedPost.user_id = currentUser.id;
    currentSynthesizedPost.userEmail = currentUser.email;
  }
  currentSynthesizedPost.createdAt = new Date().toISOString();
  currentSynthesizedPost.isUserCreated = true;
  currentSynthesizedPost.isDraft = false;
  currentSynthesizedPost.isPrivate = false;
  currentSynthesizedPost.isPubliclyPublished = true;
  currentSynthesizedPost.status = 'published';
  currentSynthesizedPost.allowComments = Boolean(creatorAllowComments);

  const publishedSeriesObj = (activeCreatorSeriesId && Array.isArray(creatorSeriesList))
    ? creatorSeriesList.find(s => s && s.id === activeCreatorSeriesId)
    : getPostSeriesInfo(currentSynthesizedPost);
  if (publishedSeriesObj) {
    currentSynthesizedPost.seriesId = publishedSeriesObj.id;
    currentSynthesizedPost.seriesTitle = publishedSeriesObj.title;
    if (!currentSynthesizedPost.generationInputs) currentSynthesizedPost.generationInputs = {};
    currentSynthesizedPost.generationInputs.seriesId = publishedSeriesObj.id;
    currentSynthesizedPost.generationInputs.seriesTitle = publishedSeriesObj.title;
    if (publishedSeriesObj.description) {
      currentSynthesizedPost.generationInputs.seriesDescription = publishedSeriesObj.description;
    }
    if (publishedSeriesObj.customCoverImage && publishedSeriesObj.customCoverImage.startsWith('http')) {
      currentSynthesizedPost.generationInputs.seriesCoverImage = publishedSeriesObj.customCoverImage;
    }
  }

  // 1. Clean & compress payload: store crisp ~60KB WebP so Supabase rows never trigger timeout
  const postToSave = { ...currentSynthesizedPost };
  if (publishedSeriesObj) {
    postToSave.seriesId = publishedSeriesObj.id;
    postToSave.seriesTitle = publishedSeriesObj.title;
  }
  const savedSlantTake = currentSynthesizedPost.polishedCuratorTake || currentSynthesizedPost.generationInputs?.slantTake || currentSynthesizedPost.userSlantTake || '';
  if (savedSlantTake) {
    postToSave.polishedCuratorTake = savedSlantTake;
    postToSave.userSlantTake = savedSlantTake;
    if (!postToSave.generationInputs) postToSave.generationInputs = {};
    postToSave.generationInputs.slantTake = savedSlantTake;
  }
  if (currentSynthesizedPost.generationInputs) {
    postToSave.generationInputs = currentSynthesizedPost.generationInputs;
  }
  const activeDraftLedger = currentSynthesizedPost.sourceLedger || currentSourceLedger || postToSave.generationInputs?.sourceLedger || null;
  if (activeDraftLedger) {
    postToSave.sourceLedger = activeDraftLedger;
    if (!postToSave.generationInputs) postToSave.generationInputs = {};
    postToSave.generationInputs.sourceLedger = activeDraftLedger;
  }
  if (currentSynthesizedPost.contextProvided) {
    postToSave.contextProvided = currentSynthesizedPost.contextProvided;
  }
  if (currentSynthesizedPost.userSlantTake) {
    postToSave.userSlantTake = currentSynthesizedPost.userSlantTake;
  }
  if (currentSynthesizedPost.sourceContext) {
    postToSave.sourceContext = currentSynthesizedPost.sourceContext;
  }
  postToSave.isDraft = false;
  postToSave.isPrivate = false;
  postToSave.isPubliclyPublished = true;
  postToSave.status = 'published';

  let hasUploadedPublicUrl = false;
  let rawPoster = currentSynthesizedPost.illustrationBase64 || currentSynthesizedPost.posterBase64 || currentSynthesizedPost.originalPhotoBase64;
  if (rawPoster && typeof rawPoster === 'string' && rawPoster.length > 50) {
    if (!rawPoster.startsWith('data:image/')) {
      const isPng = rawPoster.startsWith('iVBORw');
      rawPoster = `data:image/${isPng ? 'png' : 'jpeg'};base64,${rawPoster}`;
    }
    try {
      const compressed = await compressImageForCloud(rawPoster, 960, 0.85);
      const publicUrl = await uploadArtworkToSupabaseStorage(postToSave.id, compressed);
      if (publicUrl) {
        hasUploadedPublicUrl = true;
        postToSave.illustrationUrl = publicUrl;
        postToSave.aiIllustrationUrl = publicUrl;
        currentSynthesizedPost.illustrationUrl = publicUrl;
        currentSynthesizedPost.aiIllustrationUrl = publicUrl;
      }
    } catch (_) {}
  }

  if (!postToSave.illustrationUrl) {
    postToSave.illustrationUrl = `/posters/${postToSave.id}.png`;
    postToSave.aiIllustrationUrl = postToSave.illustrationUrl;
    postToSave.artworkPending = true;
  }

  // Purge heavy base64 fields only if direct cloud upload already succeeded, otherwise let backend upload it
  if (hasUploadedPublicUrl) {
    delete postToSave.posterBase64;
    delete postToSave.illustrationBase64;
  }
  delete postToSave.originalPhotoBase64;
  delete postToSave.sourceImageBase64;
  delete postToSave.catalystPhotoBase64;
  if (typeof postToSave.catalystPhoto === 'string' && postToSave.catalystPhoto.startsWith('data:image/')) {
    delete postToSave.catalystPhoto;
  }
  if (postToSave.generationInputs) {
    delete postToSave.generationInputs.sourceImageBase64;
    delete postToSave.generationInputs.catalystPhotoBase64;
    delete postToSave.generationInputs.innerVoiceImageBase64;
    if (typeof postToSave.generationInputs.catalystPhoto === 'string' && postToSave.generationInputs.catalystPhoto.startsWith('data:image/')) {
      delete postToSave.generationInputs.catalystPhoto;
    }
    if (typeof postToSave.generationInputs.referencePhotoUrl === 'string' && postToSave.generationInputs.referencePhotoUrl.startsWith('data:image/')) {
      delete postToSave.generationInputs.referencePhotoUrl;
    }
  }

  // 2. Primary cloud save: POST to /api/posts
  let savedToCloud = false;
  try {
    const resp = await fetch('/api/posts', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(postToSave)
    });

    if (resp.ok) {
      savedToCloud = true;
    } else {
      console.warn('Backend /api/posts returned status:', resp.status);
    }
  } catch (err) {
    console.warn('Backend publish call error:', err);
  }

  // 3. Resilient fallback: Direct Supabase write if /api/posts failed or was bypassed
  if (!savedToCloud) {
    try {
      const supaResp = await fetch(`${SUPABASE_URL}/rest/v1/posts`, {
        method: 'POST',
        headers: {
          'apikey': SUPABASE_KEY,
          'Authorization': `Bearer ${SUPABASE_KEY}`,
          'Content-Type': 'application/json',
          'Prefer': 'resolution=merge-duplicates'
        },
        body: JSON.stringify({ id: postToSave.id, data: postToSave })
      });
      if (supaResp.ok) {
        savedToCloud = true;
      } else {
        console.warn('Direct Supabase write status:', supaResp.status);
      }
    } catch (supaErr) {
      console.error('Direct Supabase write error:', supaErr);
    }
  }

  // 4. Local storage persistent backup: Save post so stories NEVER vanish across reloads/sign-ins
  try {
    const sanitizeForCache = (p) => {
      if (!p) return null;
      const copy = { ...p };
      delete copy.originalPhotoBase64;
      delete copy.posterBase64;
      delete copy.sourceImageBase64;
      delete copy.catalystPhotoBase64;
      if (copy.illustrationBase64 && copy.illustrationBase64.length > 50000) {
        delete copy.illustrationBase64;
      }
      if (!copy.illustrationUrl) {
        copy.illustrationUrl = `${SUPABASE_URL}/storage/v1/object/public/posters/${copy.id}.webp`;
        copy.aiIllustrationUrl = copy.illustrationUrl;
      }
      return copy;
    };

    const localPosts = JSON.parse(localStorage.getItem('slant_user_posts_cache') || '[]');
    const filtered = localPosts.filter(p => p && p.id !== currentSynthesizedPost.id).map(sanitizeForCache).filter(Boolean);
    const sanitizedCurrent = sanitizeForCache(currentSynthesizedPost);
    if (sanitizedCurrent) filtered.unshift(sanitizedCurrent);
    localStorage.setItem('slant_user_posts_cache', JSON.stringify(filtered.slice(0, 30)));
  } catch (lsErr) {
    console.warn('Could not cache user post to localStorage:', lsErr);
  }

  // 5. Track in local storage ID set & sync with cloud profile
  myCreatedPostIds.add(currentSynthesizedPost.id);
  localStorage.setItem('slant_my_posts', JSON.stringify(Array.from(myCreatedPostIds)));
  syncUserMetadataToCloud();

  // Update Step 3 Publish button state
  if (actionPublishBtn) {
    actionPublishBtn.disabled = false;
    actionPublishBtn.classList.add('active');
  }
  if (actionPublishLbl) actionPublishLbl.textContent = 'Published';

  // Graduate active Step 1 form draft since the 3-poster deck is now published
  if (typeof clearActiveFormDraftAfterSynthesis === 'function') {
    clearActiveFormDraftAfterSynthesis();
  }

  // 6. Merge & sort chronologically, then render feed
  mergeAndSortPosts([currentSynthesizedPost]);
  updateBadge(true, `Live Feed (${allPosts.length} posts)`);
  updateAuthUI();
  renderFeed();

  // 7. Close modal & reset state & show toast
  const justPublishedPost = { ...currentSynthesizedPost };
  closeCreatorModal(true);
  resetCreatorState();
  showTemporaryToast(publishedSeriesObj
    ? `🚀 Published to Live Feed & Series "${publishedSeriesObj.title}"!`
    : '✨ Published! Your 3-poster Slant is live on slant.today');
  setTimeout(() => {
    if (typeof maybeShowPostPublishMicroPulse === 'function') {
      maybeShowPostPublishMicroPulse(justPublishedPost);
    }
  }, 1600);

  // Scroll smoothly to top so user sees their new post
  window.scrollTo({ top: 0, behavior: 'smooth' });

  if (publishBtn) {
    publishBtn.disabled = false;
    publishBtn.innerHTML = '<span>Publish to slant.today 🚀</span>';
  }
}

window._feedLoaderStartTime = Date.now();
try {
  if (!window._feedVideoLoop) {
    window._feedVideoLoop = setupSeamlessVideoLoop('feedLoaderVideoWrap', 'feedInitialVideoA', 'feedInitialVideoB', 0.45);
  }
  if (window._feedVideoLoop) {
    window._feedVideoLoop.start();
  } else {
    const initVid = document.getElementById('feedInitialVideoA') || document.getElementById('feedInitialVideo');
    if (initVid) {
      initVid.currentTime = 0;
      const playPromise = initVid.play();
      if (playPromise !== undefined) playPromise.catch(() => {});
    }
  }
} catch (_) {}
setTimeout(() => dismissInitialFeedLoader(true), 25000); // 25s absolute safety fallback

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}
